INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u4-C1','math',3,1,'u4',2,'곱셈의 뜻과 두 자리 곱셈 상황 — 같은 수를 여러 번 더하는 것을 곱셈식으로 나타내고, 몇십몇씩 몇 번(몇 묶음)인 생활 상황을 (두 자리 수) × (한 자리 수) 곱셈식으로 세우기',ARRAY['4수01-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u4-C2','math',3,1,'u4',2,'(몇십) × (몇) — 십 모형과 곱셈구구로 (몇십) × (몇)이 (몇) × (몇)의 10배임을 알고 계산하기',ARRAY['4수01-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u4-C3','math',3,1,'u4',3,'(몇십몇) × (몇) 올림 없음 — 몇십몇을 몇십과 몇으로 나누어 각각 곱한 뒤 더하고, 세로셈에서 일의 자리·십의 자리 곱을 제자리에 쓰기',ARRAY['4수01-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u4-C4','math',3,1,'u4',3,'곱셈 어림하기 — 곱해지는 수를 가까운 몇십으로 어림해 곱의 크기를 미리 알고, 계산한 답이 어림한 값과 가까운지 견주어 맞는지 확인하기',ARRAY['4수01-08']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u4-C5','math',3,1,'u4',4,'십의 자리에서 올림이 있는 (몇십몇) × (몇) — 십의 자리 곱이 10을 넘으면 백의 자리로 올려 세 자리 곱을 바르게 쓰기',ARRAY['4수01-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u4-C6','math',3,1,'u4',5,'일의 자리에서 올림이 있는 (몇십몇) × (몇) — 일의 자리 곱이 10을 넘으면 십의 자리로 올리고, 십의 자리 곱을 한 뒤 올림한 수를 더하기',ARRAY['4수01-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u4-C7','math',3,1,'u4',6,'올림이 두 번 있는 (몇십몇) × (몇) — 일의 자리 올림은 십의 자리 곱에 더하고, 십의 자리에서 생긴 올림은 백의 자리에 써서 세 자리 곱 구하기',ARRAY['4수01-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u4-C8','math',3,1,'u4',7,'곱셈으로 문제 해결하기 — 반복되는 같은 모양·묶음에서 한 묶음 수를 (나누어 세어) 구하고, 묶음 수만큼 곱해 전체를 구하며 두 단계 문제 해결하기',ARRAY['4수01-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X01','math',3,'u4',ARRAY['M3-1-u4-C1','M3-1-u4-C8']::text[],'같은 수를 여러 번 더하거나 몇씩 몇 묶음인 상황에서 곱셈 대신 두 수를 더한다(27회씩 5번 → 27 + 5)','「씩 ~번」은 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X02','math',3,'u4',ARRAY['M3-1-u4-C2']::text[],'(몇십) × (몇)에서 0을 빠뜨려 (몇) × (몇)의 곱만 쓴다(20 × 3 = 6)','십 모형 6개는 60') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X03','math',3,'u4',ARRAY['M3-1-u4-C2','M3-1-u4-C5']::text[],'(몇십) × (몇)에 0을 하나 더 붙이거나 곱을 한 자리 높여 쓴다(20 × 3 = 600)','10배는 0 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X04','math',3,'u4',ARRAY['M3-1-u4-C3','M3-1-u4-C5','M3-1-u4-C6','M3-1-u4-C7']::text[],'두 자리 중 한 자리만 곱하고 다른 자리 숫자는 그대로 내려 쓴다(21 × 4 = 24, 81)','일의 자리도 십의 자리도 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X05','math',3,'u4',ARRAY['M3-1-u4-C3']::text[],'자리별 곱을 제자리에 쓰지 않고 순서를 바꾸어 나란히 쓴다(32 × 3 → 69)','십의 자리 곱은 왼쪽에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X06','math',3,'u4',ARRAY['M3-1-u4-C3','M3-1-u4-C5','M3-1-u4-C6','M3-1-u4-C7','M3-1-u4-C8']::text[],'나누어 곱한 두 부분 곱 중 하나만 답으로 쓰고 더하지 않는다(21 × 4 = 80)','몇십 × 몇 + 몇 × 몇') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X07','math',3,'u4',ARRAY['M3-1-u4-C5','M3-1-u4-C7']::text[],'십의 자리 곱이 10을 넘을 때 백의 자리로 올림한 수를 빠뜨린다(43 × 3 = 29)','십의 자리 곱 12는 백 1, 십 2') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X08','math',3,'u4',ARRAY['M3-1-u4-C6','M3-1-u4-C7']::text[],'일의 자리에서 올림한 수를 십의 자리 곱에 더하지 않는다(49 × 2 = 88)','올림한 수에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X09','math',3,'u4',ARRAY['M3-1-u4-C6','M3-1-u4-C7']::text[],'올림한 수를 십의 자리 숫자에 먼저 더한 뒤 곱한다(19 × 4 → (1 + 3) × 4)','곱한 다음에 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X10','math',3,'u4',ARRAY['M3-1-u4-C6','M3-1-u4-C7']::text[],'자리별 곱을 올림하지 않고 그대로 이어 붙여 쓴다(35 × 5 → 1525)','10이 넘으면 윗자리로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X11','math',3,'u4',ARRAY['M3-1-u4-C2','M3-1-u4-C3','M3-1-u4-C5','M3-1-u4-C6','M3-1-u4-C7','M3-1-u4-C8']::text[],'곱셈구구나 부분 곱을 더하는 계산에서 실수해 곱이 조금 크거나 작다','어림한 값과 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X12','math',3,'u4',ARRAY['M3-1-u4-C4']::text[],'어림할 때 가까운 몇십이 아닌 쪽으로 어림하거나 어림한 수에 곱하지 않는다','일의 자리가 5보다 작으면 내려') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X13','math',3,'u4',ARRAY['M3-1-u4-C1','M3-1-u4-C8']::text[],'상황에서 곱해지는 수(한 묶음 수)와 곱하는 수(묶음 수)를 잘못 골라 식을 세운다(27 × 27, 5 × 5)','한 묶음 수 × 묶음 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X14','math',3,'u4',ARRAY['M3-1-u4-C8']::text[],'반복되는 모양에서 한 묶음 수를 잘못 세거나 나누어 센 부분을 다 더하지 않는다','나눈 부분을 모두 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u4-X15','math',3,'u4',ARRAY['M3-1-u4-C1','M3-1-u4-C2','M3-1-u4-C3','M3-1-u4-C4','M3-1-u4-C5','M3-1-u4-C6','M3-1-u4-C7','M3-1-u4-C8']::text[],'묻는 말을 거꾸로 읽는다 — 틀린↔바른, 아닌↔맞는','물음의 「틀린·아닌」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#1','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C1',1,'mc','auto','21 + 21 + 21을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":1,"concept":"M3-1-u4-C1","difficulty":1,"kind":"mc","stem":"21 + 21 + 21을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"21 × 3","correct":true},{"t":"21 + 3","mis":"M3-1-u4-X01"},{"t":"3 × 3","mis":"M3-1-u4-X13"},{"t":"21 × 21","mis":"M3-1-u4-X13"}],"explanation":["같은 수 21을 3번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","21을 3번 → 21 × 3."],"variant_rule":{"alt":[{"stem":"11 + 11 + 11을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"11 × 3","correct":true},{"t":"11 + 3","mis":"M3-1-u4-X01"},{"t":"3 × 3","mis":"M3-1-u4-X13"},{"t":"11 × 11","mis":"M3-1-u4-X13"}],"explanation":["같은 수 11을 3번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","11을 3번 → 11 × 3."],"asset":null},{"stem":"21 + 21 + 21 + 21을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"21 × 4","correct":true},{"t":"21 + 4","mis":"M3-1-u4-X01"},{"t":"4 × 4","mis":"M3-1-u4-X13"},{"t":"21 × 21","mis":"M3-1-u4-X13"}],"explanation":["같은 수 21을 4번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","21을 4번 → 21 × 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#2','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C2',1,'mc','auto','2 × 4 = 8이에요. 그러면 20 × 4는 얼마인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X03','M3-1-u4-X11']::text[],true,'{"seq":2,"concept":"M3-1-u4-C2","difficulty":1,"kind":"mc","stem":"2 × 4 = 8이에요. 그러면 20 × 4는 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8","mis":"M3-1-u4-X02"},{"t":"800","mis":"M3-1-u4-X03"},{"t":"90","mis":"M3-1-u4-X11"}],"explanation":["20은 2의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","8의 10배 — 20 × 4 = 80이에요."],"variant_rule":{"alt":[{"stem":"3 × 2 = 6이에요. 그러면 30 × 2는 얼마인가요?","options":[{"t":"60","correct":true},{"t":"6","mis":"M3-1-u4-X02"},{"t":"600","mis":"M3-1-u4-X03"},{"t":"70","mis":"M3-1-u4-X11"}],"explanation":["30은 3의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","6의 10배 — 30 × 2 = 60이에요."],"asset":null},{"stem":"1 × 8 = 8이에요. 그러면 10 × 8은 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8","mis":"M3-1-u4-X02"},{"t":"800","mis":"M3-1-u4-X03"},{"t":"90","mis":"M3-1-u4-X11"}],"explanation":["10은 1의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","8의 10배 — 10 × 8 = 80이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#3','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C2',1,'sa','auto','30 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C2","difficulty":1,"kind":"sa","stem":"30 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["3 × 2 = 6이에요.","30은 3의 10배라 곱도 10배예요.","30 × 2 = 60이에요."],"variant_rule":{"alt":[{"stem":"20 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["2 × 3 = 6이에요.","20은 2의 10배라 곱도 10배예요.","20 × 3 = 60이에요."],"asset":null},{"stem":"20 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["2 × 4 = 8이에요.","20은 2의 10배라 곱도 10배예요.","20 × 4 = 80이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#4','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C1',1,'mc','auto','곱셈은 무엇을 간단히 나타낸 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X15']::text[],true,'{"seq":4,"concept":"M3-1-u4-C1","difficulty":1,"kind":"mc","stem":"곱셈은 무엇을 간단히 나타낸 것인가요?","options":[{"t":"같은 수를 여러 번 더한 것","correct":true},{"t":"서로 다른 수를 더한 것","mis":"M3-1-u4-X01"},{"t":"큰 수에서 작은 수를 뺀 것","mis":"M3-1-u4-X01"},{"t":"똑같이 나눈 것","mis":"M3-1-u4-X15"}],"explanation":["곱셈은 같은 수를 여러 번 더한 것을 간단히 나타내요.","「몇씩 몇 번」에서 앞의 수는 한 묶음 수, 뒤의 수는 묶음 수예요.","이번 단원은 곱해지는 수가 두 자리인 곱셈을 배워요."],"variant_rule":{"alt":[{"stem":"「줄넘기를 27회씩 5번 했어요.」에서 27은 무엇을 나타내나요?","options":[{"t":"한 번에 넘은 횟수","correct":true},{"t":"줄넘기를 한 번 수","mis":"M3-1-u4-X13"},{"t":"모두 넘은 횟수","mis":"M3-1-u4-X13"},{"t":"남은 횟수","mis":"M3-1-u4-X15"}],"explanation":["곱셈은 같은 수를 여러 번 더한 것을 간단히 나타내요.","「몇씩 몇 번」에서 앞의 수는 한 묶음 수, 뒤의 수는 묶음 수예요.","이번 단원은 곱해지는 수가 두 자리인 곱셈을 배워요."],"asset":null},{"stem":"이번 단원에서 새로 배우는 곱셈은 어느 것인가요?","options":[{"t":"(몇십몇) × (몇)","correct":true},{"t":"(몇) × (몇) 곱셈구구","mis":"M3-1-u4-X15"},{"t":"(몇) + (몇) 덧셈","mis":"M3-1-u4-X01"},{"t":"(몇) ÷ (몇) 나눗셈","mis":"M3-1-u4-X15"}],"explanation":["곱셈은 같은 수를 여러 번 더한 것을 간단히 나타내요.","「몇씩 몇 번」에서 앞의 수는 한 묶음 수, 뒤의 수는 묶음 수예요.","이번 단원은 곱해지는 수가 두 자리인 곱셈을 배워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#5','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C1',2,'mc','auto','줄넘기를 한 번에 27회씩 5번 했어요. 모두 몇 회 했는지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":5,"concept":"M3-1-u4-C1","difficulty":2,"kind":"mc","stem":"줄넘기를 한 번에 27회씩 5번 했어요. 모두 몇 회 했는지 구하는 식은 어느 것인가요?","options":[{"t":"27 × 5","correct":true},{"t":"27 + 5","mis":"M3-1-u4-X01"},{"t":"5 × 5","mis":"M3-1-u4-X13"},{"t":"27 × 27","mis":"M3-1-u4-X13"}],"explanation":["27회씩 5번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 27 × 5."],"variant_rule":{"alt":[{"stem":"한 상자에 귤이 37개씩 4상자 있어요. 귤은 모두 몇 개인지 구하는 식은 어느 것인가요?","options":[{"t":"37 × 4","correct":true},{"t":"37 + 4","mis":"M3-1-u4-X01"},{"t":"4 × 4","mis":"M3-1-u4-X13"},{"t":"37 × 37","mis":"M3-1-u4-X13"}],"explanation":["37개씩 4번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 37 × 4."],"asset":null},{"stem":"윗몸 일으키기를 하루에 79개씩 7일 동안 했어요. 모두 몇 개 했는지 구하는 식은 어느 것인가요?","options":[{"t":"79 × 7","correct":true},{"t":"79 + 7","mis":"M3-1-u4-X01"},{"t":"7 × 7","mis":"M3-1-u4-X13"},{"t":"79 × 79","mis":"M3-1-u4-X13"}],"explanation":["79개씩 7번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 79 × 7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#6','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C2',2,'ox','auto','20 × 3 = 6이에요.',ARRAY['M3-1-u4-X02']::text[],true,'{"seq":6,"concept":"M3-1-u4-C2","difficulty":2,"kind":"ox","stem":"20 × 3 = 6이에요.","answer":"X","reason_options":[{"t":"20 × 3은 2 × 3의 10배라서","correct":true},{"t":"2 × 3 = 6이니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"mis":"M3-1-u4-X02","explanation":["2 × 3 = 6이에요.","20은 2의 10배라 곱도 10배 — 60이에요.","0을 빠뜨리면 십 모형 6개를 낱개 6개로 센 셈이에요."],"variant_rule":{"alt":[{"stem":"60 × 7 = 42예요.","answer":"X","reason_options":[{"t":"60 × 7은 6 × 7의 10배라서","correct":true},{"t":"6 × 7 = 42니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["6 × 7 = 42예요.","60은 6의 10배라 곱도 10배 — 420이에요.","0을 빠뜨리면 십 모형 42개를 낱개 42개로 센 셈이에요."],"asset":null},{"stem":"70 × 5 = 35예요.","answer":"X","reason_options":[{"t":"70 × 5는 7 × 5의 10배라서","correct":true},{"t":"7 × 5 = 35니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["7 × 5 = 35예요.","70은 7의 10배라 곱도 10배 — 350이에요.","0을 빠뜨리면 십 모형 35개를 낱개 35개로 센 셈이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#7','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C2',2,'mc','auto','십 모형이 3개씩 4묶음 있어요. 모두 얼마를 나타내나요? 이것은 30 × 4의 곱이에요.',ARRAY['M3-1-u4-X02','M3-1-u4-X03','M3-1-u4-X01']::text[],true,'{"seq":7,"concept":"M3-1-u4-C2","difficulty":2,"kind":"mc","stem":"십 모형이 3개씩 4묶음 있어요. 모두 얼마를 나타내나요? 이것은 30 × 4의 곱이에요.","options":[{"t":"120","correct":true},{"t":"12","mis":"M3-1-u4-X02"},{"t":"1200","mis":"M3-1-u4-X03"},{"t":"7","mis":"M3-1-u4-X01"}],"explanation":["십 모형은 하나가 10이에요.","3개씩 4묶음 = 십 모형 12개.","십 모형 12개는 120 — 30 × 4 = 120이에요."],"variant_rule":{"alt":[{"stem":"십 모형이 4개씩 2묶음 있어요. 모두 얼마를 나타내나요? 이것은 40 × 2의 곱이에요.","options":[{"t":"80","correct":true},{"t":"8","mis":"M3-1-u4-X02"},{"t":"800","mis":"M3-1-u4-X03"},{"t":"6","mis":"M3-1-u4-X01"}],"explanation":["십 모형은 하나가 10이에요.","4개씩 2묶음 = 십 모형 8개.","십 모형 8개는 80 — 40 × 2 = 80이에요."],"asset":null},{"stem":"십 모형이 9개씩 5묶음 있어요. 모두 얼마를 나타내나요? 이것은 90 × 5의 곱이에요.","options":[{"t":"450","correct":true},{"t":"45","mis":"M3-1-u4-X02"},{"t":"4500","mis":"M3-1-u4-X03"},{"t":"14","mis":"M3-1-u4-X01"}],"explanation":["십 모형은 하나가 10이에요.","9개씩 5묶음 = 십 모형 45개.","십 모형 45개는 450 — 90 × 5 = 450이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#8','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C2',2,'mc','auto','훌라후프를 한 번에 20바퀴씩 4번 돌렸어요. 모두 몇 바퀴 돌렸나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X02','M3-1-u4-X03']::text[],true,'{"seq":8,"concept":"M3-1-u4-C2","difficulty":2,"kind":"mc","stem":"훌라후프를 한 번에 20바퀴씩 4번 돌렸어요. 모두 몇 바퀴 돌렸나요?","options":[{"t":"80바퀴","correct":true},{"t":"24바퀴","mis":"M3-1-u4-X01"},{"t":"8바퀴","mis":"M3-1-u4-X02"},{"t":"800바퀴","mis":"M3-1-u4-X03"}],"explanation":["20바퀴씩 4번(묶음) — 곱셈식 20 × 4로 세워요.","2 × 4 = 8의 10배예요.","20 × 4 = 80 — 모두 80바퀴예요."],"variant_rule":{"alt":[{"stem":"색종이를 한 명에게 70장씩 6명에게 나누어 주었어요. 모두 몇 장인가요?","options":[{"t":"420장","correct":true},{"t":"76장","mis":"M3-1-u4-X01"},{"t":"42장","mis":"M3-1-u4-X02"},{"t":"4200장","mis":"M3-1-u4-X03"}],"explanation":["70장씩 6번(묶음) — 곱셈식 70 × 6으로 세워요.","7 × 6 = 42의 10배예요.","70 × 6 = 420 — 모두 420장이에요."],"asset":null},{"stem":"체조를 하루에 20분씩 3일 동안 했어요. 모두 몇 분 했나요?","options":[{"t":"60분","correct":true},{"t":"23분","mis":"M3-1-u4-X01"},{"t":"6분","mis":"M3-1-u4-X02"},{"t":"600분","mis":"M3-1-u4-X03"}],"explanation":["20분씩 3번(묶음) — 곱셈식 20 × 3으로 세워요.","2 × 3 = 6의 10배예요.","20 × 3 = 60 — 모두 60분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#9','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C2',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u4-C2","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"40 × 2","r":"80"},{"l":"50 × 6","r":"300"},{"l":"80 × 5","r":"400"}],"mis":"M3-1-u4-X02","explanation":["(몇) × (몇)의 10배를 구해요.","40 × 2 = 80, 50 × 6 = 300, 80 × 5 = 400.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"70 × 2","r":"140"},{"l":"40 × 6","r":"240"},{"l":"50 × 9","r":"450"}],"explanation":["(몇) × (몇)의 10배를 구해요.","70 × 2 = 140, 40 × 6 = 240, 50 × 9 = 450.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"70 × 5","r":"350"},{"l":"70 × 4","r":"280"},{"l":"40 × 6","r":"240"}],"explanation":["(몇) × (몇)의 10배를 구해요.","70 × 5 = 350, 70 × 4 = 280, 40 × 6 = 240.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_basic#10','math',3,1,'u4','L02','g3_1_math_u4_L02_basic','lesson_basic','M3-1-u4-C2',3,'error','auto','30 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X15']::text[],true,'{"seq":10,"concept":"M3-1-u4-C2","difficulty":3,"kind":"error","stem":"30 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「30 × 3 = 9야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"서윤 — 「3 × 3 = 9의 10배야」","mis":"M3-1-u4-X15"},{"t":"도윤 — 「십 모형 3개씩 3묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["3 × 3 = 9의 10배예요.","30 × 3 = 90이에요.","하린은 0을 빠뜨려 9라고 말했어요."],"variant_rule":{"alt":[{"stem":"20 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「20 × 8 = 16이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"하린 — 「2 × 8 = 16의 10배야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「십 모형 2개씩 8묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["2 × 8 = 16의 10배예요.","20 × 8 = 160이에요.","도윤은 0을 빠뜨려 16이라고 말했어요."],"asset":null},{"stem":"50 × 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「50 × 5 = 25야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"태오 — 「5 × 5 = 25의 10배야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「십 모형 5개씩 5묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["5 × 5 = 25의 10배예요.","50 × 5 = 250이에요.","도윤은 0을 빠뜨려 25라고 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#1','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C1',2,'ox','auto','14 × 3은 14를 3번 더한 것과 같아요.',ARRAY['M3-1-u4-X01']::text[],true,'{"seq":1,"concept":"M3-1-u4-C1","difficulty":2,"kind":"ox","stem":"14 × 3은 14를 3번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"곱셈은 같은 수를 여러 번 더한 것을 간단히 나타내서","correct":true},{"t":"곱셈과 덧셈은 아무 사이도 아니라서","mis":"M3-1-u4-X01"}],"mis":"M3-1-u4-X01","explanation":["14 × 3은 14씩 3번이에요.","14 + 14 + 14.","그래서 맞아요 — 곱셈은 같은 수 여러 번 더하기를 간단히 나타내요."],"variant_rule":{"alt":[{"stem":"26 × 2는 26을 2번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"곱셈은 같은 수를 여러 번 더한 것을 간단히 나타내서","correct":true},{"t":"곱셈과 덧셈은 아무 사이도 아니라서","mis":"M3-1-u4-X01"}],"explanation":["26 × 2는 26씩 2번이에요.","26 + 26.","그래서 맞아요 — 곱셈은 같은 수 여러 번 더하기를 간단히 나타내요."],"asset":null},{"stem":"26 × 3은 26을 3번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"곱셈은 같은 수를 여러 번 더한 것을 간단히 나타내서","correct":true},{"t":"곱셈과 덧셈은 아무 사이도 아니라서","mis":"M3-1-u4-X01"}],"explanation":["26 × 3은 26씩 3번이에요.","26 + 26 + 26.","그래서 맞아요 — 곱셈은 같은 수 여러 번 더하기를 간단히 나타내요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#2','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C2',2,'sa','auto','4 × 2 = 8이에요. 그러면 40 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u4-C2","difficulty":2,"kind":"sa","stem":"4 × 2 = 8이에요. 그러면 40 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["40은 4의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","8의 10배 — 40 × 2 = 80이에요."],"variant_rule":{"alt":[{"stem":"3 × 3 = 9예요. 그러면 30 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["30은 3의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","9의 10배 — 30 × 3 = 90이에요."],"asset":null},{"stem":"2 × 3 = 6이에요. 그러면 20 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["20은 2의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","6의 10배 — 20 × 3 = 60이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#3','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C2',3,'mc','auto','60 × 7은 얼마인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X03','M3-1-u4-X11']::text[],true,'{"seq":3,"concept":"M3-1-u4-C2","difficulty":3,"kind":"mc","stem":"60 × 7은 얼마인가요?","options":[{"t":"420","correct":true},{"t":"42","mis":"M3-1-u4-X02"},{"t":"4200","mis":"M3-1-u4-X03"},{"t":"430","mis":"M3-1-u4-X11"}],"explanation":["6 × 7 = 42예요.","60은 6의 10배라 곱도 10배예요.","60 × 7 = 420이에요."],"variant_rule":{"alt":[{"stem":"90 × 8은 얼마인가요?","options":[{"t":"720","correct":true},{"t":"72","mis":"M3-1-u4-X02"},{"t":"7200","mis":"M3-1-u4-X03"},{"t":"730","mis":"M3-1-u4-X11"}],"explanation":["9 × 8 = 72예요.","90은 9의 10배라 곱도 10배예요.","90 × 8 = 720이에요."],"asset":null},{"stem":"50 × 4는 얼마인가요?","options":[{"t":"200","correct":true},{"t":"20","mis":"M3-1-u4-X02"},{"t":"2000","mis":"M3-1-u4-X03"},{"t":"210","mis":"M3-1-u4-X11"}],"explanation":["5 × 4 = 20이에요.","50은 5의 10배라 곱도 10배예요.","50 × 4 = 200이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#4','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C2',3,'sa','auto','□ × 3 = 90 — □에 알맞은 몇십을 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u4-C2","difficulty":3,"kind":"sa","stem":"□ × 3 = 90 — □에 알맞은 몇십을 쓰세요.","answer":["30"],"explanation":["90은 3 × 3의 10배예요.","3 × 3 = 9이니 □는 3의 10배예요.","□ = 30 — 30 × 3 = 90이에요."],"variant_rule":{"alt":[{"stem":"□ × 9 = 720 — □에 알맞은 몇십을 쓰세요.","answer":["80"],"explanation":["720은 8 × 9의 10배예요.","8 × 9 = 72이니 □는 8의 10배예요.","□ = 80 — 80 × 9 = 720이에요."],"asset":null},{"stem":"□ × 7 = 560 — □에 알맞은 몇십을 쓰세요.","answer":["80"],"explanation":["560은 8 × 7의 10배예요.","8 × 7 = 56이니 □는 8의 10배예요.","□ = 80 — 80 × 7 = 560이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#5','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C2',3,'mc','auto','50 × 4는 5 × 4의 몇 배인가요?',ARRAY['M3-1-u4-X03','M3-1-u4-X11','M3-1-u4-X02']::text[],true,'{"seq":5,"concept":"M3-1-u4-C2","difficulty":3,"kind":"mc","stem":"50 × 4는 5 × 4의 몇 배인가요?","options":[{"t":"10배","correct":true},{"t":"100배","mis":"M3-1-u4-X03"},{"t":"2배","mis":"M3-1-u4-X11"},{"t":"같아요","mis":"M3-1-u4-X02"}],"explanation":["50은 5의 10배예요.","곱해지는 수가 10배면 곱도 10배.","5 × 4 = 20, 50 × 4 = 200 — 10배예요."],"variant_rule":{"alt":[{"stem":"70 × 4는 7 × 4의 몇 배인가요?","options":[{"t":"10배","correct":true},{"t":"100배","mis":"M3-1-u4-X03"},{"t":"2배","mis":"M3-1-u4-X11"},{"t":"같아요","mis":"M3-1-u4-X02"}],"explanation":["70은 7의 10배예요.","곱해지는 수가 10배면 곱도 10배.","7 × 4 = 28, 70 × 4 = 280 — 10배예요."],"asset":null},{"stem":"20 × 7은 2 × 7의 몇 배인가요?","options":[{"t":"10배","correct":true},{"t":"100배","mis":"M3-1-u4-X03"},{"t":"2배","mis":"M3-1-u4-X11"},{"t":"같아요","mis":"M3-1-u4-X02"}],"explanation":["20은 2의 10배예요.","곱해지는 수가 10배면 곱도 10배.","2 × 7 = 14, 20 × 7 = 140 — 10배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#6','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C2',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 70 × 3 ○ 90 × 2',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":6,"concept":"M3-1-u4-C2","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 70 × 3 ○ 90 × 2","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["70 × 3 = 210이에요.","90 × 2 = 180이에요.","210 > 180 — 알맞은 것은 >예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 50 × 9 ○ 60 × 8","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["50 × 9 = 450이에요.","60 × 8 = 480이에요.","450 < 480 — 알맞은 것은 <예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 60 × 2 ○ 30 × 3","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["60 × 2 = 120이에요.","30 × 3 = 90이에요.","120 > 90 — 알맞은 것은 >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#7','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C2',3,'error','auto','80 × 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X15']::text[],true,'{"seq":7,"concept":"M3-1-u4-C2","difficulty":3,"kind":"error","stem":"80 × 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「80 × 6 = 48이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"시우 — 「8 × 6 = 48의 10배야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「십 모형 8개씩 6묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["8 × 6 = 48의 10배예요.","80 × 6 = 480이에요.","서윤은 0을 빠뜨려 48이라고 말했어요."],"variant_rule":{"alt":[{"stem":"80 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「80 × 7 = 56이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"하랑 — 「8 × 7 = 56의 10배야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「십 모형 8개씩 7묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["8 × 7 = 56의 10배예요.","80 × 7 = 560이에요.","은우는 0을 빠뜨려 56이라고 말했어요."],"asset":null},{"stem":"20 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「20 × 8 = 16이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"하랑 — 「2 × 8 = 16의 10배야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「십 모형 2개씩 8묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["2 × 8 = 16의 10배예요.","20 × 8 = 160이에요.","도윤은 0을 빠뜨려 16이라고 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#8','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C2',4,'essay','teacher','20 × 3이 얼마인지 십 모형과 곱셈구구를 이용해 두 가지 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u4-C2","difficulty":4,"kind":"essay","stem":"20 × 3이 얼마인지 십 모형과 곱셈구구를 이용해 두 가지 방법으로 설명해 보세요.","answer_guide":{"answer":"예: ① 십 모형 2개씩 3묶음이면 십 모형 6개이고, 십 모형 6개는 60이다. ② 2 × 3 = 6이고 20은 2의 10배이므로 곱도 6의 10배인 60이다. 그래서 20 × 3 = 60이다.","scoring_points":["십 모형 6개 = 60으로 설명했는가","2 × 3 = 6의 10배로 설명했는가","20 × 3 = 60을 구했는가"]},"explanation":["십 모형 2개씩 3묶음 = 6개 = 60.","2 × 3 = 6의 10배 = 60.","20 × 3 = 60."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#9','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C1',4,'essay','teacher','「운동을 30분씩 3일 했어요.」와 「운동을 30분 하고 3분 더 했어요.」에 알맞은 식을 각각 쓰고, 두 식이 어떻게 다른지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u4-C1","difficulty":4,"kind":"essay","stem":"「운동을 30분씩 3일 했어요.」와 「운동을 30분 하고 3분 더 했어요.」에 알맞은 식을 각각 쓰고, 두 식이 어떻게 다른지 설명해 보세요.","answer_guide":{"answer":"예: 첫째는 30분씩 3번이므로 30 × 3 = 90(분), 둘째는 30분에 3분을 더하므로 30 + 3 = 33(분)이다. 같은 수를 여러 번 더하는 상황은 곱셈, 더 보태는 상황은 덧셈이다.","scoring_points":["30 × 3 = 90을 썼는가","30 + 3 = 33을 썼는가","「씩 몇 번」은 곱셈, 더 보태기는 덧셈이라고 구별했는가"]},"explanation":["30분씩 3일 → 30 × 3 = 90.","30분 + 3분 → 33.","「씩 ~번」이면 곱셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L02_challenge#10','math',3,1,'u4','L02','g3_1_math_u4_L02_challenge','lesson_challenge','M3-1-u4-C2',4,'mc','auto','한 봉지에 사탕이 90개씩 8봉지 있어요. 사탕은 모두 몇 개인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X02','M3-1-u4-X03']::text[],true,'{"seq":10,"concept":"M3-1-u4-C2","difficulty":4,"kind":"mc","stem":"한 봉지에 사탕이 90개씩 8봉지 있어요. 사탕은 모두 몇 개인가요?","options":[{"t":"720개","correct":true},{"t":"98개","mis":"M3-1-u4-X01"},{"t":"72개","mis":"M3-1-u4-X02"},{"t":"7200개","mis":"M3-1-u4-X03"}],"explanation":["90개씩 8번(묶음) — 곱셈식 90 × 8로 세워요.","9 × 8 = 72의 10배예요.","90 × 8 = 720 — 모두 720개예요."],"variant_rule":{"alt":[{"stem":"윗몸 일으키기를 하루에 50개씩 7일 동안 했어요. 모두 몇 개 했나요?","options":[{"t":"350개","correct":true},{"t":"57개","mis":"M3-1-u4-X01"},{"t":"35개","mis":"M3-1-u4-X02"},{"t":"3500개","mis":"M3-1-u4-X03"}],"explanation":["50개씩 7번(묶음) — 곱셈식 50 × 7로 세워요.","5 × 7 = 35의 10배예요.","50 × 7 = 350 — 모두 350개예요."],"asset":null},{"stem":"양치질을 한 달에 80번씩 7달 동안 빠짐없이 했어요. 모두 몇 번 했나요?","options":[{"t":"560번","correct":true},{"t":"87번","mis":"M3-1-u4-X01"},{"t":"56번","mis":"M3-1-u4-X02"},{"t":"5600번","mis":"M3-1-u4-X03"}],"explanation":["80번씩 7번(묶음) — 곱셈식 80 × 7로 세워요.","8 × 7 = 56의 10배예요.","80 × 7 = 560 — 모두 560번이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#1','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C3',1,'sa','auto','22 × 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"22 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["88"],"explanation":["22를 20과 2로 나누어 곱해요: 20 × 4 = 80, 2 × 4 = 8.","일의 자리 2 × 4 = 8, 십의 자리 2 × 4 = 8(십)이에요.","80 + 8 = 88 — 88은 어림한 20 × 4 = 80과 가까워요."],"variant_rule":{"alt":[{"stem":"11 × 9는 얼마인가요? 숫자로 쓰세요.","answer":["99"],"explanation":["11을 10과 1로 나누어 곱해요: 10 × 9 = 90, 1 × 9 = 9.","일의 자리 1 × 9 = 9, 십의 자리 1 × 9 = 9(십)이에요.","90 + 9 = 99 — 99는 어림한 10 × 9 = 90과 가까워요."],"asset":null},{"stem":"32 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["32를 30과 2로 나누어 곱해요: 30 × 2 = 60, 2 × 2 = 4.","일의 자리 2 × 2 = 4, 십의 자리 3 × 2 = 6(십)이에요.","60 + 4 = 64 — 64는 어림한 30 × 2 = 60과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#2','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C3',1,'sa','auto','21 × 4를 20과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"21 × 4를 20과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["20 × 4 = 80.","□는 1 × 4 = 4예요.","80 + 4 = 84 — 21 × 4의 곱이에요."],"asset":{"type":"expr_grid","rows":[["20 × 4","=","80"],["1 × 4","=",null],["80 + □","=","84"]]},"variant_rule":{"alt":[{"stem":"22 × 2를 20과 2로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["20 × 2 = 40.","□는 2 × 2 = 4예요.","40 + 4 = 44 — 22 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["20 × 2","=","40"],["2 × 2","=",null],["40 + □","=","44"]]}},{"stem":"12 × 4를 10과 2로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["10 × 4 = 40.","□는 2 × 4 = 8이에요.","40 + 8 = 48 — 12 × 4의 곱이에요."],"asset":{"type":"expr_grid","rows":[["10 × 4","=","40"],["2 × 4","=",null],["40 + □","=","48"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#3','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C3',1,'mc','auto','43 × 2는 얼마인가요?',ARRAY['M3-1-u4-X04','M3-1-u4-X05']::text[],true,'{"seq":3,"concept":"M3-1-u4-C3","difficulty":1,"kind":"mc","stem":"43 × 2는 얼마인가요?","options":[{"t":"86","correct":true},{"t":"46","mis":"M3-1-u4-X04"},{"t":"83","mis":"M3-1-u4-X04"},{"t":"68","mis":"M3-1-u4-X05"}],"explanation":["43을 40과 3으로 나누어 곱해요: 40 × 2 = 80, 3 × 2 = 6.","일의 자리 3 × 2 = 6, 십의 자리 4 × 2 = 8(십)이에요.","80 + 6 = 86 — 86은 어림한 40 × 2 = 80과 가까워요."],"variant_rule":{"alt":[{"stem":"22 × 2는 얼마인가요?","options":[{"t":"44","correct":true},{"t":"24","mis":"M3-1-u4-X04"},{"t":"42","mis":"M3-1-u4-X04"},{"t":"40","mis":"M3-1-u4-X06"}],"explanation":["22를 20과 2로 나누어 곱해요: 20 × 2 = 40, 2 × 2 = 4.","일의 자리 2 × 2 = 4, 십의 자리 2 × 2 = 4(십)이에요.","40 + 4 = 44 — 44는 어림한 20 × 2 = 40과 가까워요."],"asset":null},{"stem":"34 × 2는 얼마인가요?","options":[{"t":"68","correct":true},{"t":"38","mis":"M3-1-u4-X04"},{"t":"64","mis":"M3-1-u4-X04"},{"t":"86","mis":"M3-1-u4-X05"}],"explanation":["34를 30과 4로 나누어 곱해요: 30 × 2 = 60, 4 × 2 = 8.","일의 자리 4 × 2 = 8, 십의 자리 3 × 2 = 6(십)이에요.","60 + 8 = 68 — 68은 어림한 30 × 2 = 60과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#4','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C4',1,'mc','auto','31 × 3을 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":4,"concept":"M3-1-u4-C4","difficulty":1,"kind":"mc","stem":"31 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 90","correct":true},{"t":"약 120","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X12"},{"t":"약 60","mis":"M3-1-u4-X11"}],"explanation":["31은 가까운 몇십 30으로 어림해요.","30 × 3 = 90이에요.","그래서 31 × 3은 약 90이에요 — 실제 곱 93과 가까워요."],"variant_rule":{"alt":[{"stem":"11 × 4를 어림하면 약 얼마인가요?","options":[{"t":"약 40","correct":true},{"t":"약 80","mis":"M3-1-u4-X12"},{"t":"약 10","mis":"M3-1-u4-X12"},{"t":"약 50","mis":"M3-1-u4-X11"}],"explanation":["11은 가까운 몇십 10으로 어림해요.","10 × 4 = 40이에요.","그래서 11 × 4는 약 40이에요 — 실제 곱 44와 가까워요."],"asset":null},{"stem":"41 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 80","correct":true},{"t":"약 100","mis":"M3-1-u4-X12"},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 120","mis":"M3-1-u4-X11"}],"explanation":["41은 가까운 몇십 40으로 어림해요.","40 × 2 = 80이에요.","그래서 41 × 2는 약 80이에요 — 실제 곱 82와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#5','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C3',2,'sa','auto','32 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u4-C3","difficulty":2,"kind":"sa","stem":"32 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 2 × 3 = 6 → 6을 써요.","32 × 3 = 96 — 일의 자리 숫자는 6이에요."],"asset":{"type":"expr_grid","rows":[["","","3","2"],["×","","","3"],["","","9",null]]},"variant_rule":{"alt":[{"stem":"24 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 2 × 2 = 4 → 4를 써요.","24 × 2 = 48 — 십의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["","","2","4"],["×","","","2"],["","",null,"8"]]}},{"stem":"23 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 3 × 3 = 9 → 9를 써요.","23 × 3 = 69 — 일의 자리 숫자는 9예요."],"asset":{"type":"expr_grid","rows":[["","","2","3"],["×","","","3"],["","","6",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#6','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C3',2,'sa','auto','체조를 하루에 32분씩 3일 동안 했어요. 모두 몇 분 했나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u4-C3","difficulty":2,"kind":"sa","stem":"체조를 하루에 32분씩 3일 동안 했어요. 모두 몇 분 했나요? 숫자로 쓰세요.","answer":["96"],"explanation":["32분씩 3번(묶음) — 곱셈식 32 × 3으로 세워요.","일의 자리 2 × 3 = 6, 십의 자리 3 × 3 = 9(십)이에요.","32 × 3 = 96 — 모두 96분이에요."],"variant_rule":{"alt":[{"stem":"색종이를 한 명에게 43장씩 2명에게 나누어 주었어요. 모두 몇 장인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["43장씩 2번(묶음) — 곱셈식 43 × 2로 세워요.","일의 자리 3 × 2 = 6, 십의 자리 4 × 2 = 8(십)이에요.","43 × 2 = 86 — 모두 86장이에요."],"asset":null},{"stem":"양치질을 한 달에 41번씩 2달 동안 빠짐없이 했어요. 모두 몇 번 했나요? 숫자로 쓰세요.","answer":["82"],"explanation":["41번씩 2번(묶음) — 곱셈식 41 × 2로 세워요.","일의 자리 1 × 2 = 2, 십의 자리 4 × 2 = 8(십)이에요.","41 × 2 = 82 — 모두 82번이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#7','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C3',2,'ox','auto','32 × 3을 계산하는데 2 × 3 = 6, 3 × 3 = 9를 차례로 나란히 써서 69라고 했어요. 바르게 계산했어요.',ARRAY['M3-1-u4-X05']::text[],true,'{"seq":7,"concept":"M3-1-u4-C3","difficulty":2,"kind":"ox","stem":"32 × 3을 계산하는데 2 × 3 = 6, 3 × 3 = 9를 차례로 나란히 써서 69라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 곱은 십의 자리에 써야 해서","correct":true},{"t":"두 곱을 구했으니 어떤 순서로 써도 되어서","mis":"M3-1-u4-X05"}],"mis":"M3-1-u4-X05","explanation":["일의 자리 곱 6은 일의 자리에, 십의 자리 곱 9는 십의 자리에 써요.","32 × 3 = 96이에요.","어림하면 약 90 — 69는 너무 커요."],"variant_rule":{"alt":[{"stem":"12 × 3을 계산하는데 2 × 3 = 6, 1 × 3 = 3을 차례로 나란히 써서 63이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 곱은 십의 자리에 써야 해서","correct":true},{"t":"두 곱을 구했으니 어떤 순서로 써도 되어서","mis":"M3-1-u4-X05"}],"explanation":["일의 자리 곱 6은 일의 자리에, 십의 자리 곱 3은 십의 자리에 써요.","12 × 3 = 36이에요.","어림하면 약 30 — 63은 너무 커요."],"asset":null},{"stem":"31 × 3을 계산하는데 1 × 3 = 3, 3 × 3 = 9를 차례로 나란히 써서 39라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 곱은 십의 자리에 써야 해서","correct":true},{"t":"두 곱을 구했으니 어떤 순서로 써도 되어서","mis":"M3-1-u4-X05"}],"explanation":["일의 자리 곱 3은 일의 자리에, 십의 자리 곱 9는 십의 자리에 써요.","31 × 3 = 93이에요.","어림하면 약 90 — 39는 너무 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#8','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C3',2,'mc','auto','12 × 3을 나누어 곱하려고 해요. 10 × 3은 얼마인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X03','M3-1-u4-X06']::text[],true,'{"seq":8,"concept":"M3-1-u4-C3","difficulty":2,"kind":"mc","stem":"12 × 3을 나누어 곱하려고 해요. 10 × 3은 얼마인가요?","options":[{"t":"30","correct":true},{"t":"3","mis":"M3-1-u4-X02"},{"t":"300","mis":"M3-1-u4-X03"},{"t":"36","mis":"M3-1-u4-X06"}],"explanation":["12를 10과 2로 나누어요.","10 × 3 = 3의 10배 — 30이에요.","여기에 2 × 3 = 6을 더하면 12 × 3 = 36이에요."],"variant_rule":{"alt":[{"stem":"11 × 7을 나누어 곱하려고 해요. 10 × 7은 얼마인가요?","options":[{"t":"70","correct":true},{"t":"7","mis":"M3-1-u4-X02"},{"t":"700","mis":"M3-1-u4-X03"},{"t":"77","mis":"M3-1-u4-X06"}],"explanation":["11을 10과 1로 나누어요.","10 × 7 = 7의 10배 — 70이에요.","여기에 1 × 7 = 7을 더하면 11 × 7 = 77이에요."],"asset":null},{"stem":"31 × 2를 나누어 곱하려고 해요. 30 × 2는 얼마인가요?","options":[{"t":"60","correct":true},{"t":"6","mis":"M3-1-u4-X02"},{"t":"600","mis":"M3-1-u4-X03"},{"t":"62","mis":"M3-1-u4-X06"}],"explanation":["31을 30과 1로 나누어요.","30 × 2 = 6의 10배 — 60이에요.","여기에 1 × 2 = 2를 더하면 31 × 2 = 62예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#9','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C3',2,'mc','auto','21 × 4를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?',ARRAY['M3-1-u4-X06','M3-1-u4-X11']::text[],true,'{"seq":9,"concept":"M3-1-u4-C3","difficulty":2,"kind":"mc","stem":"21 × 4를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"84","correct":true},{"t":"80","mis":"M3-1-u4-X06"},{"t":"4","mis":"M3-1-u4-X06"},{"t":"94","mis":"M3-1-u4-X11"}],"explanation":["나누어 곱한 두 곱을 더해요.","80 + 4 = 84예요.","하나만 쓰면 21 × 4의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["20 × 4","=","80"],["1 × 4","=","4"],["80 + 4","=",null]]},"variant_rule":{"alt":[{"stem":"14 × 2를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"28","correct":true},{"t":"20","mis":"M3-1-u4-X06"},{"t":"8","mis":"M3-1-u4-X06"},{"t":"38","mis":"M3-1-u4-X11"}],"explanation":["나누어 곱한 두 곱을 더해요.","20 + 8 = 28이에요.","하나만 쓰면 14 × 2의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["10 × 2","=","20"],["4 × 2","=","8"],["20 + 8","=",null]]}},{"stem":"12 × 3을 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"36","correct":true},{"t":"30","mis":"M3-1-u4-X06"},{"t":"6","mis":"M3-1-u4-X06"},{"t":"46","mis":"M3-1-u4-X11"}],"explanation":["나누어 곱한 두 곱을 더해요.","30 + 6 = 36이에요.","하나만 쓰면 12 × 3의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["10 × 3","=","30"],["2 × 3","=","6"],["30 + 6","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_basic#10','math',3,1,'u4','L03','g3_1_math_u4_L03_basic','lesson_basic','M3-1-u4-C3',3,'error','auto','21 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X04','M3-1-u4-X15']::text[],true,'{"seq":10,"concept":"M3-1-u4-C3","difficulty":3,"kind":"error","stem":"21 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「21 × 4 = 24야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"지유 — 「21 × 4 = 84야」","mis":"M3-1-u4-X15"},{"t":"서윤 — 「어림하면 약 80이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 1 × 4 = 4, 십의 자리 2 × 4 = 8(십)이에요.","21 × 4 = 84예요.","하랑은 24로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"11 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「11 × 8 = 18이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"도윤 — 「11 × 8 = 88이야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「10 × 8 = 80, 1 × 8 = 8, 더하면 88이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 1 × 8 = 8, 십의 자리 1 × 8 = 8(십)이에요.","11 × 8 = 88이에요.","하린은 18로 잘못 구했어요."],"asset":null},{"stem":"33 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「33 × 2 = 36이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"태오 — 「33 × 2 = 66이야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「어림하면 약 60이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 3 × 2 = 6, 십의 자리 3 × 2 = 6(십)이에요.","33 × 2 = 66이에요.","하린은 36으로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#1','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C3',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u4-C3","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"12 × 4","r":"48"},{"l":"33 × 3","r":"99"},{"l":"11 × 6","r":"66"}],"mis":"M3-1-u4-X04","explanation":["몇십과 몇으로 나누어 곱하고 더해요.","12 × 4 = 48, 33 × 3 = 99, 11 × 6 = 66.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"22 × 4","r":"88"},{"l":"41 × 2","r":"82"},{"l":"21 × 4","r":"84"}],"explanation":["몇십과 몇으로 나누어 곱하고 더해요.","22 × 4 = 88, 41 × 2 = 82, 21 × 4 = 84.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"21 × 2","r":"42"},{"l":"11 × 3","r":"33"},{"l":"12 × 3","r":"36"}],"explanation":["몇십과 몇으로 나누어 곱하고 더해요.","21 × 2 = 42, 11 × 3 = 33, 12 × 3 = 36.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#2','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C4',2,'ox','auto','31 × 3을 계산했더니 33이 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-1-u4-X12']::text[],true,'{"seq":2,"concept":"M3-1-u4-C4","difficulty":2,"kind":"ox","stem":"31 × 3을 계산했더니 33이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 90과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"mis":"M3-1-u4-X12","explanation":["31을 30으로 어림하면 약 90이에요.","33은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 31 × 3 = 93이에요."],"variant_rule":{"alt":[{"stem":"41 × 2를 계산했더니 42가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 80과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["41을 40으로 어림하면 약 80이에요.","42는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 41 × 2 = 82예요."],"asset":null},{"stem":"13 × 2를 계산했더니 62가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 20과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["13을 10으로 어림하면 약 20이에요.","62는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 13 × 2 = 26이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#3','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C3',3,'sa','auto','2□ × 3 = 69 — □에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C3","difficulty":3,"kind":"sa","stem":"2□ × 3 = 69 — □에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["먼저 20 × 3 = 60이에요.","남은 69 − 60 = 9가 일의 자리 곱이에요.","□ × 3 = 9 → □ = 3이에요."],"variant_rule":{"alt":[{"stem":"2□ × 2 = 46 — □에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["먼저 20 × 2 = 40이에요.","남은 46 − 40 = 6이 일의 자리 곱이에요.","□ × 2 = 6 → □ = 3이에요."],"asset":null},{"stem":"1□ × 2 = 22 — □에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["먼저 10 × 2 = 20이에요.","남은 22 − 20 = 2가 일의 자리 곱이에요.","□ × 2 = 2 → □ = 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#4','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C3',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 32 × 3 ○ 11 × 9',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":4,"concept":"M3-1-u4-C3","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 32 × 3 ○ 11 × 9","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["32 × 3 = 96이에요.","11 × 9 = 99예요.","96 < 99 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 11 × 2 ○ 13 × 3","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["11 × 2 = 22예요.","13 × 3 = 39예요.","22 < 39 — 알맞은 것은 <예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 23 × 3 ○ 22 × 4","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["23 × 3 = 69예요.","22 × 4 = 88이에요.","69 < 88 — 알맞은 것은 <예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#5','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C3',3,'error','auto','43 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X04','M3-1-u4-X15']::text[],true,'{"seq":5,"concept":"M3-1-u4-C3","difficulty":3,"kind":"error","stem":"43 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「43 × 2 = 46이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"서윤 — 「43 × 2 = 86이야」","mis":"M3-1-u4-X15"},{"t":"하린 — 「40 × 2 = 80, 3 × 2 = 6, 더하면 86이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 3 × 2 = 6, 십의 자리 4 × 2 = 8(십)이에요.","43 × 2 = 86이에요.","시우는 46으로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"11 × 9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「11 × 9 = 19야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"태오 — 「11 × 9 = 99야」","mis":"M3-1-u4-X15"},{"t":"하랑 — 「어림하면 약 90이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 1 × 9 = 9, 십의 자리 1 × 9 = 9(십)이에요.","11 × 9 = 99예요.","시우는 19로 잘못 구했어요."],"asset":null},{"stem":"22 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「22 × 2 = 24야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"태오 — 「22 × 2 = 44야」","mis":"M3-1-u4-X15"},{"t":"하린 — 「20 × 2 = 40, 2 × 2 = 4, 더하면 44야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 2 × 2 = 4, 십의 자리 2 × 2 = 4(십)이에요.","22 × 2 = 44예요.","서윤은 24로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#6','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C4',3,'mc','auto','11 × 9를 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":6,"concept":"M3-1-u4-C4","difficulty":3,"kind":"mc","stem":"11 × 9를 어림하면 약 얼마인가요?","options":[{"t":"약 90","correct":true},{"t":"약 180","mis":"M3-1-u4-X12"},{"t":"약 10","mis":"M3-1-u4-X12"},{"t":"약 100","mis":"M3-1-u4-X11"}],"explanation":["11은 가까운 몇십 10으로 어림해요.","10 × 9 = 90이에요.","그래서 11 × 9는 약 90이에요 — 실제 곱 99와 가까워요."],"variant_rule":{"alt":[{"stem":"12 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 20","correct":true},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 10","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X11"}],"explanation":["12는 가까운 몇십 10으로 어림해요.","10 × 2 = 20이에요.","그래서 12 × 2는 약 20이에요 — 실제 곱 24와 가까워요."],"asset":null},{"stem":"11 × 4를 어림하면 약 얼마인가요?","options":[{"t":"약 40","correct":true},{"t":"약 80","mis":"M3-1-u4-X12"},{"t":"약 10","mis":"M3-1-u4-X12"},{"t":"약 50","mis":"M3-1-u4-X11"}],"explanation":["11은 가까운 몇십 10으로 어림해요.","10 × 4 = 40이에요.","그래서 11 × 4는 약 40이에요 — 실제 곱 44와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#7','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C3',3,'sa','auto','24 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u4-C3","difficulty":3,"kind":"sa","stem":"24 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 2 × 2 = 4 → 4를 써요.","24 × 2 = 48 — 십의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["","","2","4"],["×","","","2"],["","",null,"8"]]},"variant_rule":{"alt":[{"stem":"11 × 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 1 × 6 = 6 → 6을 써요.","11 × 6 = 66 — 일의 자리 숫자는 6이에요."],"asset":{"type":"expr_grid","rows":[["","","1","1"],["×","","","6"],["","","6",null]]}},{"stem":"11 × 9의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 1 × 9 = 9 → 9를 써요.","11 × 9 = 99 — 십의 자리 숫자는 9예요."],"asset":{"type":"expr_grid","rows":[["","","1","1"],["×","","","9"],["","",null,"9"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#8','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C3',4,'essay','teacher','양치질을 일주일에 21회씩 4주 했어요. 21 × 4를 몇십과 몇으로 나누어 계산하는 방법을 쓰고, 어림으로 답이 맞는지 확인해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u4-C3","difficulty":4,"kind":"essay","stem":"양치질을 일주일에 21회씩 4주 했어요. 21 × 4를 몇십과 몇으로 나누어 계산하는 방법을 쓰고, 어림으로 답이 맞는지 확인해 보세요.","answer_guide":{"answer":"예: 21을 20과 1로 나누어 20 × 4 = 80, 1 × 4 = 4를 구하고 더하면 84이다. 21을 20으로 어림하면 약 80이므로 84는 알맞은 답이다.","scoring_points":["20 × 4 = 80, 1 × 4 = 4로 나누어 곱했는가","더해서 84를 구했는가","약 80으로 어림해 확인했는가"]},"explanation":["20 × 4 = 80, 1 × 4 = 4.","80 + 4 = 84.","어림 약 80 — 84와 가까워요."],"asset":{"type":"expr_grid","rows":[["20 × 4","=","80"],["1 × 4","=","4"],["80 + 4","=","84"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#9','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C3',4,'essay','teacher','도윤이는 32 × 3을 계산하면서 「2 × 3 = 6, 3 × 3 = 9이니까 69야.」라고 했어요. 도윤이의 답이 맞는지 판단하고, 바르게 계산하는 방법을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u4-C3","difficulty":4,"kind":"essay","stem":"도윤이는 32 × 3을 계산하면서 「2 × 3 = 6, 3 × 3 = 9이니까 69야.」라고 했어요. 도윤이의 답이 맞는지 판단하고, 바르게 계산하는 방법을 써 보세요.","answer_guide":{"answer":"예: 틀렸다. 십의 자리 곱 3 × 3 = 9는 90을 뜻하므로 십의 자리에, 일의 자리 곱 6은 일의 자리에 써야 한다. 30 × 3 = 90, 2 × 3 = 6, 더하면 96이다. 어림해도 약 90이라 69는 맞지 않다.","scoring_points":["틀렸다고 판단했는가","곱을 제자리에 써야 한다고 설명했는가","바른 답 96을 구했는가"]},"explanation":["십의 자리 곱 9는 90을 뜻해요.","90 + 6 = 96.","어림 약 90 — 69는 너무 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L03_challenge#10','math',3,1,'u4','L03','g3_1_math_u4_L03_challenge','lesson_challenge','M3-1-u4-C3',4,'sa','auto','4□ × 2 = 82 — □에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u4-C3","difficulty":4,"kind":"sa","stem":"4□ × 2 = 82 — □에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["먼저 40 × 2 = 80이에요.","남은 82 − 80 = 2가 일의 자리 곱이에요.","□ × 2 = 2 → □ = 1이에요."],"variant_rule":{"alt":[{"stem":"1□ × 7 = 77 — □에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["먼저 10 × 7 = 70이에요.","남은 77 − 70 = 7이 일의 자리 곱이에요.","□ × 7 = 7 → □ = 1이에요."],"asset":null},{"stem":"2□ × 2 = 44 — □에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["먼저 20 × 2 = 40이에요.","남은 44 − 40 = 4가 일의 자리 곱이에요.","□ × 2 = 4 → □ = 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#1','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C5',1,'mc','auto','52 × 4는 얼마인가요?',ARRAY['M3-1-u4-X07','M3-1-u4-X06','M3-1-u4-X04']::text[],true,'{"seq":1,"concept":"M3-1-u4-C5","difficulty":1,"kind":"mc","stem":"52 × 4는 얼마인가요?","options":[{"t":"208","correct":true},{"t":"8","mis":"M3-1-u4-X07"},{"t":"200","mis":"M3-1-u4-X06"},{"t":"58","mis":"M3-1-u4-X04"}],"explanation":["52를 50과 2로 나누어 곱해요: 50 × 4 = 200, 2 × 4 = 8.","십의 자리 곱 50 × 4 = 200 — 백의 자리로 올림해요.","200 + 8 = 208 — 208은 어림한 50 × 4 = 200과 가까워요."],"variant_rule":{"alt":[{"stem":"83 × 2는 얼마인가요?","options":[{"t":"166","correct":true},{"t":"66","mis":"M3-1-u4-X07"},{"t":"160","mis":"M3-1-u4-X06"},{"t":"6","mis":"M3-1-u4-X06"}],"explanation":["83을 80과 3으로 나누어 곱해요: 80 × 2 = 160, 3 × 2 = 6.","십의 자리 곱 80 × 2 = 160 — 백의 자리로 올림해요.","160 + 6 = 166 — 166은 어림한 80 × 2 = 160과 가까워요."],"asset":null},{"stem":"41 × 9는 얼마인가요?","options":[{"t":"369","correct":true},{"t":"69","mis":"M3-1-u4-X07"},{"t":"360","mis":"M3-1-u4-X06"},{"t":"9","mis":"M3-1-u4-X06"}],"explanation":["41을 40과 1로 나누어 곱해요: 40 × 9 = 360, 1 × 9 = 9.","십의 자리 곱 40 × 9 = 360 — 백의 자리로 올림해요.","360 + 9 = 369 — 369는 어림한 40 × 9 = 360과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#2','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C5',1,'mc','auto','43 × 3을 나누어 곱하려고 해요. 40 × 3은 얼마인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X03','M3-1-u4-X06']::text[],true,'{"seq":2,"concept":"M3-1-u4-C5","difficulty":1,"kind":"mc","stem":"43 × 3을 나누어 곱하려고 해요. 40 × 3은 얼마인가요?","options":[{"t":"120","correct":true},{"t":"12","mis":"M3-1-u4-X02"},{"t":"1200","mis":"M3-1-u4-X03"},{"t":"129","mis":"M3-1-u4-X06"}],"explanation":["43을 40과 3으로 나누어요.","40 × 3 = 12의 10배 — 120이에요.","여기에 3 × 3 = 9를 더하면 43 × 3 = 129예요."],"variant_rule":{"alt":[{"stem":"31 × 6을 나누어 곱하려고 해요. 30 × 6은 얼마인가요?","options":[{"t":"180","correct":true},{"t":"18","mis":"M3-1-u4-X02"},{"t":"1800","mis":"M3-1-u4-X03"},{"t":"186","mis":"M3-1-u4-X06"}],"explanation":["31을 30과 1로 나누어요.","30 × 6 = 18의 10배 — 180이에요.","여기에 1 × 6 = 6을 더하면 31 × 6 = 186이에요."],"asset":null},{"stem":"91 × 2를 나누어 곱하려고 해요. 90 × 2는 얼마인가요?","options":[{"t":"180","correct":true},{"t":"18","mis":"M3-1-u4-X02"},{"t":"1800","mis":"M3-1-u4-X03"},{"t":"182","mis":"M3-1-u4-X06"}],"explanation":["91을 90과 1로 나누어요.","90 × 2 = 18의 10배 — 180이에요.","여기에 1 × 2 = 2를 더하면 91 × 2 = 182예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#3','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C5',1,'sa','auto','73 × 2의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C5","difficulty":1,"kind":"sa","stem":"73 × 2의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["십의 자리 곱 7 × 2 = 14예요.","10을 넘은 1이 백의 자리로 올림해요.","73 × 2 = 146 — 백의 자리 숫자는 1이에요."],"variant_rule":{"alt":[{"stem":"41 × 6의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["십의 자리 곱 4 × 6 = 24예요.","10을 넘은 2가 백의 자리로 올림해요.","41 × 6 = 246 — 백의 자리 숫자는 2예요."],"asset":null},{"stem":"41 × 8의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["십의 자리 곱 4 × 8 = 32예요.","10을 넘은 3이 백의 자리로 올림해요.","41 × 8 = 328 — 백의 자리 숫자는 3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#4','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C4',1,'mc','auto','63 × 3을 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":4,"concept":"M3-1-u4-C4","difficulty":1,"kind":"mc","stem":"63 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 180","correct":true},{"t":"약 210","mis":"M3-1-u4-X12"},{"t":"약 60","mis":"M3-1-u4-X12"},{"t":"약 240","mis":"M3-1-u4-X11"}],"explanation":["63은 가까운 몇십 60으로 어림해요.","60 × 3 = 180이에요.","그래서 63 × 3은 약 180이에요 — 실제 곱 189와 가까워요."],"variant_rule":{"alt":[{"stem":"83 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 240","correct":true},{"t":"약 270","mis":"M3-1-u4-X12"},{"t":"약 80","mis":"M3-1-u4-X12"},{"t":"약 320","mis":"M3-1-u4-X11"}],"explanation":["83은 가까운 몇십 80으로 어림해요.","80 × 3 = 240이에요.","그래서 83 × 3은 약 240이에요 — 실제 곱 249와 가까워요."],"asset":null},{"stem":"74 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 140","correct":true},{"t":"약 160","mis":"M3-1-u4-X12"},{"t":"약 70","mis":"M3-1-u4-X12"},{"t":"약 210","mis":"M3-1-u4-X11"}],"explanation":["74는 가까운 몇십 70으로 어림해요.","70 × 2 = 140이에요.","그래서 74 × 2는 약 140이에요 — 실제 곱 148과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#5','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C5',2,'sa','auto','43 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u4-C5","difficulty":2,"kind":"sa","stem":"43 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 4 × 3 = 12 → 2를 써요.","43 × 3 = 129 — 십의 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["","","4","3"],["×","","","3"],["","1",null,"9"]]},"variant_rule":{"alt":[{"stem":"51 × 7의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 5 × 7 = 35 → 5를 써요.","51 × 7 = 357 — 십의 자리 숫자는 5예요."],"asset":{"type":"expr_grid","rows":[["","","5","1"],["×","","","7"],["","3",null,"7"]]}},{"stem":"61 × 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리 곱 36이 10을 넘어 백의 자리에 3을 써요.","61 × 6 = 366 — 백의 자리 숫자는 3이에요."],"asset":{"type":"expr_grid","rows":[["","","6","1"],["×","","","6"],["",null,"6","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#6','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C5',2,'mc','auto','길이가 63cm인 골판지 3개를 겹치지 않게 이었어요. 모두 몇 cm인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":6,"concept":"M3-1-u4-C5","difficulty":2,"kind":"mc","stem":"길이가 63cm인 골판지 3개를 겹치지 않게 이었어요. 모두 몇 cm인가요?","options":[{"t":"189cm","correct":true},{"t":"66cm","mis":"M3-1-u4-X01"},{"t":"89cm","mis":"M3-1-u4-X07"},{"t":"180cm","mis":"M3-1-u4-X06"}],"explanation":["63cm씩 3번(묶음) — 곱셈식 63 × 3으로 세워요.","십의 자리 곱 60 × 3 = 180 — 백의 자리로 올림해요.","63 × 3 = 189 — 모두 189cm예요."],"variant_rule":{"alt":[{"stem":"체조를 하루에 71분씩 6일 동안 했어요. 모두 몇 분 했나요?","options":[{"t":"426분","correct":true},{"t":"77분","mis":"M3-1-u4-X01"},{"t":"26분","mis":"M3-1-u4-X07"},{"t":"420분","mis":"M3-1-u4-X06"}],"explanation":["71분씩 6번(묶음) — 곱셈식 71 × 6으로 세워요.","십의 자리 곱 70 × 6 = 420 — 백의 자리로 올림해요.","71 × 6 = 426 — 모두 426분이에요."],"asset":null},{"stem":"윗몸 일으키기를 하루에 71개씩 7일 동안 했어요. 모두 몇 개 했나요?","options":[{"t":"497개","correct":true},{"t":"78개","mis":"M3-1-u4-X01"},{"t":"97개","mis":"M3-1-u4-X07"},{"t":"490개","mis":"M3-1-u4-X06"}],"explanation":["71개씩 7번(묶음) — 곱셈식 71 × 7로 세워요.","십의 자리 곱 70 × 7 = 490 — 백의 자리로 올림해요.","71 × 7 = 497 — 모두 497개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#7','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C5',2,'ox','auto','43 × 3을 계산하는데 십의 자리 곱 12에서 백의 자리로 올림한 1을 빠뜨리고 29라고 했어요. 바르게 계산했어요.',ARRAY['M3-1-u4-X07']::text[],true,'{"seq":7,"concept":"M3-1-u4-C5","difficulty":2,"kind":"ox","stem":"43 × 3을 계산하는데 십의 자리 곱 12에서 백의 자리로 올림한 1을 빠뜨리고 29라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 곱이 10을 넘으면 백의 자리로 올림해야 해서","correct":true},{"t":"세로셈은 두 자리까지만 쓰면 되어서","mis":"M3-1-u4-X07"}],"mis":"M3-1-u4-X07","explanation":["40 × 3 = 120 — 백의 자리까지 생겨요.","43 × 3 = 129예요.","어림하면 약 120 — 두 자리 29는 너무 작아요."],"variant_rule":{"alt":[{"stem":"73 × 3을 계산하는데 십의 자리 곱 21에서 백의 자리로 올림한 2를 빠뜨리고 19라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 곱이 10을 넘으면 백의 자리로 올림해야 해서","correct":true},{"t":"세로셈은 두 자리까지만 쓰면 되어서","mis":"M3-1-u4-X07"}],"explanation":["70 × 3 = 210 — 백의 자리까지 생겨요.","73 × 3 = 219예요.","어림하면 약 210 — 두 자리 19는 너무 작아요."],"asset":null},{"stem":"91 × 3을 계산하는데 십의 자리 곱 27에서 백의 자리로 올림한 2를 빠뜨리고 73이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 곱이 10을 넘으면 백의 자리로 올림해야 해서","correct":true},{"t":"세로셈은 두 자리까지만 쓰면 되어서","mis":"M3-1-u4-X07"}],"explanation":["90 × 3 = 270 — 백의 자리까지 생겨요.","91 × 3 = 273이에요.","어림하면 약 270 — 두 자리 73은 너무 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#8','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C5',2,'mc','auto','42 × 4를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?',ARRAY['M3-1-u4-X06','M3-1-u4-X11']::text[],true,'{"seq":8,"concept":"M3-1-u4-C5","difficulty":2,"kind":"mc","stem":"42 × 4를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"168","correct":true},{"t":"160","mis":"M3-1-u4-X06"},{"t":"8","mis":"M3-1-u4-X06"},{"t":"178","mis":"M3-1-u4-X11"}],"explanation":["나누어 곱한 두 곱을 더해요.","160 + 8 = 168이에요.","하나만 쓰면 42 × 4의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["40 × 4","=","160"],["2 × 4","=","8"],["160 + 8","=",null]]},"variant_rule":{"alt":[{"stem":"92 × 4를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"368","correct":true},{"t":"360","mis":"M3-1-u4-X06"},{"t":"8","mis":"M3-1-u4-X06"},{"t":"378","mis":"M3-1-u4-X11"}],"explanation":["나누어 곱한 두 곱을 더해요.","360 + 8 = 368이에요.","하나만 쓰면 92 × 4의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["90 × 4","=","360"],["2 × 4","=","8"],["360 + 8","=",null]]}},{"stem":"72 × 2를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"144","correct":true},{"t":"140","mis":"M3-1-u4-X06"},{"t":"4","mis":"M3-1-u4-X06"},{"t":"154","mis":"M3-1-u4-X11"}],"explanation":["나누어 곱한 두 곱을 더해요.","140 + 4 = 144예요.","하나만 쓰면 72 × 2의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["70 × 2","=","140"],["2 × 2","=","4"],["140 + 4","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#9','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C5',2,'mc','auto','곱이 세 자리 수인 것은 어느 것인가요?',ARRAY['M3-1-u4-X07']::text[],true,'{"seq":9,"concept":"M3-1-u4-C5","difficulty":2,"kind":"mc","stem":"곱이 세 자리 수인 것은 어느 것인가요?","options":[{"t":"51 × 3","correct":true},{"t":"14 × 2","mis":"M3-1-u4-X07"},{"t":"13 × 2","mis":"M3-1-u4-X07"},{"t":"42 × 2","mis":"M3-1-u4-X07"}],"explanation":["십의 자리 숫자 × 곱하는 수가 10 이상이면 백의 자리가 생겨요.","51 × 3 = 153 — 5 × 3 = 15가 10 이상이에요.","나머지는 14 × 2 = 28, 13 × 2 = 26, 42 × 2 = 84 — 두 자리예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 세 자리 수인 것은 어느 것인가요?","options":[{"t":"31 × 9","correct":true},{"t":"34 × 2","mis":"M3-1-u4-X07"},{"t":"43 × 2","mis":"M3-1-u4-X07"},{"t":"13 × 3","mis":"M3-1-u4-X07"}],"explanation":["십의 자리 숫자 × 곱하는 수가 10 이상이면 백의 자리가 생겨요.","31 × 9 = 279 — 3 × 9 = 27이 10 이상이에요.","나머지는 34 × 2 = 68, 43 × 2 = 86, 13 × 3 = 39 — 두 자리예요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 세 자리 수인 것은 어느 것인가요?","options":[{"t":"63 × 3","correct":true},{"t":"11 × 3","mis":"M3-1-u4-X07"},{"t":"13 × 2","mis":"M3-1-u4-X07"},{"t":"13 × 3","mis":"M3-1-u4-X07"}],"explanation":["십의 자리 숫자 × 곱하는 수가 10 이상이면 백의 자리가 생겨요.","63 × 3 = 189 — 6 × 3 = 18이 10 이상이에요.","나머지는 11 × 3 = 33, 13 × 2 = 26, 13 × 3 = 39 — 두 자리예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_basic#10','math',3,1,'u4','L04','g3_1_math_u4_L04_basic','lesson_basic','M3-1-u4-C5',3,'error','auto','52 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X07','M3-1-u4-X15']::text[],true,'{"seq":10,"concept":"M3-1-u4-C5","difficulty":3,"kind":"error","stem":"52 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「52 × 4 = 8이야」","correct":true,"mis_target":"M3-1-u4-X07"},{"t":"시우 — 「52 × 4 = 208이야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「어림하면 약 200이야」","mis":"M3-1-u4-X15"}],"explanation":["십의 자리 곱 50 × 4 = 200 — 백의 자리로 올림해요.","52 × 4 = 208이에요.","하린은 8로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"82 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「82 × 3 = 46이야」","correct":true,"mis_target":"M3-1-u4-X07"},{"t":"하랑 — 「82 × 3 = 246이야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「80 × 3 = 240, 2 × 3 = 6, 더하면 246이야」","mis":"M3-1-u4-X15"}],"explanation":["십의 자리 곱 80 × 3 = 240 — 백의 자리로 올림해요.","82 × 3 = 246이에요.","시우는 46으로 잘못 구했어요."],"asset":null},{"stem":"91 × 9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「91 × 9 = 19야」","correct":true,"mis_target":"M3-1-u4-X07"},{"t":"태오 — 「91 × 9 = 819야」","mis":"M3-1-u4-X15"},{"t":"지유 — 「어림하면 약 810이야」","mis":"M3-1-u4-X15"}],"explanation":["십의 자리 곱 90 × 9 = 810 — 백의 자리로 올림해요.","91 × 9 = 819예요.","서윤은 19로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#1','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C5',2,'sa','auto','41 × 6을 40과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u4-C5","difficulty":2,"kind":"sa","stem":"41 × 6을 40과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["40 × 6 = 240.","□는 1 × 6 = 6이에요.","240 + 6 = 246 — 41 × 6의 곱이에요."],"asset":{"type":"expr_grid","rows":[["40 × 6","=","240"],["1 × 6","=",null],["240 + □","=","246"]]},"variant_rule":{"alt":[{"stem":"63 × 3을 60과 3으로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["60 × 3 = 180.","□는 3 × 3 = 9예요.","180 + 9 = 189 — 63 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["60 × 3","=","180"],["3 × 3","=",null],["180 + □","=","189"]]}},{"stem":"92 × 3을 90과 2로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["90 × 3 = 270.","□는 2 × 3 = 6이에요.","270 + 6 = 276 — 92 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["90 × 3","=","270"],["2 × 3","=",null],["270 + □","=","276"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#2','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C5',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u4-C5","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"61 × 5","r":"305"},{"l":"61 × 2","r":"122"},{"l":"52 × 4","r":"208"}],"mis":"M3-1-u4-X07","explanation":["몇십과 몇으로 나누어 곱하고 더해요.","61 × 5 = 305, 61 × 2 = 122, 52 × 4 = 208.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"41 × 3","r":"123"},{"l":"81 × 6","r":"486"},{"l":"82 × 4","r":"328"}],"explanation":["몇십과 몇으로 나누어 곱하고 더해요.","41 × 3 = 123, 81 × 6 = 486, 82 × 4 = 328.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"84 × 2","r":"168"},{"l":"52 × 4","r":"208"},{"l":"51 × 3","r":"153"}],"explanation":["몇십과 몇으로 나누어 곱하고 더해요.","84 × 2 = 168, 52 × 4 = 208, 51 × 3 = 153.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#3','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C5',3,'sa','auto','81 × 7의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C5","difficulty":3,"kind":"sa","stem":"81 × 7의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 8 × 7 = 56 → 6을 써요.","81 × 7 = 567 — 십의 자리 숫자는 6이에요."],"asset":{"type":"expr_grid","rows":[["","","8","1"],["×","","","7"],["","5",null,"7"]]},"variant_rule":{"alt":[{"stem":"51 × 8의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["0"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 5 × 8 = 40 → 0을 써요.","51 × 8 = 408 — 십의 자리 숫자는 0이에요."],"asset":{"type":"expr_grid","rows":[["","","5","1"],["×","","","8"],["","4",null,"8"]]}},{"stem":"31 × 7의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리 곱 21이 10을 넘어 백의 자리에 2를 써요.","31 × 7 = 217 — 백의 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["","","3","1"],["×","","","7"],["",null,"1","7"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#4','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C5',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 72 × 4 ○ 41 × 8',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":4,"concept":"M3-1-u4-C5","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 72 × 4 ○ 41 × 8","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["72 × 4 = 288이에요.","41 × 8 = 328이에요.","288 < 328 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 91 × 4 ○ 41 × 9","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["91 × 4 = 364예요.","41 × 9 = 369예요.","364 < 369 — 알맞은 것은 <예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 51 × 6 ○ 93 × 3","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["51 × 6 = 306이에요.","93 × 3 = 279예요.","306 > 279 — 알맞은 것은 >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#5','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C4',3,'ox','auto','61 × 4를 계산했더니 44가 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-1-u4-X12']::text[],true,'{"seq":5,"concept":"M3-1-u4-C4","difficulty":3,"kind":"ox","stem":"61 × 4를 계산했더니 44가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 240과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"mis":"M3-1-u4-X12","explanation":["61을 60으로 어림하면 약 240이에요.","44는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 61 × 4 = 244예요."],"variant_rule":{"alt":[{"stem":"91 × 8을 계산했더니 28이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 720과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["91을 90으로 어림하면 약 720이에요.","28은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 91 × 8 = 728이에요."],"asset":null},{"stem":"21 × 8을 계산했더니 68이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 160과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["21을 20으로 어림하면 약 160이에요.","68은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 21 × 8 = 168이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#6','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C5',3,'error','auto','91 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X07','M3-1-u4-X15']::text[],true,'{"seq":6,"concept":"M3-1-u4-C5","difficulty":3,"kind":"error","stem":"91 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「91 × 8 = 28이야」","correct":true,"mis_target":"M3-1-u4-X07"},{"t":"은우 — 「91 × 8 = 728이야」","mis":"M3-1-u4-X15"},{"t":"지유 — 「90 × 8 = 720, 1 × 8 = 8, 더하면 728이야」","mis":"M3-1-u4-X15"}],"explanation":["십의 자리 곱 90 × 8 = 720 — 백의 자리로 올림해요.","91 × 8 = 728이에요.","도윤은 28로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"31 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「31 × 7 = 17이야」","correct":true,"mis_target":"M3-1-u4-X07"},{"t":"지유 — 「31 × 7 = 217이야」","mis":"M3-1-u4-X15"},{"t":"서윤 — 「어림하면 약 210이야」","mis":"M3-1-u4-X15"}],"explanation":["십의 자리 곱 30 × 7 = 210 — 백의 자리로 올림해요.","31 × 7 = 217이에요.","은우는 17로 잘못 구했어요."],"asset":null},{"stem":"71 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「71 × 3 = 13이야」","correct":true,"mis_target":"M3-1-u4-X07"},{"t":"도윤 — 「71 × 3 = 213이야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「70 × 3 = 210, 1 × 3 = 3, 더하면 213이야」","mis":"M3-1-u4-X15"}],"explanation":["십의 자리 곱 70 × 3 = 210 — 백의 자리로 올림해요.","71 × 3 = 213이에요.","시우는 13으로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#7','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C5',3,'mc','auto','윗몸 일으키기를 하루에 41개씩 6일 동안 했어요. 모두 몇 개 했나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":7,"concept":"M3-1-u4-C5","difficulty":3,"kind":"mc","stem":"윗몸 일으키기를 하루에 41개씩 6일 동안 했어요. 모두 몇 개 했나요?","options":[{"t":"246개","correct":true},{"t":"47개","mis":"M3-1-u4-X01"},{"t":"46개","mis":"M3-1-u4-X07"},{"t":"240개","mis":"M3-1-u4-X06"}],"explanation":["41개씩 6번(묶음) — 곱셈식 41 × 6으로 세워요.","십의 자리 곱 40 × 6 = 240 — 백의 자리로 올림해요.","41 × 6 = 246 — 모두 246개예요."],"variant_rule":{"alt":[{"stem":"양치질을 한 달에 31번씩 9달 동안 빠짐없이 했어요. 모두 몇 번 했나요?","options":[{"t":"279번","correct":true},{"t":"40번","mis":"M3-1-u4-X01"},{"t":"79번","mis":"M3-1-u4-X07"},{"t":"270번","mis":"M3-1-u4-X06"}],"explanation":["31번씩 9번(묶음) — 곱셈식 31 × 9로 세워요.","십의 자리 곱 30 × 9 = 270 — 백의 자리로 올림해요.","31 × 9 = 279 — 모두 279번이에요."],"asset":null},{"stem":"색종이를 한 명에게 92장씩 3명에게 나누어 주었어요. 모두 몇 장인가요?","options":[{"t":"276장","correct":true},{"t":"95장","mis":"M3-1-u4-X01"},{"t":"76장","mis":"M3-1-u4-X07"},{"t":"270장","mis":"M3-1-u4-X06"}],"explanation":["92장씩 3번(묶음) — 곱셈식 92 × 3으로 세워요.","십의 자리 곱 90 × 3 = 270 — 백의 자리로 올림해요.","92 × 3 = 276 — 모두 276장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#8','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C5',4,'essay','teacher','줄넘기를 한 번에 43회씩 3번 했어요. 43 × 3을 세로셈으로 계산하는 방법을 쓰고, 백의 자리 숫자가 어디에서 생겼는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u4-C5","difficulty":4,"kind":"essay","stem":"줄넘기를 한 번에 43회씩 3번 했어요. 43 × 3을 세로셈으로 계산하는 방법을 쓰고, 백의 자리 숫자가 어디에서 생겼는지 설명해 보세요.","answer_guide":{"answer":"예: 일의 자리 3 × 3 = 9를 일의 자리에 쓴다. 십의 자리 4 × 3 = 12는 120을 뜻하므로 십의 자리에 2, 백의 자리에 1을 쓴다. 답은 129회이다. 백의 자리 1은 십의 자리 곱 12에서 올림한 것이다.","scoring_points":["일의 자리 9를 구했는가","십의 자리 곱 12에서 백의 자리로 올림했다고 설명했는가","129를 구했는가"]},"explanation":["일의 자리 3 × 3 = 9.","십의 자리 4 × 3 = 12 → 백의 자리 1, 십의 자리 2.","43 × 3 = 129."],"asset":{"type":"expr_grid","rows":[["","","4","3"],["×","","","3"],["","1","2","9"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#9','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C4',4,'essay','teacher','하린이는 52 × 4를 계산해 28이라고 했어요. 어림을 이용해 하린이의 답이 맞는지 판단하고, 바른 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u4-C4","difficulty":4,"kind":"essay","stem":"하린이는 52 × 4를 계산해 28이라고 했어요. 어림을 이용해 하린이의 답이 맞는지 판단하고, 바른 답을 구해 보세요.","answer_guide":{"answer":"예: 52를 50으로 어림하면 50 × 4 = 200이므로 답은 약 200이어야 한다. 28은 너무 작아 틀렸다. 50 × 4 = 200, 2 × 4 = 8이므로 바른 답은 208이다.","scoring_points":["50 × 4 = 200으로 어림했는가","28은 어림한 값과 너무 달라 틀렸다고 판단했는가","바른 답 208을 구했는가"]},"explanation":["어림 약 200.","28은 백의 자리를 빠뜨린 답이에요.","52 × 4 = 208."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L04_challenge#10','math',3,1,'u4','L04','g3_1_math_u4_L04_challenge','lesson_challenge','M3-1-u4-C5',4,'sa','auto','91 × 9의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u4-C5","difficulty":4,"kind":"sa","stem":"91 × 9의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["십의 자리 곱 9 × 9 = 81이에요.","10을 넘은 8이 백의 자리로 올림해요.","91 × 9 = 819 — 백의 자리 숫자는 8이에요."],"variant_rule":{"alt":[{"stem":"73 × 3의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["십의 자리 곱 7 × 3 = 21이에요.","10을 넘은 2가 백의 자리로 올림해요.","73 × 3 = 219 — 백의 자리 숫자는 2예요."],"asset":null},{"stem":"21 × 7의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["십의 자리 곱 2 × 7 = 14예요.","10을 넘은 1이 백의 자리로 올림해요.","21 × 7 = 147 — 백의 자리 숫자는 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#1','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C6',1,'sa','auto','14 × 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u4-C6","difficulty":1,"kind":"sa","stem":"14 × 5는 얼마인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["14를 10과 4로 나누어 곱해요: 10 × 5 = 50, 4 × 5 = 20.","일의 자리 곱 4 × 5 = 20 — 2를 십의 자리로 올림해 더해요.","50 + 20 = 70 — 70은 어림한 10 × 5 = 50과 가까워요."],"variant_rule":{"alt":[{"stem":"16 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["16을 10과 6으로 나누어 곱해요: 10 × 4 = 40, 6 × 4 = 24.","일의 자리 곱 6 × 4 = 24 — 2를 십의 자리로 올림해 더해요.","40 + 24 = 64 — 64는 어림한 20 × 4 = 80과 가까워요."],"asset":null},{"stem":"36 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["36을 30과 6으로 나누어 곱해요: 30 × 2 = 60, 6 × 2 = 12.","일의 자리 곱 6 × 2 = 12 — 1을 십의 자리로 올림해 더해요.","60 + 12 = 72 — 72는 어림한 40 × 2 = 80과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#2','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C6',1,'sa','auto','19 × 4를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u4-C6","difficulty":1,"kind":"sa","stem":"19 × 4를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["일의 자리 9 × 4 = 36이에요.","일의 자리에 6을 쓰고 3을 십의 자리로 올림해요.","십의 자리 1 × 4 = 4에 3을 더해 7이에요."],"asset":{"type":"expr_grid","rows":[["","","1","9"],["×","","","4"],["","",null,null]]},"variant_rule":{"alt":[{"stem":"17 × 4를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리 7 × 4 = 28이에요.","일의 자리에 8을 쓰고 2를 십의 자리로 올림해요.","십의 자리 1 × 4 = 4에 2를 더해 6이에요."],"asset":{"type":"expr_grid","rows":[["","","1","7"],["×","","","4"],["","",null,null]]}},{"stem":"49 × 2를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리 9 × 2 = 18이에요.","일의 자리에 8을 쓰고 1을 십의 자리로 올림해요.","십의 자리 4 × 2 = 8에 1을 더해 9예요."],"asset":{"type":"expr_grid","rows":[["","","4","9"],["×","","","2"],["","",null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#3','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C6',1,'sa','auto','25 × 3을 20과 5로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C6","difficulty":1,"kind":"sa","stem":"25 × 3을 20과 5로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["20 × 3 = 60.","□는 5 × 3 = 15예요.","60 + 15 = 75 — 25 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["20 × 3","=","60"],["5 × 3","=",null],["60 + □","=","75"]]},"variant_rule":{"alt":[{"stem":"26 × 2를 20과 6으로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["12"],"explanation":["20 × 2 = 40.","□는 6 × 2 = 12예요.","40 + 12 = 52 — 26 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["20 × 2","=","40"],["6 × 2","=",null],["40 + □","=","52"]]}},{"stem":"18 × 4를 10과 8로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["32"],"explanation":["10 × 4 = 40.","□는 8 × 4 = 32예요.","40 + 32 = 72 — 18 × 4의 곱이에요."],"asset":{"type":"expr_grid","rows":[["10 × 4","=","40"],["8 × 4","=",null],["40 + □","=","72"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#4','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C6',1,'mc','auto','23 × 4는 얼마인가요?',ARRAY['M3-1-u4-X08','M3-1-u4-X09','M3-1-u4-X04']::text[],true,'{"seq":4,"concept":"M3-1-u4-C6","difficulty":1,"kind":"mc","stem":"23 × 4는 얼마인가요?","options":[{"t":"92","correct":true},{"t":"82","mis":"M3-1-u4-X08"},{"t":"122","mis":"M3-1-u4-X09"},{"t":"32","mis":"M3-1-u4-X04"}],"explanation":["23을 20과 3으로 나누어 곱해요: 20 × 4 = 80, 3 × 4 = 12.","일의 자리 곱 3 × 4 = 12 — 1을 십의 자리로 올림해 더해요.","80 + 12 = 92 — 92는 어림한 20 × 4 = 80과 가까워요."],"variant_rule":{"alt":[{"stem":"36 × 2는 얼마인가요?","options":[{"t":"72","correct":true},{"t":"62","mis":"M3-1-u4-X08"},{"t":"82","mis":"M3-1-u4-X09"},{"t":"42","mis":"M3-1-u4-X04"}],"explanation":["36을 30과 6으로 나누어 곱해요: 30 × 2 = 60, 6 × 2 = 12.","일의 자리 곱 6 × 2 = 12 — 1을 십의 자리로 올림해 더해요.","60 + 12 = 72 — 72는 어림한 40 × 2 = 80과 가까워요."],"asset":null},{"stem":"28 × 2는 얼마인가요?","options":[{"t":"56","correct":true},{"t":"46","mis":"M3-1-u4-X08"},{"t":"66","mis":"M3-1-u4-X09"},{"t":"36","mis":"M3-1-u4-X04"}],"explanation":["28을 20과 8로 나누어 곱해요: 20 × 2 = 40, 8 × 2 = 16.","일의 자리 곱 8 × 2 = 16 — 1을 십의 자리로 올림해 더해요.","40 + 16 = 56 — 56은 어림한 30 × 2 = 60과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#5','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C6',2,'sa','auto','19 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u4-C6","difficulty":2,"kind":"sa","stem":"19 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 1 × 4 = 4 + 올림 3 = 7 → 7을 써요.","19 × 4 = 76 — 십의 자리 숫자는 7이에요."],"asset":{"type":"expr_grid","rows":[["올림","","3",""],["","","1","9"],["×","","","4"],["","",null,"6"]]},"variant_rule":{"alt":[{"stem":"12 × 7의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 1 × 7 = 7 + 올림 1 = 8 → 8을 써요.","12 × 7 = 84 — 십의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1",""],["","","1","2"],["×","","","7"],["","",null,"4"]]}},{"stem":"13 × 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 1 × 5 = 5 + 올림 1 = 6 → 6을 써요.","13 × 5 = 65 — 십의 자리 숫자는 6이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1",""],["","","1","3"],["×","","","5"],["","",null,"5"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#6','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C6',2,'sa','auto','훌라후프를 한 번에 13바퀴씩 6번 돌렸어요. 모두 몇 바퀴 돌렸나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u4-C6","difficulty":2,"kind":"sa","stem":"훌라후프를 한 번에 13바퀴씩 6번 돌렸어요. 모두 몇 바퀴 돌렸나요? 숫자로 쓰세요.","answer":["78"],"explanation":["13바퀴씩 6번(묶음) — 곱셈식 13 × 6으로 세워요.","일의 자리 곱 3 × 6 = 18 — 1을 십의 자리로 올림해 더해요.","13 × 6 = 78 — 모두 78바퀴예요."],"variant_rule":{"alt":[{"stem":"줄넘기를 한 번에 19회씩 3번 했어요. 모두 몇 회 했나요? 숫자로 쓰세요.","answer":["57"],"explanation":["19회씩 3번(묶음) — 곱셈식 19 × 3으로 세워요.","일의 자리 곱 9 × 3 = 27 — 2를 십의 자리로 올림해 더해요.","19 × 3 = 57 — 모두 57회예요."],"asset":null},{"stem":"한 봉지에 사탕이 17개씩 3봉지 있어요. 사탕은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["51"],"explanation":["17개씩 3번(묶음) — 곱셈식 17 × 3으로 세워요.","일의 자리 곱 7 × 3 = 21 — 2를 십의 자리로 올림해 더해요.","17 × 3 = 51 — 모두 51개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#7','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C6',2,'ox','auto','49 × 2를 계산하는데 일의 자리에서 올림한 1을 더하지 않고 88이라고 했어요. 바르게 계산했어요.',ARRAY['M3-1-u4-X08']::text[],true,'{"seq":7,"concept":"M3-1-u4-C6","difficulty":2,"kind":"ox","stem":"49 × 2를 계산하는데 일의 자리에서 올림한 1을 더하지 않고 88이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 십의 자리 곱에 더해야 해서","correct":true},{"t":"올림한 수는 작게 써 두기만 하면 되어서","mis":"M3-1-u4-X08"}],"mis":"M3-1-u4-X08","explanation":["일의 자리 9 × 2 = 18 → 1을 올림해요.","십의 자리 4 × 2 = 8에 1을 더해요.","49 × 2 = 98이에요."],"variant_rule":{"alt":[{"stem":"18 × 5를 계산하는데 일의 자리에서 올림한 4를 더하지 않고 50이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 십의 자리 곱에 더해야 해서","correct":true},{"t":"올림한 수는 작게 써 두기만 하면 되어서","mis":"M3-1-u4-X08"}],"explanation":["일의 자리 8 × 5 = 40 → 4를 올림해요.","십의 자리 1 × 5 = 5에 4를 더해요.","18 × 5 = 90이에요."],"asset":null},{"stem":"18 × 4를 계산하는데 일의 자리에서 올림한 3을 더하지 않고 42라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 십의 자리 곱에 더해야 해서","correct":true},{"t":"올림한 수는 작게 써 두기만 하면 되어서","mis":"M3-1-u4-X08"}],"explanation":["일의 자리 8 × 4 = 32 → 3을 올림해요.","십의 자리 1 × 4 = 4에 3을 더해요.","18 × 4 = 72예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#8','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C4',2,'mc','auto','29 × 2를 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":8,"concept":"M3-1-u4-C4","difficulty":2,"kind":"mc","stem":"29 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 60","correct":true},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X12"},{"t":"약 90","mis":"M3-1-u4-X11"}],"explanation":["29는 가까운 몇십 30으로 어림해요.","30 × 2 = 60이에요.","그래서 29 × 2는 약 60이에요 — 실제 곱 58과 가까워요."],"variant_rule":{"alt":[{"stem":"17 × 5를 어림하면 약 얼마인가요?","options":[{"t":"약 100","correct":true},{"t":"약 50","mis":"M3-1-u4-X12"},{"t":"약 20","mis":"M3-1-u4-X12"},{"t":"약 120","mis":"M3-1-u4-X11"}],"explanation":["17은 가까운 몇십 20으로 어림해요.","20 × 5 = 100이에요.","그래서 17 × 5는 약 100이에요 — 실제 곱 85와 가까워요."],"asset":null},{"stem":"37 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 80","correct":true},{"t":"약 60","mis":"M3-1-u4-X12"},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 120","mis":"M3-1-u4-X11"}],"explanation":["37은 가까운 몇십 40으로 어림해요.","40 × 2 = 80이에요.","그래서 37 × 2는 약 80이에요 — 실제 곱 74와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#9','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C6',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u4-C6","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"15 × 4","r":"60"},{"l":"19 × 2","r":"38"},{"l":"26 × 2","r":"52"}],"mis":"M3-1-u4-X08","explanation":["몇십과 몇으로 나누어 곱하고 더해요.","15 × 4 = 60, 19 × 2 = 38, 26 × 2 = 52.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"23 × 4","r":"92"},{"l":"18 × 4","r":"72"},{"l":"49 × 2","r":"98"}],"explanation":["몇십과 몇으로 나누어 곱하고 더해요.","23 × 4 = 92, 18 × 4 = 72, 49 × 2 = 98.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"17 × 5","r":"85"},{"l":"16 × 5","r":"80"},{"l":"14 × 4","r":"56"}],"explanation":["몇십과 몇으로 나누어 곱하고 더해요.","17 × 5 = 85, 16 × 5 = 80, 14 × 4 = 56.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_basic#10','math',3,1,'u4','L05','g3_1_math_u4_L05_basic','lesson_basic','M3-1-u4-C6',3,'error','auto','19 × 4를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u4-X09','M3-1-u4-X15']::text[],true,'{"seq":10,"concept":"M3-1-u4-C6","difficulty":3,"kind":"error","stem":"19 × 4를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은우 — 「올림한 3을 십의 자리 1에 먼저 더해 4 × 4 — 답은 166이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"하랑 — 「1 × 4 = 4에 올림한 3을 더해 7 — 답은 76이야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「10 × 4 = 40, 9 × 4 = 36, 더하면 76이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 4 = 4, + 3 = 7 — 19 × 4 = 76이에요.","은우는 먼저 더하고 곱해 166이 나왔어요."],"variant_rule":{"alt":[{"stem":"29 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"태오 — 「올림한 1을 십의 자리 2에 먼저 더해 3 × 2 — 답은 68이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"은우 — 「2 × 2 = 4에 올림한 1을 더해 5 — 답은 58이야」","mis":"M3-1-u4-X15"},{"t":"지유 — 「20 × 2 = 40, 9 × 2 = 18, 더하면 58이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","2 × 2 = 4, + 1 = 5 — 29 × 2 = 58이에요.","태오는 먼저 더하고 곱해 68이 나왔어요."],"asset":null},{"stem":"16 × 5를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서윤 — 「올림한 3을 십의 자리 1에 먼저 더해 4 × 5 — 답은 200이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"하랑 — 「1 × 5 = 5에 올림한 3을 더해 8 — 답은 80이야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「10 × 5 = 50, 6 × 5 = 30, 더하면 80이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 5 = 5, + 3 = 8 — 16 × 5 = 80이에요.","서윤은 먼저 더하고 곱해 200이 나왔어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#1','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',2,'sa','auto','27 × 3을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u4-C6","difficulty":2,"kind":"sa","stem":"27 × 3을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리 7 × 3 = 21이에요.","일의 자리에 1을 쓰고 2를 십의 자리로 올림해요.","십의 자리 2 × 3 = 6에 2를 더해 8이에요."],"asset":{"type":"expr_grid","rows":[["","","2","7"],["×","","","3"],["","",null,null]]},"variant_rule":{"alt":[{"stem":"28 × 3을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리 8 × 3 = 24예요.","일의 자리에 4를 쓰고 2를 십의 자리로 올림해요.","십의 자리 2 × 3 = 6에 2를 더해 8이에요."],"asset":{"type":"expr_grid","rows":[["","","2","8"],["×","","","3"],["","",null,null]]}},{"stem":"13 × 4를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리 3 × 4 = 12예요.","일의 자리에 2를 쓰고 1을 십의 자리로 올림해요.","십의 자리 1 × 4 = 4에 1을 더해 5예요."],"asset":{"type":"expr_grid","rows":[["","","1","3"],["×","","","4"],["","",null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#2','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',2,'sa','auto','걷기 운동을 하루에 47분씩 2일 동안 했어요. 모두 몇 분 걸었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u4-C6","difficulty":2,"kind":"sa","stem":"걷기 운동을 하루에 47분씩 2일 동안 했어요. 모두 몇 분 걸었나요? 숫자로 쓰세요.","answer":["94"],"explanation":["47분씩 2번(묶음) — 곱셈식 47 × 2로 세워요.","일의 자리 곱 7 × 2 = 14 — 1을 십의 자리로 올림해 더해요.","47 × 2 = 94 — 모두 94분이에요."],"variant_rule":{"alt":[{"stem":"계단 오르기를 하루에 19칸씩 4일 동안 했어요. 모두 몇 칸 올랐나요? 숫자로 쓰세요.","answer":["76"],"explanation":["19칸씩 4번(묶음) — 곱셈식 19 × 4로 세워요.","일의 자리 곱 9 × 4 = 36 — 3을 십의 자리로 올림해 더해요.","19 × 4 = 76 — 모두 76칸이에요."],"asset":null},{"stem":"한 상자에 귤이 19개씩 5상자 있어요. 귤은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["19개씩 5번(묶음) — 곱셈식 19 × 5로 세워요.","일의 자리 곱 9 × 5 = 45 — 4를 십의 자리로 올림해 더해요.","19 × 5 = 95 — 모두 95개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#3','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',3,'error','auto','23 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X08','M3-1-u4-X15']::text[],true,'{"seq":3,"concept":"M3-1-u4-C6","difficulty":3,"kind":"error","stem":"23 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「23 × 4 = 82야」","correct":true,"mis_target":"M3-1-u4-X08"},{"t":"지유 — 「23 × 4 = 92야」","mis":"M3-1-u4-X15"},{"t":"도윤 — 「어림하면 약 80이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 곱 3 × 4 = 12 — 1을 십의 자리로 올림해 더해요.","23 × 4 = 92예요.","하랑은 82로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"19 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「19 × 3 = 37이야」","correct":true,"mis_target":"M3-1-u4-X08"},{"t":"하린 — 「19 × 3 = 57이야」","mis":"M3-1-u4-X15"},{"t":"도윤 — 「10 × 3 = 30, 9 × 3 = 27, 더하면 57이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 곱 9 × 3 = 27 — 2를 십의 자리로 올림해 더해요.","19 × 3 = 57이에요.","하랑은 37로 잘못 구했어요."],"asset":null},{"stem":"18 × 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「18 × 5 = 50이야」","correct":true,"mis_target":"M3-1-u4-X08"},{"t":"지유 — 「18 × 5 = 90이야」","mis":"M3-1-u4-X15"},{"t":"서윤 — 「어림하면 약 100이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 곱 8 × 5 = 40 — 4를 십의 자리로 올림해 더해요.","18 × 5 = 90이에요.","시우는 50으로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#4','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',3,'sa','auto','16 × 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u4-C6","difficulty":3,"kind":"sa","stem":"16 × 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 1 × 6 = 6 + 올림 3 = 9 → 9를 써요.","16 × 6 = 96 — 십의 자리 숫자는 9예요."],"asset":{"type":"expr_grid","rows":[["올림","","3",""],["","","1","6"],["×","","","6"],["","",null,"6"]]},"variant_rule":{"alt":[{"stem":"14 × 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 1 × 6 = 6 + 올림 2 = 8 → 8을 써요.","14 × 6 = 84 — 십의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["올림","","2",""],["","","1","4"],["×","","","6"],["","",null,"4"]]}},{"stem":"14 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 1 × 4 = 4 + 올림 1 = 5 → 5를 써요.","14 × 4 = 56 — 십의 자리 숫자는 5예요."],"asset":{"type":"expr_grid","rows":[["올림","","1",""],["","","1","4"],["×","","","4"],["","",null,"6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#5','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 18 × 5 ○ 23 × 4',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":5,"concept":"M3-1-u4-C6","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 18 × 5 ○ 23 × 4","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["18 × 5 = 90이에요.","23 × 4 = 92예요.","90 < 92 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 14 × 4 ○ 14 × 5","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["14 × 4 = 56이에요.","14 × 5 = 70이에요.","56 < 70 — 알맞은 것은 <예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 18 × 4 ○ 12 × 5","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["18 × 4 = 72예요.","12 × 5 = 60이에요.","72 > 60 — 알맞은 것은 >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#6','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',3,'error','auto','26 × 3을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u4-X09','M3-1-u4-X15']::text[],true,'{"seq":6,"concept":"M3-1-u4-C6","difficulty":3,"kind":"error","stem":"26 × 3을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린 — 「올림한 1을 십의 자리 2에 먼저 더해 3 × 3 — 답은 98이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"은우 — 「2 × 3 = 6에 올림한 1을 더해 7 — 답은 78이야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「20 × 3 = 60, 6 × 3 = 18, 더하면 78이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","2 × 3 = 6, + 1 = 7 — 26 × 3 = 78이에요.","하린은 먼저 더하고 곱해 98이 나왔어요."],"variant_rule":{"alt":[{"stem":"12 × 5를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하랑 — 「올림한 1을 십의 자리 1에 먼저 더해 2 × 5 — 답은 100이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"서윤 — 「1 × 5 = 5에 올림한 1을 더해 6 — 답은 60이야」","mis":"M3-1-u4-X15"},{"t":"하린 — 「10 × 5 = 50, 2 × 5 = 10, 더하면 60이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 5 = 5, + 1 = 6 — 12 × 5 = 60이에요.","하랑은 먼저 더하고 곱해 100이 나왔어요."],"asset":null},{"stem":"14 × 7을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시우 — 「올림한 2를 십의 자리 1에 먼저 더해 3 × 7 — 답은 218이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"지유 — 「1 × 7 = 7에 올림한 2를 더해 9 — 답은 98이야」","mis":"M3-1-u4-X15"},{"t":"하린 — 「10 × 7 = 70, 4 × 7 = 28, 더하면 98이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 7 = 7, + 2 = 9 — 14 × 7 = 98이에요.","시우는 먼저 더하고 곱해 218이 나왔어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#7','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',3,'sa','auto','1□ × 4 = 68 — □에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u4-C6","difficulty":3,"kind":"sa","stem":"1□ × 4 = 68 — □에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["먼저 10 × 4 = 40이에요.","남은 68 − 40 = 28이 일의 자리 곱이에요.","□ × 4 = 28 → □ = 7이에요."],"variant_rule":{"alt":[{"stem":"1□ × 7 = 98 — □에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["먼저 10 × 7 = 70이에요.","남은 98 − 70 = 28이 일의 자리 곱이에요.","□ × 7 = 28 → □ = 4예요."],"asset":null},{"stem":"2□ × 2 = 54 — □에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["먼저 20 × 2 = 40이에요.","남은 54 − 40 = 14가 일의 자리 곱이에요.","□ × 2 = 14 → □ = 7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#8','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',4,'essay','teacher','체조를 한 번에 19분씩 4번 했어요. 19 × 4를 세로셈으로 계산하는 방법을 쓰고, 올림한 수를 어떻게 처리하는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u4-C6","difficulty":4,"kind":"essay","stem":"체조를 한 번에 19분씩 4번 했어요. 19 × 4를 세로셈으로 계산하는 방법을 쓰고, 올림한 수를 어떻게 처리하는지 설명해 보세요.","answer_guide":{"answer":"예: 일의 자리 9 × 4 = 36에서 6을 일의 자리에 쓰고 3을 십의 자리로 올림한다. 십의 자리 1 × 4 = 4에 올림한 3을 더해 7을 쓴다. 답은 76분이다. 어림하면 20 × 4 = 80이라 맞다.","scoring_points":["9 × 4 = 36에서 3을 올림했는가","1 × 4 = 4에 올림한 3을 더했는가","76을 구했는가"]},"explanation":["9 × 4 = 36 → 6 쓰고 3 올림.","1 × 4 + 3 = 7.","19 × 4 = 76."],"asset":{"type":"expr_grid","rows":[["올림","","3",""],["","","1","9"],["×","","","4"],["","","7","6"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#9','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',4,'essay','teacher','시우는 49 × 2를 88이라고 했어요. 무엇을 빠뜨렸는지 찾고, 바른 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u4-C6","difficulty":4,"kind":"essay","stem":"시우는 49 × 2를 88이라고 했어요. 무엇을 빠뜨렸는지 찾고, 바른 답을 구해 보세요.","answer_guide":{"answer":"예: 일의 자리 9 × 2 = 18에서 올림한 1을 십의 자리 곱 4 × 2 = 8에 더하지 않았다. 8 + 1 = 9이므로 바른 답은 98이다. 어림하면 50 × 2 = 100에 가깝다.","scoring_points":["올림한 1을 더하지 않았다고 찾았는가","8 + 1 = 9로 고쳤는가","바른 답 98을 구했는가"]},"explanation":["9 × 2 = 18 → 1 올림.","4 × 2 = 8에 1을 더해 9.","49 × 2 = 98."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L05_challenge#10','math',3,1,'u4','L05','g3_1_math_u4_L05_challenge','lesson_challenge','M3-1-u4-C6',4,'sa','auto','지유는 줄넘기를 한 번에 17회씩 4번, 은우는 한 번에 38회씩 2번 했어요. 두 사람이 넘은 횟수의 차는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u4-C6","difficulty":4,"kind":"sa","stem":"지유는 줄넘기를 한 번에 17회씩 4번, 은우는 한 번에 38회씩 2번 했어요. 두 사람이 넘은 횟수의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["지유: 17 × 4 = 68회.","은우: 38 × 2 = 76회.","76 − 68 = 8 — 은우가 8회 더 했어요."],"variant_rule":{"alt":[{"stem":"하린은 줄넘기를 한 번에 16회씩 4번, 태오는 한 번에 13회씩 6번 했어요. 두 사람이 넘은 횟수의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["하린: 16 × 4 = 64회.","태오: 13 × 6 = 78회.","78 − 64 = 14 — 태오가 14회 더 했어요."],"asset":null},{"stem":"태오는 줄넘기를 한 번에 12회씩 8번, 은우는 한 번에 18회씩 3번 했어요. 두 사람이 넘은 횟수의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["태오: 12 × 8 = 96회.","은우: 18 × 3 = 54회.","96 − 54 = 42 — 태오가 42회 더 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#1','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C7',1,'mc','auto','36 × 4는 얼마인가요?',ARRAY['M3-1-u4-X08','M3-1-u4-X07','M3-1-u4-X09']::text[],true,'{"seq":1,"concept":"M3-1-u4-C7","difficulty":1,"kind":"mc","stem":"36 × 4는 얼마인가요?","options":[{"t":"144","correct":true},{"t":"124","mis":"M3-1-u4-X08"},{"t":"44","mis":"M3-1-u4-X07"},{"t":"204","mis":"M3-1-u4-X09"}],"explanation":["36을 30과 6으로 나누어 곱해요: 30 × 4 = 120, 6 × 4 = 24.","일의 자리 24 → 2 올림, 십의 자리 3 × 4 + 2 = 14 — 백의 자리까지 올림해요.","120 + 24 = 144 — 144는 어림한 40 × 4 = 160과 가까워요."],"variant_rule":{"alt":[{"stem":"18 × 6은 얼마인가요?","options":[{"t":"108","correct":true},{"t":"68","mis":"M3-1-u4-X08"},{"t":"8","mis":"M3-1-u4-X07"},{"t":"308","mis":"M3-1-u4-X09"}],"explanation":["18을 10과 8로 나누어 곱해요: 10 × 6 = 60, 8 × 6 = 48.","일의 자리 48 → 4 올림, 십의 자리 1 × 6 + 4 = 10 — 백의 자리까지 올림해요.","60 + 48 = 108 — 108은 어림한 20 × 6 = 120과 가까워요."],"asset":null},{"stem":"48 × 4는 얼마인가요?","options":[{"t":"192","correct":true},{"t":"162","mis":"M3-1-u4-X08"},{"t":"92","mis":"M3-1-u4-X07"},{"t":"282","mis":"M3-1-u4-X09"}],"explanation":["48을 40과 8로 나누어 곱해요: 40 × 4 = 160, 8 × 4 = 32.","일의 자리 32 → 3 올림, 십의 자리 4 × 4 + 3 = 19 — 백의 자리까지 올림해요.","160 + 32 = 192 — 192는 어림한 50 × 4 = 200과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#2','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C7',1,'sa','auto','35 × 5를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u4-C7","difficulty":1,"kind":"sa","stem":"35 × 5를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리 5 × 5 = 25예요.","일의 자리에 5를 쓰고 2를 십의 자리로 올림해요.","십의 자리 3 × 5 = 15에 2를 더해 17이에요."],"asset":{"type":"expr_grid","rows":[["","","3","5"],["×","","","5"],["",null,null,null]]},"variant_rule":{"alt":[{"stem":"49 × 7을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["일의 자리 9 × 7 = 63이에요.","일의 자리에 3을 쓰고 6을 십의 자리로 올림해요.","십의 자리 4 × 7 = 28에 6을 더해 34예요."],"asset":{"type":"expr_grid","rows":[["","","4","9"],["×","","","7"],["",null,null,null]]}},{"stem":"77 × 4를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리 7 × 4 = 28이에요.","일의 자리에 8을 쓰고 2를 십의 자리로 올림해요.","십의 자리 7 × 4 = 28에 2를 더해 30이에요."],"asset":{"type":"expr_grid","rows":[["","","7","7"],["×","","","4"],["",null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#3','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C7',1,'sa','auto','54 × 3의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C7","difficulty":1,"kind":"sa","stem":"54 × 3의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["십의 자리 곱 5 × 3 = 15예요.","10을 넘은 1이 백의 자리로 올림해요.","54 × 3 = 162 — 백의 자리 숫자는 1이에요."],"variant_rule":{"alt":[{"stem":"98 × 8의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["십의 자리 곱 9 × 8 = 72예요.","10을 넘은 7이 백의 자리로 올림해요.","98 × 8 = 784 — 백의 자리 숫자는 7이에요."],"asset":null},{"stem":"92 × 8의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["십의 자리 곱 9 × 8 = 72예요.","10을 넘은 7이 백의 자리로 올림해요.","92 × 8 = 736 — 백의 자리 숫자는 7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#4','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C7',1,'mc','auto','35 × 5를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?',ARRAY['M3-1-u4-X06','M3-1-u4-X11']::text[],true,'{"seq":4,"concept":"M3-1-u4-C7","difficulty":1,"kind":"mc","stem":"35 × 5를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"175","correct":true},{"t":"150","mis":"M3-1-u4-X06"},{"t":"25","mis":"M3-1-u4-X06"},{"t":"185","mis":"M3-1-u4-X11"}],"explanation":["나누어 곱한 두 곱을 더해요.","150 + 25 = 175예요.","하나만 쓰면 35 × 5의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["30 × 5","=","150"],["5 × 5","=","25"],["150 + 25","=",null]]},"variant_rule":{"alt":[{"stem":"56 × 7을 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"392","correct":true},{"t":"350","mis":"M3-1-u4-X06"},{"t":"42","mis":"M3-1-u4-X06"},{"t":"402","mis":"M3-1-u4-X11"}],"explanation":["나누어 곱한 두 곱을 더해요.","350 + 42 = 392예요.","하나만 쓰면 56 × 7의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["50 × 7","=","350"],["6 × 7","=","42"],["350 + 42","=",null]]}},{"stem":"63 × 9를 나누어 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"567","correct":true},{"t":"540","mis":"M3-1-u4-X06"},{"t":"27","mis":"M3-1-u4-X06"},{"t":"577","mis":"M3-1-u4-X11"}],"explanation":["나누어 곱한 두 곱을 더해요.","540 + 27 = 567이에요.","하나만 쓰면 63 × 9의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["60 × 9","=","540"],["3 × 9","=","27"],["540 + 27","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#5','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C7',2,'sa','auto','35 × 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u4-C7","difficulty":2,"kind":"sa","stem":"35 × 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리 곱 17이 10을 넘어 백의 자리에 1을 써요.","35 × 5 = 175 — 백의 자리 숫자는 1이에요."],"asset":{"type":"expr_grid","rows":[["올림","","2",""],["","","3","5"],["×","","","5"],["",null,"7","5"]]},"variant_rule":{"alt":[{"stem":"53 × 8의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 5 × 8 = 40 + 올림 2 = 42 → 2를 써요.","53 × 8 = 424 — 십의 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["올림","","2",""],["","","5","3"],["×","","","8"],["","4",null,"4"]]}},{"stem":"98 × 9의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 9 × 9 = 81 + 올림 7 = 88 → 8을 써요.","98 × 9 = 882 — 십의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["올림","","7",""],["","","9","8"],["×","","","9"],["","8",null,"2"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#6','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C7',2,'mc','auto','계단 오르기를 하루에 68칸씩 4일 동안 했어요. 모두 몇 칸 올랐나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X08','M3-1-u4-X09']::text[],true,'{"seq":6,"concept":"M3-1-u4-C7","difficulty":2,"kind":"mc","stem":"계단 오르기를 하루에 68칸씩 4일 동안 했어요. 모두 몇 칸 올랐나요?","options":[{"t":"272칸","correct":true},{"t":"72칸","mis":"M3-1-u4-X01"},{"t":"242칸","mis":"M3-1-u4-X08"},{"t":"362칸","mis":"M3-1-u4-X09"}],"explanation":["68칸씩 4번(묶음) — 곱셈식 68 × 4로 세워요.","일의 자리 32 → 3 올림, 십의 자리 6 × 4 + 3 = 27 — 백의 자리까지 올림해요.","68 × 4 = 272 — 모두 272칸이에요."],"variant_rule":{"alt":[{"stem":"책꽂이 한 칸에 책을 74권씩 6칸에 꽂았어요. 책은 모두 몇 권인가요?","options":[{"t":"444권","correct":true},{"t":"80권","mis":"M3-1-u4-X01"},{"t":"424권","mis":"M3-1-u4-X08"},{"t":"44권","mis":"M3-1-u4-X07"}],"explanation":["74권씩 6번(묶음) — 곱셈식 74 × 6으로 세워요.","일의 자리 24 → 2 올림, 십의 자리 7 × 6 + 2 = 44 — 백의 자리까지 올림해요.","74 × 6 = 444 — 모두 444권이에요."],"asset":null},{"stem":"줄넘기를 한 번에 56회씩 2번 했어요. 모두 몇 회 했나요?","options":[{"t":"112회","correct":true},{"t":"58회","mis":"M3-1-u4-X01"},{"t":"102회","mis":"M3-1-u4-X08"},{"t":"12회","mis":"M3-1-u4-X07"}],"explanation":["56회씩 2번(묶음) — 곱셈식 56 × 2로 세워요.","일의 자리 12 → 1 올림, 십의 자리 5 × 2 + 1 = 11 — 백의 자리까지 올림해요.","56 × 2 = 112 — 모두 112회예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#7','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C7',2,'ox','auto','35 × 5를 계산하는데 3 × 5 = 15, 5 × 5 = 25를 이어 붙여 1525라고 했어요. 바르게 계산했어요.',ARRAY['M3-1-u4-X10']::text[],true,'{"seq":7,"concept":"M3-1-u4-C7","difficulty":2,"kind":"ox","stem":"35 × 5를 계산하는데 3 × 5 = 15, 5 × 5 = 25를 이어 붙여 1525라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"10이 넘는 곱은 윗자리로 올림해 더해야 해서","correct":true},{"t":"자리별 곱을 그대로 이어 쓰면 되어서","mis":"M3-1-u4-X10"}],"mis":"M3-1-u4-X10","explanation":["일의 자리 25 → 5 쓰고 2 올림.","십의 자리 15 + 2 = 17 → 7 쓰고 백의 자리 1.","35 × 5 = 175 — 어림한 약 200과 가까워요."],"variant_rule":{"alt":[{"stem":"42 × 7을 계산하는데 4 × 7 = 28, 2 × 7 = 14를 이어 붙여 2814라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"10이 넘는 곱은 윗자리로 올림해 더해야 해서","correct":true},{"t":"자리별 곱을 그대로 이어 쓰면 되어서","mis":"M3-1-u4-X10"}],"explanation":["일의 자리 14 → 4 쓰고 1 올림.","십의 자리 28 + 1 = 29 → 9 쓰고 백의 자리 2.","42 × 7 = 294 — 어림한 약 280과 가까워요."],"asset":null},{"stem":"43 × 5를 계산하는데 4 × 5 = 20, 3 × 5 = 15를 이어 붙여 2015라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"10이 넘는 곱은 윗자리로 올림해 더해야 해서","correct":true},{"t":"자리별 곱을 그대로 이어 쓰면 되어서","mis":"M3-1-u4-X10"}],"explanation":["일의 자리 15 → 5 쓰고 1 올림.","십의 자리 20 + 1 = 21 → 1 쓰고 백의 자리 2.","43 × 5 = 215 — 어림한 약 200과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#8','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C4',2,'mc','auto','39 × 9를 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":8,"concept":"M3-1-u4-C4","difficulty":2,"kind":"mc","stem":"39 × 9를 어림하면 약 얼마인가요?","options":[{"t":"약 360","correct":true},{"t":"약 270","mis":"M3-1-u4-X12"},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 400","mis":"M3-1-u4-X11"}],"explanation":["39는 가까운 몇십 40으로 어림해요.","40 × 9 = 360이에요.","그래서 39 × 9는 약 360이에요 — 실제 곱 351과 가까워요."],"variant_rule":{"alt":[{"stem":"36 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 120","correct":true},{"t":"약 90","mis":"M3-1-u4-X12"},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 160","mis":"M3-1-u4-X11"}],"explanation":["36은 가까운 몇십 40으로 어림해요.","40 × 3 = 120이에요.","그래서 36 × 3은 약 120이에요 — 실제 곱 108과 가까워요."],"asset":null},{"stem":"57 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 180","correct":true},{"t":"약 150","mis":"M3-1-u4-X12"},{"t":"약 60","mis":"M3-1-u4-X12"},{"t":"약 240","mis":"M3-1-u4-X11"}],"explanation":["57은 가까운 몇십 60으로 어림해요.","60 × 3 = 180이에요.","그래서 57 × 3은 약 180이에요 — 실제 곱 171과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#9','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C7',2,'ox','auto','48 × 3을 계산하는데 일의 자리에서 올림한 2를 더하지 않고 124라고 했어요. 바르게 계산했어요.',ARRAY['M3-1-u4-X08']::text[],true,'{"seq":9,"concept":"M3-1-u4-C7","difficulty":2,"kind":"ox","stem":"48 × 3을 계산하는데 일의 자리에서 올림한 2를 더하지 않고 124라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 십의 자리 곱에 더해야 해서","correct":true},{"t":"올림한 수는 작게 써 두기만 하면 되어서","mis":"M3-1-u4-X08"}],"mis":"M3-1-u4-X08","explanation":["일의 자리 8 × 3 = 24 → 2를 올림해요.","십의 자리 4 × 3 = 12에 2를 더해요.","48 × 3 = 144예요."],"variant_rule":{"alt":[{"stem":"23 × 9를 계산하는데 일의 자리에서 올림한 2를 더하지 않고 187이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 십의 자리 곱에 더해야 해서","correct":true},{"t":"올림한 수는 작게 써 두기만 하면 되어서","mis":"M3-1-u4-X08"}],"explanation":["일의 자리 3 × 9 = 27 → 2를 올림해요.","십의 자리 2 × 9 = 18에 2를 더해요.","23 × 9 = 207이에요."],"asset":null},{"stem":"33 × 4를 계산하는데 일의 자리에서 올림한 1을 더하지 않고 122라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 십의 자리 곱에 더해야 해서","correct":true},{"t":"올림한 수는 작게 써 두기만 하면 되어서","mis":"M3-1-u4-X08"}],"explanation":["일의 자리 3 × 4 = 12 → 1을 올림해요.","십의 자리 3 × 4 = 12에 1을 더해요.","33 × 4 = 132예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_basic#10','math',3,1,'u4','L06','g3_1_math_u4_L06_basic','lesson_basic','M3-1-u4-C7',3,'error','auto','53 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X08','M3-1-u4-X15']::text[],true,'{"seq":10,"concept":"M3-1-u4-C7","difficulty":3,"kind":"error","stem":"53 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「53 × 7 = 351이야」","correct":true,"mis_target":"M3-1-u4-X08"},{"t":"도윤 — 「53 × 7 = 371이야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「어림하면 약 350이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 21 → 2 올림, 십의 자리 5 × 7 + 2 = 37 — 백의 자리까지 올림해요.","53 × 7 = 371이에요.","하린은 351로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"19 × 9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「19 × 9 = 91이야」","correct":true,"mis_target":"M3-1-u4-X08"},{"t":"태오 — 「19 × 9 = 171이야」","mis":"M3-1-u4-X15"},{"t":"지유 — 「10 × 9 = 90, 9 × 9 = 81, 더하면 171이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 81 → 8 올림, 십의 자리 1 × 9 + 8 = 17 — 백의 자리까지 올림해요.","19 × 9 = 171이에요.","시우는 91로 잘못 구했어요."],"asset":null},{"stem":"74 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「74 × 8 = 562야」","correct":true,"mis_target":"M3-1-u4-X08"},{"t":"서윤 — 「74 × 8 = 592야」","mis":"M3-1-u4-X15"},{"t":"도윤 — 「어림하면 약 560이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 32 → 3 올림, 십의 자리 7 × 8 + 3 = 59 — 백의 자리까지 올림해요.","74 × 8 = 592예요.","하랑은 562로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#1','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',2,'mc','auto','35 × 5의 곱은 어느 범위에 있나요?',ARRAY['M3-1-u4-X12','M3-1-u4-X03']::text[],true,'{"seq":1,"concept":"M3-1-u4-C7","difficulty":2,"kind":"mc","stem":"35 × 5의 곱은 어느 범위에 있나요?","options":[{"t":"150보다 크고 200보다 작아요","correct":true},{"t":"150보다 작아요","mis":"M3-1-u4-X12"},{"t":"200보다 커요","mis":"M3-1-u4-X12"},{"t":"15보다 크고 20보다 작아요","mis":"M3-1-u4-X03"}],"explanation":["35는 30과 40 사이의 수예요.","30 × 5 = 150, 40 × 5 = 200이에요.","35 × 5 = 175 — 그 사이에 있어요."],"variant_rule":{"alt":[{"stem":"54 × 8의 곱은 어느 범위에 있나요?","options":[{"t":"400보다 크고 480보다 작아요","correct":true},{"t":"400보다 작아요","mis":"M3-1-u4-X12"},{"t":"480보다 커요","mis":"M3-1-u4-X12"},{"t":"40보다 크고 48보다 작아요","mis":"M3-1-u4-X03"}],"explanation":["54는 50과 60 사이의 수예요.","50 × 8 = 400, 60 × 8 = 480이에요.","54 × 8 = 432 — 그 사이에 있어요."],"asset":null},{"stem":"98 × 6의 곱은 어느 범위에 있나요?","options":[{"t":"540보다 크고 600보다 작아요","correct":true},{"t":"540보다 작아요","mis":"M3-1-u4-X12"},{"t":"600보다 커요","mis":"M3-1-u4-X12"},{"t":"54보다 크고 60보다 작아요","mis":"M3-1-u4-X03"}],"explanation":["98은 90과 100 사이의 수예요.","90 × 6 = 540, 100 × 6 = 600이에요.","98 × 6 = 588 — 그 사이에 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#2','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u4-C7","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"63 × 9","r":"567"},{"l":"23 × 7","r":"161"},{"l":"83 × 9","r":"747"}],"mis":"M3-1-u4-X08","explanation":["몇십과 몇으로 나누어 곱하고 더해요.","63 × 9 = 567, 23 × 7 = 161, 83 × 9 = 747.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"99 × 4","r":"396"},{"l":"96 × 9","r":"864"},{"l":"74 × 8","r":"592"}],"explanation":["몇십과 몇으로 나누어 곱하고 더해요.","99 × 4 = 396, 96 × 9 = 864, 74 × 8 = 592.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"86 × 2","r":"172"},{"l":"47 × 3","r":"141"},{"l":"24 × 9","r":"216"}],"explanation":["몇십과 몇으로 나누어 곱하고 더해요.","86 × 2 = 172, 47 × 3 = 141, 24 × 9 = 216.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#3','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',3,'sa','auto','74 × 8의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C7","difficulty":3,"kind":"sa","stem":"74 × 8의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리 곱 59가 10을 넘어 백의 자리에 5를 써요.","74 × 8 = 592 — 백의 자리 숫자는 5예요."],"asset":{"type":"expr_grid","rows":[["올림","","3",""],["","","7","4"],["×","","","8"],["",null,"9","2"]]},"variant_rule":{"alt":[{"stem":"59 × 9의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 5 × 9 = 45 + 올림 8 = 53 → 3을 써요.","59 × 9 = 531 — 십의 자리 숫자는 3이에요."],"asset":{"type":"expr_grid","rows":[["올림","","8",""],["","","5","9"],["×","","","9"],["","5",null,"1"]]}},{"stem":"97 × 8의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 9 × 8 = 72 + 올림 5 = 77 → 7을 써요.","97 × 8 = 776 — 십의 자리 숫자는 7이에요."],"asset":{"type":"expr_grid","rows":[["올림","","5",""],["","","9","7"],["×","","","8"],["","7",null,"6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#4','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',3,'mc','auto','계단 오르기를 하루에 74칸씩 8일 동안 했어요. 모두 몇 칸 올랐나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X08','M3-1-u4-X07']::text[],true,'{"seq":4,"concept":"M3-1-u4-C7","difficulty":3,"kind":"mc","stem":"계단 오르기를 하루에 74칸씩 8일 동안 했어요. 모두 몇 칸 올랐나요?","options":[{"t":"592칸","correct":true},{"t":"82칸","mis":"M3-1-u4-X01"},{"t":"562칸","mis":"M3-1-u4-X08"},{"t":"92칸","mis":"M3-1-u4-X07"}],"explanation":["74칸씩 8번(묶음) — 곱셈식 74 × 8로 세워요.","일의 자리 32 → 3 올림, 십의 자리 7 × 8 + 3 = 59 — 백의 자리까지 올림해요.","74 × 8 = 592 — 모두 592칸이에요."],"variant_rule":{"alt":[{"stem":"훌라후프를 한 번에 53바퀴씩 9번 돌렸어요. 모두 몇 바퀴 돌렸나요?","options":[{"t":"477바퀴","correct":true},{"t":"62바퀴","mis":"M3-1-u4-X01"},{"t":"457바퀴","mis":"M3-1-u4-X08"},{"t":"77바퀴","mis":"M3-1-u4-X07"}],"explanation":["53바퀴씩 9번(묶음) — 곱셈식 53 × 9로 세워요.","일의 자리 27 → 2 올림, 십의 자리 5 × 9 + 2 = 47 — 백의 자리까지 올림해요.","53 × 9 = 477 — 모두 477바퀴예요."],"asset":null},{"stem":"길이가 33cm인 골판지 5개를 겹치지 않게 이었어요. 모두 몇 cm인가요?","options":[{"t":"165cm","correct":true},{"t":"38cm","mis":"M3-1-u4-X01"},{"t":"155cm","mis":"M3-1-u4-X08"},{"t":"65cm","mis":"M3-1-u4-X07"}],"explanation":["33cm씩 5번(묶음) — 곱셈식 33 × 5로 세워요.","일의 자리 15 → 1 올림, 십의 자리 3 × 5 + 1 = 16 — 백의 자리까지 올림해요.","33 × 5 = 165 — 모두 165cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#5','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',3,'error','auto','38 × 6을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u4-X09','M3-1-u4-X15']::text[],true,'{"seq":5,"concept":"M3-1-u4-C7","difficulty":3,"kind":"error","stem":"38 × 6을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"지유 — 「올림한 4를 십의 자리 3에 먼저 더해 7 × 6 — 답은 428이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"은우 — 「3 × 6 = 18에 올림한 4를 더해 22 — 답은 228이야」","mis":"M3-1-u4-X15"},{"t":"하린 — 「30 × 6 = 180, 8 × 6 = 48, 더하면 228이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","3 × 6 = 18, + 4 = 22 — 38 × 6 = 228이에요.","지유는 먼저 더하고 곱해 428이 나왔어요."],"variant_rule":{"alt":[{"stem":"34 × 8을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서윤 — 「올림한 3을 십의 자리 3에 먼저 더해 6 × 8 — 답은 482야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"하랑 — 「3 × 8 = 24에 올림한 3을 더해 27 — 답은 272야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「30 × 8 = 240, 4 × 8 = 32, 더하면 272야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","3 × 8 = 24, + 3 = 27 — 34 × 8 = 272예요.","서윤은 먼저 더하고 곱해 482가 나왔어요."],"asset":null},{"stem":"37 × 7을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은우 — 「올림한 4를 십의 자리 3에 먼저 더해 7 × 7 — 답은 499야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"태오 — 「3 × 7 = 21에 올림한 4를 더해 25 — 답은 259야」","mis":"M3-1-u4-X15"},{"t":"서윤 — 「30 × 7 = 210, 7 × 7 = 49, 더하면 259야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","3 × 7 = 21, + 4 = 25 — 37 × 7 = 259예요.","은우는 먼저 더하고 곱해 499가 나왔어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#6','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 47 × 6 ○ 67 × 4',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":6,"concept":"M3-1-u4-C7","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 47 × 6 ○ 67 × 4","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["47 × 6 = 282예요.","67 × 4 = 268이에요.","282 > 268 — 알맞은 것은 >예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 74 × 4 ○ 94 × 3","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["74 × 4 = 296이에요.","94 × 3 = 282예요.","296 > 282 — 알맞은 것은 >예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 96 × 5 ○ 74 × 7","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["96 × 5 = 480이에요.","74 × 7 = 518이에요.","480 < 518 — 알맞은 것은 <예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#7','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',3,'error','auto','86 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X08','M3-1-u4-X15']::text[],true,'{"seq":7,"concept":"M3-1-u4-C7","difficulty":3,"kind":"error","stem":"86 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「86 × 7 = 562야」","correct":true,"mis_target":"M3-1-u4-X08"},{"t":"서윤 — 「86 × 7 = 602야」","mis":"M3-1-u4-X15"},{"t":"지유 — 「80 × 7 = 560, 6 × 7 = 42, 더하면 602야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 42 → 4 올림, 십의 자리 8 × 7 + 4 = 60 — 백의 자리까지 올림해요.","86 × 7 = 602예요.","은우는 562로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"97 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「97 × 8 = 726이야」","correct":true,"mis_target":"M3-1-u4-X08"},{"t":"하랑 — 「97 × 8 = 776이야」","mis":"M3-1-u4-X15"},{"t":"하린 — 「어림하면 약 800이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 56 → 5 올림, 십의 자리 9 × 8 + 5 = 77 — 백의 자리까지 올림해요.","97 × 8 = 776이에요.","지유는 726으로 잘못 구했어요."],"asset":null},{"stem":"42 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「42 × 8 = 326이야」","correct":true,"mis_target":"M3-1-u4-X08"},{"t":"지유 — 「42 × 8 = 336이야」","mis":"M3-1-u4-X15"},{"t":"서윤 — 「40 × 8 = 320, 2 × 8 = 16, 더하면 336이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 16 → 1 올림, 십의 자리 4 × 8 + 1 = 33 — 백의 자리까지 올림해요.","42 × 8 = 336이에요.","도윤은 326으로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#8','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',4,'essay','teacher','줄넘기를 한 번에 35회씩 5번 했어요. 35 × 5를 몇십과 몇으로 나누어 계산하는 방법과 세로셈으로 계산하는 방법을 각각 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u4-C7","difficulty":4,"kind":"essay","stem":"줄넘기를 한 번에 35회씩 5번 했어요. 35 × 5를 몇십과 몇으로 나누어 계산하는 방법과 세로셈으로 계산하는 방법을 각각 써 보세요.","answer_guide":{"answer":"예: 나누어 곱하기 — 30 × 5 = 150, 5 × 5 = 25, 더하면 175이다. 세로셈 — 일의 자리 5 × 5 = 25에서 5를 쓰고 2를 올림, 십의 자리 3 × 5 = 15에 2를 더해 17, 7을 쓰고 1을 백의 자리에 쓴다. 답은 175회이다.","scoring_points":["150 + 25 = 175로 나누어 곱했는가","세로셈에서 올림 두 번을 바르게 처리했는가","175를 구했는가"]},"explanation":["30 × 5 = 150, 5 × 5 = 25.","세로셈: 25 → 2 올림, 15 + 2 = 17.","35 × 5 = 175."],"asset":{"type":"expr_grid","rows":[["올림","","2",""],["","","3","5"],["×","","","5"],["","1","7","5"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#9','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',4,'essay','teacher','은우는 48 × 3을 124라고 했어요. 은우가 어디에서 실수했는지 찾고, 어림과 함께 바른 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u4-C7","difficulty":4,"kind":"essay","stem":"은우는 48 × 3을 124라고 했어요. 은우가 어디에서 실수했는지 찾고, 어림과 함께 바른 답을 구해 보세요.","answer_guide":{"answer":"예: 일의 자리 8 × 3 = 24에서 올림한 2를 십의 자리 곱 4 × 3 = 12에 더하지 않았다. 12 + 2 = 14이므로 바른 답은 144이다. 50 × 3 = 150으로 어림하면 144가 가깝다.","scoring_points":["일의 자리 올림 2를 빠뜨렸다고 찾았는가","12 + 2 = 14로 고쳐 144를 구했는가","약 150으로 어림해 확인했는가"]},"explanation":["8 × 3 = 24 → 2 올림.","4 × 3 = 12에 2를 더해 14 — 144.","어림 약 150 — 144가 가까워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L06_challenge#10','math',3,1,'u4','L06','g3_1_math_u4_L06_challenge','lesson_challenge','M3-1-u4-C7',4,'mc','auto','곱이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":10,"concept":"M3-1-u4-C7","difficulty":4,"kind":"mc","stem":"곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"87 × 6","correct":true},{"t":"94 × 5","mis":"M3-1-u4-X11"},{"t":"99 × 4","mis":"M3-1-u4-X15"},{"t":"87 × 5","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","87 × 6 = 522, 94 × 5 = 470, 99 × 4 = 396, 87 × 5 = 435.","곱이 가장 큰 것은 87 × 6 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"46 × 7","correct":true},{"t":"54 × 4","mis":"M3-1-u4-X11"},{"t":"66 × 3","mis":"M3-1-u4-X15"},{"t":"47 × 6","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","46 × 7 = 322, 54 × 4 = 216, 66 × 3 = 198, 47 × 6 = 282.","곱이 가장 큰 것은 46 × 7 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"46 × 8","correct":true},{"t":"38 × 5","mis":"M3-1-u4-X11"},{"t":"66 × 4","mis":"M3-1-u4-X15"},{"t":"48 × 3","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","46 × 8 = 368, 38 × 5 = 190, 66 × 4 = 264, 48 × 3 = 144.","곱이 가장 큰 것은 46 × 8 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#1','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',1,'sa','auto','열쇠고리를 만들어요. 별 모양 한 개에 비즈가 15개씩 들어가요. 별 모양 4개에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u4-C8","difficulty":1,"kind":"sa","stem":"열쇠고리를 만들어요. 별 모양 한 개에 비즈가 15개씩 들어가요. 별 모양 4개에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["60"],"explanation":["같은 모양이 4개 반복돼요 — 곱셈으로 한 번에 구해요.","한 개의 비즈 15개 × 4개 = 15 × 4.","15 × 4 = 60 — 비즈 60개가 필요해요."],"variant_rule":{"alt":[{"stem":"열쇠고리를 만들어요. 하트 한 개에 비즈가 48개씩 들어가요. 하트 2개에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["96"],"explanation":["같은 모양이 2개 반복돼요 — 곱셈으로 한 번에 구해요.","한 개의 비즈 48개 × 2개 = 48 × 2.","48 × 2 = 96 — 비즈 96개가 필요해요."],"asset":null},{"stem":"열쇠고리를 만들어요. 바람개비 날개 한 장에 비즈가 24개씩 들어가요. 바람개비 날개 4장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["96"],"explanation":["같은 모양이 4장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 24개 × 4장 = 24 × 4.","24 × 4 = 96 — 비즈 96개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#2','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',1,'mc','auto','꽃잎 한 장에 비즈가 18개씩 들어가요. 꽃잎 5장에 들어가는 비즈 수를 구하는 식은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":2,"concept":"M3-1-u4-C8","difficulty":1,"kind":"mc","stem":"꽃잎 한 장에 비즈가 18개씩 들어가요. 꽃잎 5장에 들어가는 비즈 수를 구하는 식은 어느 것인가요?","options":[{"t":"18 × 5","correct":true},{"t":"18 + 5","mis":"M3-1-u4-X01"},{"t":"5 × 5","mis":"M3-1-u4-X13"},{"t":"18 × 18","mis":"M3-1-u4-X13"}],"explanation":["한 묶음(한 장)은 18개, 묶음 수는 5이에요.","한 묶음 수 × 묶음 수예요.","18 × 5 = 90이에요."],"variant_rule":{"alt":[{"stem":"나비 날개 한 장에 비즈가 27개씩 들어가요. 나비 날개 2장에 들어가는 비즈 수를 구하는 식은 어느 것인가요?","options":[{"t":"27 × 2","correct":true},{"t":"27 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"27 × 27","mis":"M3-1-u4-X13"}],"explanation":["한 묶음(한 장)은 27개, 묶음 수는 2이에요.","한 묶음 수 × 묶음 수예요.","27 × 2 = 54예요."],"asset":null},{"stem":"네잎클로버 잎 한 장에 비즈가 48개씩 들어가요. 네잎클로버 잎 2장에 들어가는 비즈 수를 구하는 식은 어느 것인가요?","options":[{"t":"48 × 2","correct":true},{"t":"48 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"48 × 48","mis":"M3-1-u4-X13"}],"explanation":["한 묶음(한 장)은 48개, 묶음 수는 2이에요.","한 묶음 수 × 묶음 수예요.","48 × 2 = 96이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#3','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',1,'mc','auto','열쇠고리를 만들어요. 바람개비 날개 한 장에 비즈가 31개씩 들어가요. 바람개비 날개 5장에는 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":3,"concept":"M3-1-u4-C8","difficulty":1,"kind":"mc","stem":"열쇠고리를 만들어요. 바람개비 날개 한 장에 비즈가 31개씩 들어가요. 바람개비 날개 5장에는 비즈가 모두 몇 개 필요한가요?","options":[{"t":"155개","correct":true},{"t":"36개","mis":"M3-1-u4-X01"},{"t":"55개","mis":"M3-1-u4-X07"},{"t":"150개","mis":"M3-1-u4-X06"}],"explanation":["같은 모양이 5장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 31개 × 5장 = 31 × 5.","31 × 5 = 155 — 비즈 155개가 필요해요."],"variant_rule":{"alt":[{"stem":"열쇠고리를 만들어요. 꽃잎 한 장에 비즈가 72개씩 들어가요. 꽃잎 4장에는 비즈가 모두 몇 개 필요한가요?","options":[{"t":"288개","correct":true},{"t":"76개","mis":"M3-1-u4-X01"},{"t":"88개","mis":"M3-1-u4-X07"},{"t":"280개","mis":"M3-1-u4-X06"}],"explanation":["같은 모양이 4장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 72개 × 4장 = 72 × 4.","72 × 4 = 288 — 비즈 288개가 필요해요."],"asset":null},{"stem":"열쇠고리를 만들어요. 나비 날개 한 장에 비즈가 81개씩 들어가요. 나비 날개 6장에는 비즈가 모두 몇 개 필요한가요?","options":[{"t":"486개","correct":true},{"t":"87개","mis":"M3-1-u4-X01"},{"t":"86개","mis":"M3-1-u4-X07"},{"t":"480개","mis":"M3-1-u4-X06"}],"explanation":["같은 모양이 6장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 81개 × 6장 = 81 × 6.","81 × 6 = 486 — 비즈 486개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#4','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',1,'ox','auto','비즈 45개짜리 나비 날개를 4장 만들 때 일일이 세는 것보다 45 × 4로 구하는 것이 빠르고 정확해요.',ARRAY['M3-1-u4-X01']::text[],true,'{"seq":4,"concept":"M3-1-u4-C8","difficulty":1,"kind":"ox","stem":"비즈 45개짜리 나비 날개를 4장 만들 때 일일이 세는 것보다 45 × 4로 구하는 것이 빠르고 정확해요.","answer":"O","reason_options":[{"t":"같은 모양이 반복되면 곱셈으로 한 번에 구할 수 있어서","correct":true},{"t":"하나씩 세는 것이 언제나 더 정확해서","mis":"M3-1-u4-X01"}],"mis":"M3-1-u4-X01","explanation":["같은 모양 4장 — 한 묶음 45개.","45 × 4 = 180 — 한 번에 구해요.","일일이 세면 오래 걸리고 빠뜨리기 쉬워요."],"variant_rule":{"alt":[{"stem":"비즈 74개짜리 네잎클로버 잎을 3장 만들 때 일일이 세는 것보다 74 × 3으로 구하는 것이 빠르고 정확해요.","answer":"O","reason_options":[{"t":"같은 모양이 반복되면 곱셈으로 한 번에 구할 수 있어서","correct":true},{"t":"하나씩 세는 것이 언제나 더 정확해서","mis":"M3-1-u4-X01"}],"explanation":["같은 모양 3장 — 한 묶음 74개.","74 × 3 = 222 — 한 번에 구해요.","일일이 세면 오래 걸리고 빠뜨리기 쉬워요."],"asset":null},{"stem":"비즈 17개짜리 별 모양을 8개 만들 때 일일이 세는 것보다 17 × 8로 구하는 것이 빠르고 정확해요.","answer":"O","reason_options":[{"t":"같은 모양이 반복되면 곱셈으로 한 번에 구할 수 있어서","correct":true},{"t":"하나씩 세는 것이 언제나 더 정확해서","mis":"M3-1-u4-X01"}],"explanation":["같은 모양 8개 — 한 묶음 17개.","17 × 8 = 136 — 한 번에 구해요.","일일이 세면 오래 걸리고 빠뜨리기 쉬워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#5','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',2,'sa','auto','열쇠고리를 만들어요. 나비 날개 한 장에 비즈가 12개씩 들어가요. 나비 날개 2장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u4-C8","difficulty":2,"kind":"sa","stem":"열쇠고리를 만들어요. 나비 날개 한 장에 비즈가 12개씩 들어가요. 나비 날개 2장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["24"],"explanation":["같은 모양이 2장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 12개 × 2장 = 12 × 2.","12 × 2 = 24 — 비즈 24개가 필요해요."],"variant_rule":{"alt":[{"stem":"열쇠고리를 만들어요. 네잎클로버 잎 한 장에 비즈가 13개씩 들어가요. 네잎클로버 잎 3장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["39"],"explanation":["같은 모양이 3장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 13개 × 3장 = 13 × 3.","13 × 3 = 39 — 비즈 39개가 필요해요."],"asset":null},{"stem":"열쇠고리를 만들어요. 별 모양 한 개에 비즈가 21개씩 들어가요. 별 모양 4개에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["84"],"explanation":["같은 모양이 4개 반복돼요 — 곱셈으로 한 번에 구해요.","한 개의 비즈 21개 × 4개 = 21 × 4.","21 × 4 = 84 — 비즈 84개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#6','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',2,'sa','auto','꽃잎 한 장의 비즈를 두 부분으로 나누어 세었더니 7개씩 5줄과 5개씩 2줄이었어요. 꽃잎 한 장의 비즈는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u4-C8","difficulty":2,"kind":"sa","stem":"꽃잎 한 장의 비즈를 두 부분으로 나누어 세었더니 7개씩 5줄과 5개씩 2줄이었어요. 꽃잎 한 장의 비즈는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["첫 부분: 7 × 5 = 35예요.","둘째 부분: 5 × 2 = 10이에요.","나누어 센 것을 모두 더해요 — 35 + 10 = 45개."],"asset":{"type":"expr_grid","rows":[["7 × 5","=","35"],["5 × 2","=","10"],["한 장","=",null]]},"variant_rule":{"alt":[{"stem":"꽃잎 한 장의 비즈를 두 부분으로 나누어 세었더니 6개씩 4줄과 4개씩 3줄이었어요. 꽃잎 한 장의 비즈는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["첫 부분: 6 × 4 = 24예요.","둘째 부분: 4 × 3 = 12예요.","나누어 센 것을 모두 더해요 — 24 + 12 = 36개."],"asset":{"type":"expr_grid","rows":[["6 × 4","=","24"],["4 × 3","=","12"],["한 장","=",null]]}},{"stem":"꽃잎 한 장의 비즈를 두 부분으로 나누어 세었더니 8개씩 3줄과 6개씩 2줄이었어요. 꽃잎 한 장의 비즈는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["첫 부분: 8 × 3 = 24예요.","둘째 부분: 6 × 2 = 12예요.","나누어 센 것을 모두 더해요 — 24 + 12 = 36개."],"asset":{"type":"expr_grid","rows":[["8 × 3","=","24"],["6 × 2","=","12"],["한 장","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#7','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',2,'mc','auto','열쇠고리를 만들어요. 네잎클로버 잎 한 장에 비즈가 45개씩 들어가요. 네잎클로버 잎 4장에는 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X08','M3-1-u4-X07']::text[],true,'{"seq":7,"concept":"M3-1-u4-C8","difficulty":2,"kind":"mc","stem":"열쇠고리를 만들어요. 네잎클로버 잎 한 장에 비즈가 45개씩 들어가요. 네잎클로버 잎 4장에는 비즈가 모두 몇 개 필요한가요?","options":[{"t":"180개","correct":true},{"t":"49개","mis":"M3-1-u4-X01"},{"t":"160개","mis":"M3-1-u4-X08"},{"t":"80개","mis":"M3-1-u4-X07"}],"explanation":["같은 모양이 4장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 45개 × 4장 = 45 × 4.","45 × 4 = 180 — 비즈 180개가 필요해요."],"variant_rule":{"alt":[{"stem":"열쇠고리를 만들어요. 별 모양 한 개에 비즈가 58개씩 들어가요. 별 모양 5개에는 비즈가 모두 몇 개 필요한가요?","options":[{"t":"290개","correct":true},{"t":"63개","mis":"M3-1-u4-X01"},{"t":"250개","mis":"M3-1-u4-X08"},{"t":"90개","mis":"M3-1-u4-X07"}],"explanation":["같은 모양이 5개 반복돼요 — 곱셈으로 한 번에 구해요.","한 개의 비즈 58개 × 5개 = 58 × 5.","58 × 5 = 290 — 비즈 290개가 필요해요."],"asset":null},{"stem":"열쇠고리를 만들어요. 하트 한 개에 비즈가 17개씩 들어가요. 하트 9개에는 비즈가 모두 몇 개 필요한가요?","options":[{"t":"153개","correct":true},{"t":"26개","mis":"M3-1-u4-X01"},{"t":"93개","mis":"M3-1-u4-X08"},{"t":"53개","mis":"M3-1-u4-X07"}],"explanation":["같은 모양이 9개 반복돼요 — 곱셈으로 한 번에 구해요.","한 개의 비즈 17개 × 9개 = 17 × 9.","17 × 9 = 153 — 비즈 153개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#8','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',2,'mc','auto','바람개비 한 개에 날개 비즈 36개와 손잡이 비즈 15개가 들어가요. 바람개비 7개의 날개 비즈는 모두 몇 개인가요?',ARRAY['M3-1-u4-X14','M3-1-u4-X15','M3-1-u4-X01']::text[],true,'{"seq":8,"concept":"M3-1-u4-C8","difficulty":2,"kind":"mc","stem":"바람개비 한 개에 날개 비즈 36개와 손잡이 비즈 15개가 들어가요. 바람개비 7개의 날개 비즈는 모두 몇 개인가요?","options":[{"t":"252개","correct":true},{"t":"357개","mis":"M3-1-u4-X14"},{"t":"105개","mis":"M3-1-u4-X15"},{"t":"43개","mis":"M3-1-u4-X01"}],"explanation":["묻는 것은 날개 비즈만이에요.","날개 비즈 36개 × 바람개비 7개.","36 × 7 = 252개 — 손잡이 비즈는 더하지 않아요."],"variant_rule":{"alt":[{"stem":"바람개비 한 개에 날개 비즈 63개와 손잡이 비즈 16개가 들어가요. 바람개비 6개의 날개 비즈는 모두 몇 개인가요?","options":[{"t":"378개","correct":true},{"t":"474개","mis":"M3-1-u4-X14"},{"t":"96개","mis":"M3-1-u4-X15"},{"t":"69개","mis":"M3-1-u4-X01"}],"explanation":["묻는 것은 날개 비즈만이에요.","날개 비즈 63개 × 바람개비 6개.","63 × 6 = 378개 — 손잡이 비즈는 더하지 않아요."],"asset":null},{"stem":"바람개비 한 개에 날개 비즈 76개와 손잡이 비즈 12개가 들어가요. 바람개비 6개의 날개 비즈는 모두 몇 개인가요?","options":[{"t":"456개","correct":true},{"t":"528개","mis":"M3-1-u4-X14"},{"t":"72개","mis":"M3-1-u4-X15"},{"t":"82개","mis":"M3-1-u4-X01"}],"explanation":["묻는 것은 날개 비즈만이에요.","날개 비즈 76개 × 바람개비 6개.","76 × 6 = 456개 — 손잡이 비즈는 더하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#9','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',2,'mc','auto','생수가 한 묶음에 24병씩 3묶음 있어요. 생수는 모두 몇 병인지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":9,"concept":"M3-1-u4-C8","difficulty":2,"kind":"mc","stem":"생수가 한 묶음에 24병씩 3묶음 있어요. 생수는 모두 몇 병인지 구하는 식은 어느 것인가요?","options":[{"t":"24 × 3","correct":true},{"t":"24 + 3","mis":"M3-1-u4-X01"},{"t":"3 × 3","mis":"M3-1-u4-X13"},{"t":"24 × 24","mis":"M3-1-u4-X13"}],"explanation":["24병씩 3번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 24 × 3."],"variant_rule":{"alt":[{"stem":"걷기 운동을 하루에 24분씩 4일 동안 했어요. 모두 몇 분 걸었는지 구하는 식은 어느 것인가요?","options":[{"t":"24 × 4","correct":true},{"t":"24 + 4","mis":"M3-1-u4-X01"},{"t":"4 × 4","mis":"M3-1-u4-X13"},{"t":"24 × 24","mis":"M3-1-u4-X13"}],"explanation":["24분씩 4번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 24 × 4."],"asset":null},{"stem":"계단 오르기를 하루에 13칸씩 5일 동안 했어요. 모두 몇 칸 올랐는지 구하는 식은 어느 것인가요?","options":[{"t":"13 × 5","correct":true},{"t":"13 + 5","mis":"M3-1-u4-X01"},{"t":"5 × 5","mis":"M3-1-u4-X13"},{"t":"13 × 13","mis":"M3-1-u4-X13"}],"explanation":["13칸씩 5번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 13 × 5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_basic#10','math',3,1,'u4','L07','g3_1_math_u4_L07_basic','lesson_basic','M3-1-u4-C8',3,'mc','auto','나비 날개 한 장의 비즈는 7개씩 5줄과 5개씩 2줄이에요. 날개 4장을 만들려면 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X14','M3-1-u4-X01']::text[],true,'{"seq":10,"concept":"M3-1-u4-C8","difficulty":3,"kind":"mc","stem":"나비 날개 한 장의 비즈는 7개씩 5줄과 5개씩 2줄이에요. 날개 4장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"180개","correct":true},{"t":"140개","mis":"M3-1-u4-X14"},{"t":"40개","mis":"M3-1-u4-X14"},{"t":"49개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 7 × 5 + 5 × 2 = 35 + 10 = 45개.","날개 4장: 45 × 4.","45 × 4 = 180 — 비즈 180개가 필요해요."],"variant_rule":{"alt":[{"stem":"나비 날개 한 장의 비즈는 6개씩 4줄과 4개씩 3줄이에요. 날개 3장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"108개","correct":true},{"t":"72개","mis":"M3-1-u4-X14"},{"t":"36개","mis":"M3-1-u4-X14"},{"t":"39개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 6 × 4 + 4 × 3 = 24 + 12 = 36개.","날개 3장: 36 × 3.","36 × 3 = 108 — 비즈 108개가 필요해요."],"asset":null},{"stem":"나비 날개 한 장의 비즈는 8개씩 3줄과 6개씩 2줄이에요. 날개 5장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"180개","correct":true},{"t":"120개","mis":"M3-1-u4-X14"},{"t":"60개","mis":"M3-1-u4-X14"},{"t":"41개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 8 × 3 + 6 × 2 = 24 + 12 = 36개.","날개 5장: 36 × 5.","36 × 5 = 180 — 비즈 180개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#1','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',2,'mc','auto','바람개비 한 개에 날개 비즈 25개와 손잡이 비즈 16개가 들어가요. 바람개비 7개의 날개 비즈는 모두 몇 개인가요?',ARRAY['M3-1-u4-X14','M3-1-u4-X15','M3-1-u4-X01']::text[],true,'{"seq":1,"concept":"M3-1-u4-C8","difficulty":2,"kind":"mc","stem":"바람개비 한 개에 날개 비즈 25개와 손잡이 비즈 16개가 들어가요. 바람개비 7개의 날개 비즈는 모두 몇 개인가요?","options":[{"t":"175개","correct":true},{"t":"287개","mis":"M3-1-u4-X14"},{"t":"112개","mis":"M3-1-u4-X15"},{"t":"32개","mis":"M3-1-u4-X01"}],"explanation":["묻는 것은 날개 비즈만이에요.","날개 비즈 25개 × 바람개비 7개.","25 × 7 = 175개 — 손잡이 비즈는 더하지 않아요."],"variant_rule":{"alt":[{"stem":"바람개비 한 개에 날개 비즈 99개와 손잡이 비즈 12개가 들어가요. 바람개비 8개의 날개 비즈는 모두 몇 개인가요?","options":[{"t":"792개","correct":true},{"t":"888개","mis":"M3-1-u4-X14"},{"t":"96개","mis":"M3-1-u4-X15"},{"t":"107개","mis":"M3-1-u4-X01"}],"explanation":["묻는 것은 날개 비즈만이에요.","날개 비즈 99개 × 바람개비 8개.","99 × 8 = 792개 — 손잡이 비즈는 더하지 않아요."],"asset":null},{"stem":"바람개비 한 개에 날개 비즈 79개와 손잡이 비즈 13개가 들어가요. 바람개비 5개의 날개 비즈는 모두 몇 개인가요?","options":[{"t":"395개","correct":true},{"t":"460개","mis":"M3-1-u4-X14"},{"t":"65개","mis":"M3-1-u4-X15"},{"t":"84개","mis":"M3-1-u4-X01"}],"explanation":["묻는 것은 날개 비즈만이에요.","날개 비즈 79개 × 바람개비 5개.","79 × 5 = 395개 — 손잡이 비즈는 더하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#2','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',2,'sa','auto','꽃잎 한 장의 비즈를 두 부분으로 나누어 세었더니 5개씩 6줄과 4개씩 3줄이었어요. 꽃잎 한 장의 비즈는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u4-C8","difficulty":2,"kind":"sa","stem":"꽃잎 한 장의 비즈를 두 부분으로 나누어 세었더니 5개씩 6줄과 4개씩 3줄이었어요. 꽃잎 한 장의 비즈는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["첫 부분: 5 × 6 = 30이에요.","둘째 부분: 4 × 3 = 12예요.","나누어 센 것을 모두 더해요 — 30 + 12 = 42개."],"asset":{"type":"expr_grid","rows":[["5 × 6","=","30"],["4 × 3","=","12"],["한 장","=",null]]},"variant_rule":{"alt":[{"stem":"꽃잎 한 장의 비즈를 두 부분으로 나누어 세었더니 7개씩 4줄과 9개씩 2줄이었어요. 꽃잎 한 장의 비즈는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["첫 부분: 7 × 4 = 28이에요.","둘째 부분: 9 × 2 = 18이에요.","나누어 센 것을 모두 더해요 — 28 + 18 = 46개."],"asset":{"type":"expr_grid","rows":[["7 × 4","=","28"],["9 × 2","=","18"],["한 장","=",null]]}},{"stem":"꽃잎 한 장의 비즈를 두 부분으로 나누어 세었더니 6개씩 5줄과 3개씩 4줄이었어요. 꽃잎 한 장의 비즈는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["첫 부분: 6 × 5 = 30이에요.","둘째 부분: 3 × 4 = 12예요.","나누어 센 것을 모두 더해요 — 30 + 12 = 42개."],"asset":{"type":"expr_grid","rows":[["6 × 5","=","30"],["3 × 4","=","12"],["한 장","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#3','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',3,'mc','auto','열쇠고리를 만들어요. 나비 날개 한 장에 비즈가 68개씩 들어가요. 나비 날개 4장에는 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X08','M3-1-u4-X09']::text[],true,'{"seq":3,"concept":"M3-1-u4-C8","difficulty":3,"kind":"mc","stem":"열쇠고리를 만들어요. 나비 날개 한 장에 비즈가 68개씩 들어가요. 나비 날개 4장에는 비즈가 모두 몇 개 필요한가요?","options":[{"t":"272개","correct":true},{"t":"72개","mis":"M3-1-u4-X01"},{"t":"242개","mis":"M3-1-u4-X08"},{"t":"362개","mis":"M3-1-u4-X09"}],"explanation":["같은 모양이 4장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 68개 × 4장 = 68 × 4.","68 × 4 = 272 — 비즈 272개가 필요해요."],"variant_rule":{"alt":[{"stem":"열쇠고리를 만들어요. 네잎클로버 잎 한 장에 비즈가 72개씩 들어가요. 네잎클로버 잎 5장에는 비즈가 모두 몇 개 필요한가요?","options":[{"t":"360개","correct":true},{"t":"77개","mis":"M3-1-u4-X01"},{"t":"350개","mis":"M3-1-u4-X08"},{"t":"60개","mis":"M3-1-u4-X07"}],"explanation":["같은 모양이 5장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 72개 × 5장 = 72 × 5.","72 × 5 = 360 — 비즈 360개가 필요해요."],"asset":null},{"stem":"열쇠고리를 만들어요. 별 모양 한 개에 비즈가 89개씩 들어가요. 별 모양 2개에는 비즈가 모두 몇 개 필요한가요?","options":[{"t":"178개","correct":true},{"t":"91개","mis":"M3-1-u4-X01"},{"t":"168개","mis":"M3-1-u4-X08"},{"t":"78개","mis":"M3-1-u4-X07"}],"explanation":["같은 모양이 2개 반복돼요 — 곱셈으로 한 번에 구해요.","한 개의 비즈 89개 × 2개 = 89 × 2.","89 × 2 = 178 — 비즈 178개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#4','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',3,'mc','auto','나비 날개 한 장의 비즈는 5개씩 6줄과 4개씩 3줄이에요. 날개 6장을 만들려면 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X14','M3-1-u4-X01']::text[],true,'{"seq":4,"concept":"M3-1-u4-C8","difficulty":3,"kind":"mc","stem":"나비 날개 한 장의 비즈는 5개씩 6줄과 4개씩 3줄이에요. 날개 6장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"252개","correct":true},{"t":"180개","mis":"M3-1-u4-X14"},{"t":"72개","mis":"M3-1-u4-X14"},{"t":"48개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 5 × 6 + 4 × 3 = 30 + 12 = 42개.","날개 6장: 42 × 6.","42 × 6 = 252 — 비즈 252개가 필요해요."],"variant_rule":{"alt":[{"stem":"나비 날개 한 장의 비즈는 7개씩 4줄과 9개씩 2줄이에요. 날개 4장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"184개","correct":true},{"t":"112개","mis":"M3-1-u4-X14"},{"t":"72개","mis":"M3-1-u4-X14"},{"t":"50개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 7 × 4 + 9 × 2 = 28 + 18 = 46개.","날개 4장: 46 × 4.","46 × 4 = 184 — 비즈 184개가 필요해요."],"asset":null},{"stem":"나비 날개 한 장의 비즈는 6개씩 5줄과 3개씩 4줄이에요. 날개 7장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"294개","correct":true},{"t":"210개","mis":"M3-1-u4-X14"},{"t":"84개","mis":"M3-1-u4-X14"},{"t":"49개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 6 × 5 + 3 × 4 = 30 + 12 = 42개.","날개 7장: 42 × 7.","42 × 7 = 294 — 비즈 294개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#5','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',3,'mc','auto','줄넘기를 한 번에 74회씩 8번 했어요. 모두 몇 회 했나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X08','M3-1-u4-X07']::text[],true,'{"seq":5,"concept":"M3-1-u4-C8","difficulty":3,"kind":"mc","stem":"줄넘기를 한 번에 74회씩 8번 했어요. 모두 몇 회 했나요?","options":[{"t":"592회","correct":true},{"t":"82회","mis":"M3-1-u4-X01"},{"t":"562회","mis":"M3-1-u4-X08"},{"t":"92회","mis":"M3-1-u4-X07"}],"explanation":["74회씩 8번(묶음) — 곱셈식 74 × 8로 세워요.","일의 자리 32 → 3 올림, 십의 자리 7 × 8 + 3 = 59 — 백의 자리까지 올림해요.","74 × 8 = 592 — 모두 592회예요."],"variant_rule":{"alt":[{"stem":"체조를 하루에 58분씩 4일 동안 했어요. 모두 몇 분 했나요?","options":[{"t":"232분","correct":true},{"t":"62분","mis":"M3-1-u4-X01"},{"t":"202분","mis":"M3-1-u4-X08"},{"t":"32분","mis":"M3-1-u4-X07"}],"explanation":["58분씩 4번(묶음) — 곱셈식 58 × 4로 세워요.","일의 자리 32 → 3 올림, 십의 자리 5 × 4 + 3 = 23 — 백의 자리까지 올림해요.","58 × 4 = 232 — 모두 232분이에요."],"asset":null},{"stem":"생수가 한 묶음에 57병씩 7묶음 있어요. 생수는 모두 몇 병인가요?","options":[{"t":"399병","correct":true},{"t":"64병","mis":"M3-1-u4-X01"},{"t":"359병","mis":"M3-1-u4-X08"},{"t":"99병","mis":"M3-1-u4-X07"}],"explanation":["57병씩 7번(묶음) — 곱셈식 57 × 7로 세워요.","일의 자리 49 → 4 올림, 십의 자리 5 × 7 + 4 = 39 — 백의 자리까지 올림해요.","57 × 7 = 399 — 모두 399병이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#6','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 45 × 4 ○ 16 × 9',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":6,"concept":"M3-1-u4-C8","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 45 × 4 ○ 16 × 9","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["45 × 4 = 180이에요.","16 × 9 = 144예요.","180 > 144 — 알맞은 것은 >예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 83 × 9 ○ 93 × 8","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["83 × 9 = 747이에요.","93 × 8 = 744예요.","747 > 744 — 알맞은 것은 >예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 89 × 4 ○ 63 × 6","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u4-X11"},{"t":"=","mis":"M3-1-u4-X11"},{"t":"알 수 없다","mis":"M3-1-u4-X15"}],"explanation":["89 × 4 = 356이에요.","63 × 6 = 378이에요.","356 < 378 — 알맞은 것은 <예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#7','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',3,'sa','auto','하랑은 줄넘기를 한 번에 27회씩 3번, 태오는 한 번에 35회씩 2번 했어요. 두 사람이 넘은 횟수의 차는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u4-C8","difficulty":3,"kind":"sa","stem":"하랑은 줄넘기를 한 번에 27회씩 3번, 태오는 한 번에 35회씩 2번 했어요. 두 사람이 넘은 횟수의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["하랑: 27 × 3 = 81회.","태오: 35 × 2 = 70회.","81 − 70 = 11 — 하랑이 11회 더 했어요."],"variant_rule":{"alt":[{"stem":"도윤은 줄넘기를 한 번에 18회씩 5번, 서윤은 한 번에 23회씩 3번 했어요. 두 사람이 넘은 횟수의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["도윤: 18 × 5 = 90회.","서윤: 23 × 3 = 69회.","90 − 69 = 21 — 도윤이 21회 더 했어요."],"asset":null},{"stem":"시우는 줄넘기를 한 번에 32회씩 3번, 도윤은 한 번에 19회씩 4번 했어요. 두 사람이 넘은 횟수의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["시우: 32 × 3 = 96회.","도윤: 19 × 4 = 76회.","96 − 76 = 20 — 시우가 20회 더 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#8','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',4,'essay','teacher','네잎클로버 열쇠고리의 잎 한 장은 비즈가 7개씩 5줄과 5개씩 2줄이에요. 잎 4장에 필요한 비즈 수를 구하는 방법을 두 단계로 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u4-C8","difficulty":4,"kind":"essay","stem":"네잎클로버 열쇠고리의 잎 한 장은 비즈가 7개씩 5줄과 5개씩 2줄이에요. 잎 4장에 필요한 비즈 수를 구하는 방법을 두 단계로 써 보세요.","answer_guide":{"answer":"예: ① 잎 한 장 — 7 × 5 = 35, 5 × 2 = 10, 더하면 45개이다. ② 잎 4장 — 45 × 4 = 180이므로 비즈 180개가 필요하다(40 × 4 = 160, 5 × 4 = 20).","scoring_points":["잎 한 장을 나누어 세어 45개를 구했는가","45 × 4로 식을 세웠는가","180개를 구했는가"]},"explanation":["잎 한 장: 35 + 10 = 45개.","잎 4장: 45 × 4.","45 × 4 = 180개."],"asset":{"type":"expr_grid","rows":[["7 × 5","=","35"],["5 × 2","=","10"],["한 장","=","45"],["45 × 4","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#9','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',4,'essay','teacher','비즈 한 봉지에 24개씩 들어 있어요. 「24 × 6」에 알맞은 열쇠고리 만들기 이야기를 하나 만들고, 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u4-C8","difficulty":4,"kind":"essay","stem":"비즈 한 봉지에 24개씩 들어 있어요. 「24 × 6」에 알맞은 열쇠고리 만들기 이야기를 하나 만들고, 답을 구해 보세요.","answer_guide":{"answer":"예: 「별 모양 열쇠고리 하나에 비즈가 24개 들어가요. 6개를 만들려면 비즈가 모두 몇 개 필요할까요?」 — 24 × 6 = 144(20 × 6 = 120, 4 × 6 = 24), 비즈 144개가 필요하다.","scoring_points":["24개씩 6번(묶음)인 이야기를 만들었는가","24 × 6 = 144를 구했는가","답의 뜻(필요한 비즈 수)을 썼는가"]},"explanation":["24개씩 6묶음 이야기를 만들어요.","20 × 6 = 120, 4 × 6 = 24.","24 × 6 = 144."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_L07_challenge#10','math',3,1,'u4','L07','g3_1_math_u4_L07_challenge','lesson_challenge','M3-1-u4-C8',4,'mc','auto','나비 날개 한 장의 비즈는 6개씩 7줄과 8개씩 2줄이에요. 날개 6장을 만들려면 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X14','M3-1-u4-X01']::text[],true,'{"seq":10,"concept":"M3-1-u4-C8","difficulty":4,"kind":"mc","stem":"나비 날개 한 장의 비즈는 6개씩 7줄과 8개씩 2줄이에요. 날개 6장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"348개","correct":true},{"t":"252개","mis":"M3-1-u4-X14"},{"t":"96개","mis":"M3-1-u4-X14"},{"t":"64개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 6 × 7 + 8 × 2 = 42 + 16 = 58개.","날개 6장: 58 × 6.","58 × 6 = 348 — 비즈 348개가 필요해요."],"variant_rule":{"alt":[{"stem":"나비 날개 한 장의 비즈는 9개씩 5줄과 7개씩 3줄이에요. 날개 4장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"264개","correct":true},{"t":"180개","mis":"M3-1-u4-X14"},{"t":"84개","mis":"M3-1-u4-X14"},{"t":"70개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 9 × 5 + 7 × 3 = 45 + 21 = 66개.","날개 4장: 66 × 4.","66 × 4 = 264 — 비즈 264개가 필요해요."],"asset":null},{"stem":"나비 날개 한 장의 비즈는 8개씩 6줄과 7개씩 2줄이에요. 날개 5장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"310개","correct":true},{"t":"240개","mis":"M3-1-u4-X14"},{"t":"70개","mis":"M3-1-u4-X14"},{"t":"67개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 8 × 6 + 7 × 2 = 48 + 14 = 62개.","날개 5장: 62 × 5.","62 × 5 = 310 — 비즈 310개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#1','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C1',1,'mc','auto','14 + 14를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":1,"concept":"M3-1-u4-C1","difficulty":1,"kind":"mc","stem":"14 + 14를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"14 × 2","correct":true},{"t":"14 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"14 × 14","mis":"M3-1-u4-X13"}],"explanation":["같은 수 14를 2번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","14를 2번 → 14 × 2."],"variant_rule":{"alt":[{"stem":"11 + 11을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"11 × 2","correct":true},{"t":"11 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"11 × 11","mis":"M3-1-u4-X13"}],"explanation":["같은 수 11을 2번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","11을 2번 → 11 × 2."],"asset":null},{"stem":"41 + 41을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"41 × 2","correct":true},{"t":"41 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"41 × 41","mis":"M3-1-u4-X13"}],"explanation":["같은 수 41을 2번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","41을 2번 → 41 × 2."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#2','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C2',1,'mc','auto','2 × 3 = 6이에요. 그러면 20 × 3은 얼마인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X03','M3-1-u4-X11']::text[],true,'{"seq":2,"concept":"M3-1-u4-C2","difficulty":1,"kind":"mc","stem":"2 × 3 = 6이에요. 그러면 20 × 3은 얼마인가요?","options":[{"t":"60","correct":true},{"t":"6","mis":"M3-1-u4-X02"},{"t":"600","mis":"M3-1-u4-X03"},{"t":"70","mis":"M3-1-u4-X11"}],"explanation":["20은 2의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","6의 10배 — 20 × 3 = 60이에요."],"variant_rule":{"alt":[{"stem":"2 × 4 = 8이에요. 그러면 20 × 4는 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8","mis":"M3-1-u4-X02"},{"t":"800","mis":"M3-1-u4-X03"},{"t":"90","mis":"M3-1-u4-X11"}],"explanation":["20은 2의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","8의 10배 — 20 × 4 = 80이에요."],"asset":null},{"stem":"2 × 2 = 4예요. 그러면 20 × 2는 얼마인가요?","options":[{"t":"40","correct":true},{"t":"4","mis":"M3-1-u4-X02"},{"t":"400","mis":"M3-1-u4-X03"},{"t":"50","mis":"M3-1-u4-X11"}],"explanation":["20은 2의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","4의 10배 — 20 × 2 = 40이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#3','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C2',1,'sa','auto','40 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C2","difficulty":1,"kind":"sa","stem":"40 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["4 × 2 = 8이에요.","40은 4의 10배라 곱도 10배예요.","40 × 2 = 80이에요."],"variant_rule":{"alt":[{"stem":"30 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["3 × 2 = 6이에요.","30은 3의 10배라 곱도 10배예요.","30 × 2 = 60이에요."],"asset":null},{"stem":"10 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["1 × 7 = 7이에요.","10은 1의 10배라 곱도 10배예요.","10 × 7 = 70이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#4','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C3',1,'sa','auto','13 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"13 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["13을 10과 3으로 나누어 곱해요: 10 × 2 = 20, 3 × 2 = 6.","일의 자리 3 × 2 = 6, 십의 자리 1 × 2 = 2(십)이에요.","20 + 6 = 26 — 26은 어림한 10 × 2 = 20과 가까워요."],"variant_rule":{"alt":[{"stem":"41 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["82"],"explanation":["41을 40과 1로 나누어 곱해요: 40 × 2 = 80, 1 × 2 = 2.","일의 자리 1 × 2 = 2, 십의 자리 4 × 2 = 8(십)이에요.","80 + 2 = 82 — 82는 어림한 40 × 2 = 80과 가까워요."],"asset":null},{"stem":"44 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["88"],"explanation":["44를 40과 4로 나누어 곱해요: 40 × 2 = 80, 4 × 2 = 8.","일의 자리 4 × 2 = 8, 십의 자리 4 × 2 = 8(십)이에요.","80 + 8 = 88 — 88은 어림한 40 × 2 = 80과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#5','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C3',1,'sa','auto','14 × 2를 10과 4로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"14 × 2를 10과 4로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["10 × 2 = 20.","□는 4 × 2 = 8이에요.","20 + 8 = 28 — 14 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["10 × 2","=","20"],["4 × 2","=",null],["20 + □","=","28"]]},"variant_rule":{"alt":[{"stem":"23 × 2를 20과 3으로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["20 × 2 = 40.","□는 3 × 2 = 6이에요.","40 + 6 = 46 — 23 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["20 × 2","=","40"],["3 × 2","=",null],["40 + □","=","46"]]}},{"stem":"32 × 3을 30과 2로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["30 × 3 = 90.","□는 2 × 3 = 6이에요.","90 + 6 = 96 — 32 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["30 × 3","=","90"],["2 × 3","=",null],["90 + □","=","96"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#6','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C4',1,'mc','auto','22 × 3을 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":6,"concept":"M3-1-u4-C4","difficulty":1,"kind":"mc","stem":"22 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 60","correct":true},{"t":"약 90","mis":"M3-1-u4-X12"},{"t":"약 20","mis":"M3-1-u4-X12"},{"t":"약 80","mis":"M3-1-u4-X11"}],"explanation":["22는 가까운 몇십 20으로 어림해요.","20 × 3 = 60이에요.","그래서 22 × 3은 약 60이에요 — 실제 곱 66과 가까워요."],"variant_rule":{"alt":[{"stem":"23 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 40","correct":true},{"t":"약 60","mis":"M3-1-u4-X12"},{"t":"약 20","mis":"M3-1-u4-X12"},{"t":"약 400","mis":"M3-1-u4-X03"}],"explanation":["23은 가까운 몇십 20으로 어림해요.","20 × 2 = 40이에요.","그래서 23 × 2는 약 40이에요 — 실제 곱 46과 가까워요."],"asset":null},{"stem":"21 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 40","correct":true},{"t":"약 60","mis":"M3-1-u4-X12"},{"t":"약 20","mis":"M3-1-u4-X12"},{"t":"약 400","mis":"M3-1-u4-X03"}],"explanation":["21은 가까운 몇십 20으로 어림해요.","20 × 2 = 40이에요.","그래서 21 × 2는 약 40이에요 — 실제 곱 42와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#7','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C5',1,'mc','auto','93 × 3은 얼마인가요?',ARRAY['M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":7,"concept":"M3-1-u4-C5","difficulty":1,"kind":"mc","stem":"93 × 3은 얼마인가요?","options":[{"t":"279","correct":true},{"t":"79","mis":"M3-1-u4-X07"},{"t":"270","mis":"M3-1-u4-X06"},{"t":"9","mis":"M3-1-u4-X06"}],"explanation":["93을 90과 3으로 나누어 곱해요: 90 × 3 = 270, 3 × 3 = 9.","십의 자리 곱 90 × 3 = 270 — 백의 자리로 올림해요.","270 + 9 = 279 — 279는 어림한 90 × 3 = 270과 가까워요."],"variant_rule":{"alt":[{"stem":"51 × 9는 얼마인가요?","options":[{"t":"459","correct":true},{"t":"59","mis":"M3-1-u4-X07"},{"t":"450","mis":"M3-1-u4-X06"},{"t":"9","mis":"M3-1-u4-X06"}],"explanation":["51을 50과 1로 나누어 곱해요: 50 × 9 = 450, 1 × 9 = 9.","십의 자리 곱 50 × 9 = 450 — 백의 자리로 올림해요.","450 + 9 = 459 — 459는 어림한 50 × 9 = 450과 가까워요."],"asset":null},{"stem":"21 × 8은 얼마인가요?","options":[{"t":"168","correct":true},{"t":"68","mis":"M3-1-u4-X07"},{"t":"160","mis":"M3-1-u4-X06"},{"t":"8","mis":"M3-1-u4-X06"}],"explanation":["21을 20과 1로 나누어 곱해요: 20 × 8 = 160, 1 × 8 = 8.","십의 자리 곱 20 × 8 = 160 — 백의 자리로 올림해요.","160 + 8 = 168 — 168은 어림한 20 × 8 = 160과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#8','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C6',1,'sa','auto','36 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u4-C6","difficulty":1,"kind":"sa","stem":"36 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["36을 30과 6으로 나누어 곱해요: 30 × 2 = 60, 6 × 2 = 12.","일의 자리 곱 6 × 2 = 12 — 1을 십의 자리로 올림해 더해요.","60 + 12 = 72 — 72는 어림한 40 × 2 = 80과 가까워요."],"variant_rule":{"alt":[{"stem":"13 × 6은 얼마인가요? 숫자로 쓰세요.","answer":["78"],"explanation":["13을 10과 3으로 나누어 곱해요: 10 × 6 = 60, 3 × 6 = 18.","일의 자리 곱 3 × 6 = 18 — 1을 십의 자리로 올림해 더해요.","60 + 18 = 78 — 78은 어림한 10 × 6 = 60과 가까워요."],"asset":null},{"stem":"14 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["14를 10과 4로 나누어 곱해요: 10 × 4 = 40, 4 × 4 = 16.","일의 자리 곱 4 × 4 = 16 — 1을 십의 자리로 올림해 더해요.","40 + 16 = 56 — 56은 어림한 10 × 4 = 40과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#9','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C1',2,'mc','auto','윗몸 일으키기를 하루에 98개씩 7일 동안 했어요. 모두 몇 개 했는지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":9,"concept":"M3-1-u4-C1","difficulty":2,"kind":"mc","stem":"윗몸 일으키기를 하루에 98개씩 7일 동안 했어요. 모두 몇 개 했는지 구하는 식은 어느 것인가요?","options":[{"t":"98 × 7","correct":true},{"t":"98 + 7","mis":"M3-1-u4-X01"},{"t":"7 × 7","mis":"M3-1-u4-X13"},{"t":"98 × 98","mis":"M3-1-u4-X13"}],"explanation":["98개씩 7번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 98 × 7."],"variant_rule":{"alt":[{"stem":"양치질을 한 달에 86번씩 7달 동안 빠짐없이 했어요. 모두 몇 번 했는지 구하는 식은 어느 것인가요?","options":[{"t":"86 × 7","correct":true},{"t":"86 + 7","mis":"M3-1-u4-X01"},{"t":"7 × 7","mis":"M3-1-u4-X13"},{"t":"86 × 86","mis":"M3-1-u4-X13"}],"explanation":["86번씩 7번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 86 × 7."],"asset":null},{"stem":"생수가 한 묶음에 29병씩 4묶음 있어요. 생수는 모두 몇 병인지 구하는 식은 어느 것인가요?","options":[{"t":"29 × 4","correct":true},{"t":"29 + 4","mis":"M3-1-u4-X01"},{"t":"4 × 4","mis":"M3-1-u4-X13"},{"t":"29 × 29","mis":"M3-1-u4-X13"}],"explanation":["29병씩 4번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 29 × 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#10','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C2',2,'ox','auto','40 × 6 = 24예요.',ARRAY['M3-1-u4-X02']::text[],true,'{"seq":10,"concept":"M3-1-u4-C2","difficulty":2,"kind":"ox","stem":"40 × 6 = 24예요.","answer":"X","reason_options":[{"t":"40 × 6은 4 × 6의 10배라서","correct":true},{"t":"4 × 6 = 24니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"mis":"M3-1-u4-X02","explanation":["4 × 6 = 24예요.","40은 4의 10배라 곱도 10배 — 240이에요.","0을 빠뜨리면 십 모형 24개를 낱개 24개로 센 셈이에요."],"variant_rule":{"alt":[{"stem":"90 × 9 = 81이에요.","answer":"X","reason_options":[{"t":"90 × 9는 9 × 9의 10배라서","correct":true},{"t":"9 × 9 = 81이니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["9 × 9 = 81이에요.","90은 9의 10배라 곱도 10배 — 810이에요.","0을 빠뜨리면 십 모형 81개를 낱개 81개로 센 셈이에요."],"asset":null},{"stem":"60 × 7 = 42예요.","answer":"X","reason_options":[{"t":"60 × 7은 6 × 7의 10배라서","correct":true},{"t":"6 × 7 = 42니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["6 × 7 = 42예요.","60은 6의 10배라 곱도 10배 — 420이에요.","0을 빠뜨리면 십 모형 42개를 낱개 42개로 센 셈이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#11','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C3',2,'sa','auto','23 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-1-u4-C3","difficulty":2,"kind":"sa","stem":"23 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 2 × 2 = 4 → 4를 써요.","23 × 2 = 46 — 십의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["","","2","3"],["×","","","2"],["","",null,"6"]]},"variant_rule":{"alt":[{"stem":"24 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 4 × 2 = 8 → 8을 써요.","24 × 2 = 48 — 일의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["","","2","4"],["×","","","2"],["","","4",null]]}},{"stem":"33 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 3 × 2 = 6 → 6을 써요.","33 × 2 = 66 — 십의 자리 숫자는 6이에요."],"asset":{"type":"expr_grid","rows":[["","","3","3"],["×","","","2"],["","",null,"6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#12','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C4',2,'mc','auto','78 × 4를 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":12,"concept":"M3-1-u4-C4","difficulty":2,"kind":"mc","stem":"78 × 4를 어림하면 약 얼마인가요?","options":[{"t":"약 320","correct":true},{"t":"약 280","mis":"M3-1-u4-X12"},{"t":"약 80","mis":"M3-1-u4-X12"},{"t":"약 400","mis":"M3-1-u4-X11"}],"explanation":["78은 가까운 몇십 80으로 어림해요.","80 × 4 = 320이에요.","그래서 78 × 4는 약 320이에요 — 실제 곱 312와 가까워요."],"variant_rule":{"alt":[{"stem":"57 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 120","correct":true},{"t":"약 100","mis":"M3-1-u4-X12"},{"t":"약 60","mis":"M3-1-u4-X12"},{"t":"약 180","mis":"M3-1-u4-X11"}],"explanation":["57은 가까운 몇십 60으로 어림해요.","60 × 2 = 120이에요.","그래서 57 × 2는 약 120이에요 — 실제 곱 114와 가까워요."],"asset":null},{"stem":"68 × 7을 어림하면 약 얼마인가요?","options":[{"t":"약 490","correct":true},{"t":"약 420","mis":"M3-1-u4-X12"},{"t":"약 70","mis":"M3-1-u4-X12"},{"t":"약 560","mis":"M3-1-u4-X11"}],"explanation":["68은 가까운 몇십 70으로 어림해요.","70 × 7 = 490이에요.","그래서 68 × 7은 약 490이에요 — 실제 곱 476과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#13','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C5',2,'sa','auto','41 × 5의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-1-u4-C5","difficulty":2,"kind":"sa","stem":"41 × 5의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["십의 자리 곱 4 × 5 = 20이에요.","10을 넘은 2가 백의 자리로 올림해요.","41 × 5 = 205 — 백의 자리 숫자는 2예요."],"variant_rule":{"alt":[{"stem":"61 × 9의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["십의 자리 곱 6 × 9 = 54예요.","10을 넘은 5가 백의 자리로 올림해요.","61 × 9 = 549 — 백의 자리 숫자는 5예요."],"asset":null},{"stem":"21 × 8의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["십의 자리 곱 2 × 8 = 16이에요.","10을 넘은 1이 백의 자리로 올림해요.","21 × 8 = 168 — 백의 자리 숫자는 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#14','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C6',2,'sa','auto','26 × 2를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u4-C6","difficulty":2,"kind":"sa","stem":"26 × 2를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리 6 × 2 = 12예요.","일의 자리에 2를 쓰고 1을 십의 자리로 올림해요.","십의 자리 2 × 2 = 4에 1을 더해 5예요."],"asset":{"type":"expr_grid","rows":[["","","2","6"],["×","","","2"],["","",null,null]]},"variant_rule":{"alt":[{"stem":"17 × 3을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리 7 × 3 = 21이에요.","일의 자리에 1을 쓰고 2를 십의 자리로 올림해요.","십의 자리 1 × 3 = 3에 2를 더해 5예요."],"asset":{"type":"expr_grid","rows":[["","","1","7"],["×","","","3"],["","",null,null]]}},{"stem":"36 × 2를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리 6 × 2 = 12예요.","일의 자리에 2를 쓰고 1을 십의 자리로 올림해요.","십의 자리 3 × 2 = 6에 1을 더해 7이에요."],"asset":{"type":"expr_grid","rows":[["","","3","6"],["×","","","2"],["","",null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#15','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C7',2,'mc','auto','19 × 6은 얼마인가요?',ARRAY['M3-1-u4-X08','M3-1-u4-X07','M3-1-u4-X09']::text[],true,'{"seq":15,"concept":"M3-1-u4-C7","difficulty":2,"kind":"mc","stem":"19 × 6은 얼마인가요?","options":[{"t":"114","correct":true},{"t":"64","mis":"M3-1-u4-X08"},{"t":"14","mis":"M3-1-u4-X07"},{"t":"364","mis":"M3-1-u4-X09"}],"explanation":["19를 10과 9로 나누어 곱해요: 10 × 6 = 60, 9 × 6 = 54.","일의 자리 54 → 5 올림, 십의 자리 1 × 6 + 5 = 11 — 백의 자리까지 올림해요.","60 + 54 = 114 — 114는 어림한 20 × 6 = 120과 가까워요."],"variant_rule":{"alt":[{"stem":"18 × 9는 얼마인가요?","options":[{"t":"162","correct":true},{"t":"92","mis":"M3-1-u4-X08"},{"t":"62","mis":"M3-1-u4-X07"},{"t":"722","mis":"M3-1-u4-X09"}],"explanation":["18을 10과 8로 나누어 곱해요: 10 × 9 = 90, 8 × 9 = 72.","일의 자리 72 → 7 올림, 십의 자리 1 × 9 + 7 = 16 — 백의 자리까지 올림해요.","90 + 72 = 162 — 162는 어림한 20 × 9 = 180과 가까워요."],"asset":null},{"stem":"38 × 3은 얼마인가요?","options":[{"t":"114","correct":true},{"t":"94","mis":"M3-1-u4-X08"},{"t":"14","mis":"M3-1-u4-X07"},{"t":"154","mis":"M3-1-u4-X09"}],"explanation":["38을 30과 8로 나누어 곱해요: 30 × 3 = 90, 8 × 3 = 24.","일의 자리 24 → 2 올림, 십의 자리 3 × 3 + 2 = 11 — 백의 자리까지 올림해요.","90 + 24 = 114 — 114는 어림한 40 × 3 = 120과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#16','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C8',2,'sa','auto','열쇠고리를 만들어요. 별 모양 한 개에 비즈가 37개씩 들어가요. 별 모양 2개에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-1-u4-C8","difficulty":2,"kind":"sa","stem":"열쇠고리를 만들어요. 별 모양 한 개에 비즈가 37개씩 들어가요. 별 모양 2개에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["74"],"explanation":["같은 모양이 2개 반복돼요 — 곱셈으로 한 번에 구해요.","한 개의 비즈 37개 × 2개 = 37 × 2.","37 × 2 = 74 — 비즈 74개가 필요해요."],"variant_rule":{"alt":[{"stem":"열쇠고리를 만들어요. 하트 한 개에 비즈가 28개씩 들어가요. 하트 2개에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["56"],"explanation":["같은 모양이 2개 반복돼요 — 곱셈으로 한 번에 구해요.","한 개의 비즈 28개 × 2개 = 28 × 2.","28 × 2 = 56 — 비즈 56개가 필요해요."],"asset":null},{"stem":"열쇠고리를 만들어요. 바람개비 날개 한 장에 비즈가 23개씩 들어가요. 바람개비 날개 4장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["92"],"explanation":["같은 모양이 4장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 23개 × 4장 = 23 × 4.","23 × 4 = 92 — 비즈 92개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#17','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C2',3,'error','auto','90 × 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X15']::text[],true,'{"seq":17,"concept":"M3-1-u4-C2","difficulty":3,"kind":"error","stem":"90 × 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「90 × 5 = 45야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"태오 — 「9 × 5 = 45의 10배야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「십 모형 9개씩 5묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["9 × 5 = 45의 10배예요.","90 × 5 = 450이에요.","시우는 0을 빠뜨려 45라고 말했어요."],"variant_rule":{"alt":[{"stem":"20 × 9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「20 × 9 = 18이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"지유 — 「2 × 9 = 18의 10배야」","mis":"M3-1-u4-X15"},{"t":"서윤 — 「십 모형 2개씩 9묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["2 × 9 = 18의 10배예요.","20 × 9 = 180이에요.","은우는 0을 빠뜨려 18이라고 말했어요."],"asset":null},{"stem":"60 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「60 × 8 = 48이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"은우 — 「6 × 8 = 48의 10배야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「십 모형 6개씩 8묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["6 × 8 = 48의 10배예요.","60 × 8 = 480이에요.","하린은 0을 빠뜨려 48이라고 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#18','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C3',3,'error','auto','22 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X04','M3-1-u4-X15']::text[],true,'{"seq":18,"concept":"M3-1-u4-C3","difficulty":3,"kind":"error","stem":"22 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「22 × 2 = 24야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"시우 — 「22 × 2 = 44야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「20 × 2 = 40, 2 × 2 = 4, 더하면 44야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 2 × 2 = 4, 십의 자리 2 × 2 = 4(십)이에요.","22 × 2 = 44예요.","은우는 24로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"32 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「32 × 3 = 36이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"시우 — 「32 × 3 = 96이야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「어림하면 약 90이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 2 × 3 = 6, 십의 자리 3 × 3 = 9(십)이에요.","32 × 3 = 96이에요.","도윤은 36으로 잘못 구했어요."],"asset":null},{"stem":"11 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「11 × 7 = 17이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"시우 — 「11 × 7 = 77이야」","mis":"M3-1-u4-X15"},{"t":"지유 — 「10 × 7 = 70, 1 × 7 = 7, 더하면 77이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 1 × 7 = 7, 십의 자리 1 × 7 = 7(십)이에요.","11 × 7 = 77이에요.","서윤은 17로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#19','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C4',3,'ox','auto','21 × 6을 계산했더니 26이 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-1-u4-X12']::text[],true,'{"seq":19,"concept":"M3-1-u4-C4","difficulty":3,"kind":"ox","stem":"21 × 6을 계산했더니 26이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 120과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"mis":"M3-1-u4-X12","explanation":["21을 20으로 어림하면 약 120이에요.","26은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 21 × 6 = 126이에요."],"variant_rule":{"alt":[{"stem":"71 × 5를 계산했더니 55가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 350과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["71을 70으로 어림하면 약 350이에요.","55는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 71 × 5 = 355예요."],"asset":null},{"stem":"73 × 3을 계산했더니 19가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 210과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["73을 70으로 어림하면 약 210이에요.","19는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 73 × 3 = 219예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#20','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C5',3,'mc','auto','철봉에 한 번에 71초씩 8번 매달렸어요. 모두 몇 초 매달렸나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":20,"concept":"M3-1-u4-C5","difficulty":3,"kind":"mc","stem":"철봉에 한 번에 71초씩 8번 매달렸어요. 모두 몇 초 매달렸나요?","options":[{"t":"568초","correct":true},{"t":"79초","mis":"M3-1-u4-X01"},{"t":"68초","mis":"M3-1-u4-X07"},{"t":"560초","mis":"M3-1-u4-X06"}],"explanation":["71초씩 8번(묶음) — 곱셈식 71 × 8로 세워요.","십의 자리 곱 70 × 8 = 560 — 백의 자리로 올림해요.","71 × 8 = 568 — 모두 568초예요."],"variant_rule":{"alt":[{"stem":"한 상자에 귤이 62개씩 4상자 있어요. 귤은 모두 몇 개인가요?","options":[{"t":"248개","correct":true},{"t":"66개","mis":"M3-1-u4-X01"},{"t":"48개","mis":"M3-1-u4-X07"},{"t":"240개","mis":"M3-1-u4-X06"}],"explanation":["62개씩 4번(묶음) — 곱셈식 62 × 4로 세워요.","십의 자리 곱 60 × 4 = 240 — 백의 자리로 올림해요.","62 × 4 = 248 — 모두 248개예요."],"asset":null},{"stem":"계단 오르기를 하루에 71칸씩 4일 동안 했어요. 모두 몇 칸 올랐나요?","options":[{"t":"284칸","correct":true},{"t":"75칸","mis":"M3-1-u4-X01"},{"t":"84칸","mis":"M3-1-u4-X07"},{"t":"280칸","mis":"M3-1-u4-X06"}],"explanation":["71칸씩 4번(묶음) — 곱셈식 71 × 4로 세워요.","십의 자리 곱 70 × 4 = 280 — 백의 자리로 올림해요.","71 × 4 = 284 — 모두 284칸이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#21','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C6',3,'error','auto','19 × 5를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u4-X09','M3-1-u4-X15']::text[],true,'{"seq":21,"concept":"M3-1-u4-C6","difficulty":3,"kind":"error","stem":"19 × 5를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도윤 — 「올림한 4를 십의 자리 1에 먼저 더해 5 × 5 — 답은 255야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"은우 — 「1 × 5 = 5에 올림한 4를 더해 9 — 답은 95야」","mis":"M3-1-u4-X15"},{"t":"서윤 — 「10 × 5 = 50, 9 × 5 = 45, 더하면 95야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 5 = 5, + 4 = 9 — 19 × 5 = 95예요.","도윤은 먼저 더하고 곱해 255가 나왔어요."],"variant_rule":{"alt":[{"stem":"19 × 4를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서윤 — 「올림한 3을 십의 자리 1에 먼저 더해 4 × 4 — 답은 166이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"지유 — 「1 × 4 = 4에 올림한 3을 더해 7 — 답은 76이야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「10 × 4 = 40, 9 × 4 = 36, 더하면 76이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 4 = 4, + 3 = 7 — 19 × 4 = 76이에요.","서윤은 먼저 더하고 곱해 166이 나왔어요."],"asset":null},{"stem":"26 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은우 — 「올림한 1을 십의 자리 2에 먼저 더해 3 × 2 — 답은 62야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"하랑 — 「2 × 2 = 4에 올림한 1을 더해 5 — 답은 52야」","mis":"M3-1-u4-X15"},{"t":"하린 — 「20 × 2 = 40, 6 × 2 = 12, 더하면 52야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","2 × 2 = 4, + 1 = 5 — 26 × 2 = 52예요.","은우는 먼저 더하고 곱해 62가 나왔어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#22','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C7',3,'mc','auto','한 봉지에 사탕이 86개씩 8봉지 있어요. 사탕은 모두 몇 개인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X08','M3-1-u4-X07']::text[],true,'{"seq":22,"concept":"M3-1-u4-C7","difficulty":3,"kind":"mc","stem":"한 봉지에 사탕이 86개씩 8봉지 있어요. 사탕은 모두 몇 개인가요?","options":[{"t":"688개","correct":true},{"t":"94개","mis":"M3-1-u4-X01"},{"t":"648개","mis":"M3-1-u4-X08"},{"t":"88개","mis":"M3-1-u4-X07"}],"explanation":["86개씩 8번(묶음) — 곱셈식 86 × 8로 세워요.","일의 자리 48 → 4 올림, 십의 자리 8 × 8 + 4 = 68 — 백의 자리까지 올림해요.","86 × 8 = 688 — 모두 688개예요."],"variant_rule":{"alt":[{"stem":"철봉에 한 번에 49초씩 3번 매달렸어요. 모두 몇 초 매달렸나요?","options":[{"t":"147초","correct":true},{"t":"52초","mis":"M3-1-u4-X01"},{"t":"127초","mis":"M3-1-u4-X08"},{"t":"47초","mis":"M3-1-u4-X07"}],"explanation":["49초씩 3번(묶음) — 곱셈식 49 × 3으로 세워요.","일의 자리 27 → 2 올림, 십의 자리 4 × 3 + 2 = 14 — 백의 자리까지 올림해요.","49 × 3 = 147 — 모두 147초예요."],"asset":null},{"stem":"걷기 운동을 하루에 42분씩 9일 동안 했어요. 모두 몇 분 걸었나요?","options":[{"t":"378분","correct":true},{"t":"51분","mis":"M3-1-u4-X01"},{"t":"368분","mis":"M3-1-u4-X08"},{"t":"78분","mis":"M3-1-u4-X07"}],"explanation":["42분씩 9번(묶음) — 곱셈식 42 × 9로 세워요.","일의 자리 18 → 1 올림, 십의 자리 4 × 9 + 1 = 37 — 백의 자리까지 올림해요.","42 × 9 = 378 — 모두 378분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#23','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C8',4,'mc','auto','나비 날개 한 장의 비즈는 8개씩 4줄과 5개씩 3줄이에요. 날개 4장을 만들려면 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X14','M3-1-u4-X01']::text[],true,'{"seq":23,"concept":"M3-1-u4-C8","difficulty":4,"kind":"mc","stem":"나비 날개 한 장의 비즈는 8개씩 4줄과 5개씩 3줄이에요. 날개 4장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"188개","correct":true},{"t":"128개","mis":"M3-1-u4-X14"},{"t":"60개","mis":"M3-1-u4-X14"},{"t":"51개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 8 × 4 + 5 × 3 = 32 + 15 = 47개.","날개 4장: 47 × 4.","47 × 4 = 188 — 비즈 188개가 필요해요."],"variant_rule":{"alt":[{"stem":"나비 날개 한 장의 비즈는 7개씩 3줄과 6개씩 4줄이에요. 날개 3장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"135개","correct":true},{"t":"63개","mis":"M3-1-u4-X14"},{"t":"72개","mis":"M3-1-u4-X14"},{"t":"48개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 7 × 3 + 6 × 4 = 21 + 24 = 45개.","날개 3장: 45 × 3.","45 × 3 = 135 — 비즈 135개가 필요해요."],"asset":null},{"stem":"나비 날개 한 장의 비즈는 9개씩 2줄과 4개씩 5줄이에요. 날개 5장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"190개","correct":true},{"t":"90개","mis":"M3-1-u4-X14"},{"t":"100개","mis":"M3-1-u4-X14"},{"t":"43개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 9 × 2 + 4 × 5 = 18 + 20 = 38개.","날개 5장: 38 × 5.","38 × 5 = 190 — 비즈 190개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#24','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C7',4,'mc','auto','곱이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":24,"concept":"M3-1-u4-C7","difficulty":4,"kind":"mc","stem":"곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"49 × 4","correct":true},{"t":"18 × 8","mis":"M3-1-u4-X11"},{"t":"22 × 5","mis":"M3-1-u4-X11"},{"t":"96 × 2","mis":"M3-1-u4-X15"}],"explanation":["하나씩 곱을 구해요.","49 × 4 = 196, 18 × 8 = 144, 22 × 5 = 110, 96 × 2 = 192.","곱이 가장 큰 것은 49 × 4 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"34 × 8","correct":true},{"t":"27 × 5","mis":"M3-1-u4-X11"},{"t":"38 × 4","mis":"M3-1-u4-X11"},{"t":"57 × 2","mis":"M3-1-u4-X15"}],"explanation":["하나씩 곱을 구해요.","34 × 8 = 272, 27 × 5 = 135, 38 × 4 = 152, 57 × 2 = 114.","곱이 가장 큰 것은 34 × 8 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"52 × 7","correct":true},{"t":"69 × 2","mis":"M3-1-u4-X15"},{"t":"66 × 5","mis":"M3-1-u4-X11"},{"t":"37 × 3","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","52 × 7 = 364, 69 × 2 = 138, 66 × 5 = 330, 37 × 3 = 111.","곱이 가장 큰 것은 52 × 7 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_a#25','math',3,1,'u4','','g3_1_math_u4_review_a','unit_review','M3-1-u4-C7',4,'essay','teacher','줄넘기를 한 번에 74회씩 8세트 했어요. 74 × 8을 계산하는 과정을 쓰고, 어림으로 답이 맞는지 확인해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u4-C7","difficulty":4,"kind":"essay","stem":"줄넘기를 한 번에 74회씩 8세트 했어요. 74 × 8을 계산하는 과정을 쓰고, 어림으로 답이 맞는지 확인해 보세요.","answer_guide":{"answer":"예: 70 × 8 = 560, 4 × 8 = 32, 더하면 592회이다. 74를 70으로 어림하면 약 560이므로 592는 알맞다.","scoring_points":["560과 32로 나누어 곱했는가","592를 구했는가","약 560으로 어림해 확인했는가"]},"explanation":["70 × 8 = 560, 4 × 8 = 32.","560 + 32 = 592.","어림 약 560 — 592와 가까워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#1','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C1',1,'mc','auto','24 + 24를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":1,"concept":"M3-1-u4-C1","difficulty":1,"kind":"mc","stem":"24 + 24를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"24 × 2","correct":true},{"t":"24 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"24 × 24","mis":"M3-1-u4-X13"}],"explanation":["같은 수 24를 2번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","24를 2번 → 24 × 2."],"variant_rule":{"alt":[{"stem":"21 + 21을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"21 × 2","correct":true},{"t":"21 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"21 × 21","mis":"M3-1-u4-X13"}],"explanation":["같은 수 21을 2번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","21을 2번 → 21 × 2."],"asset":null},{"stem":"22 + 22 + 22 + 22를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"22 × 4","correct":true},{"t":"22 + 4","mis":"M3-1-u4-X01"},{"t":"4 × 4","mis":"M3-1-u4-X13"},{"t":"22 × 22","mis":"M3-1-u4-X13"}],"explanation":["같은 수 22를 4번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","22를 4번 → 22 × 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#2','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C2',1,'mc','auto','2 × 4 = 8이에요. 그러면 20 × 4는 얼마인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X03','M3-1-u4-X11']::text[],true,'{"seq":2,"concept":"M3-1-u4-C2","difficulty":1,"kind":"mc","stem":"2 × 4 = 8이에요. 그러면 20 × 4는 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8","mis":"M3-1-u4-X02"},{"t":"800","mis":"M3-1-u4-X03"},{"t":"90","mis":"M3-1-u4-X11"}],"explanation":["20은 2의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","8의 10배 — 20 × 4 = 80이에요."],"variant_rule":{"alt":[{"stem":"3 × 2 = 6이에요. 그러면 30 × 2는 얼마인가요?","options":[{"t":"60","correct":true},{"t":"6","mis":"M3-1-u4-X02"},{"t":"600","mis":"M3-1-u4-X03"},{"t":"70","mis":"M3-1-u4-X11"}],"explanation":["30은 3의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","6의 10배 — 30 × 2 = 60이에요."],"asset":null},{"stem":"1 × 9 = 9예요. 그러면 10 × 9는 얼마인가요?","options":[{"t":"90","correct":true},{"t":"9","mis":"M3-1-u4-X02"},{"t":"900","mis":"M3-1-u4-X03"},{"t":"100","mis":"M3-1-u4-X11"}],"explanation":["10은 1의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","9의 10배 — 10 × 9 = 90이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#3','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C2',1,'sa','auto','30 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C2","difficulty":1,"kind":"sa","stem":"30 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["3 × 2 = 6이에요.","30은 3의 10배라 곱도 10배예요.","30 × 2 = 60이에요."],"variant_rule":{"alt":[{"stem":"10 × 6은 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["1 × 6 = 6이에요.","10은 1의 10배라 곱도 10배예요.","10 × 6 = 60이에요."],"asset":null},{"stem":"30 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["3 × 3 = 9예요.","30은 3의 10배라 곱도 10배예요.","30 × 3 = 90이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#4','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C3',1,'sa','auto','13 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"13 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["13을 10과 3으로 나누어 곱해요: 10 × 3 = 30, 3 × 3 = 9.","일의 자리 3 × 3 = 9, 십의 자리 1 × 3 = 3(십)이에요.","30 + 9 = 39 — 39는 어림한 10 × 3 = 30과 가까워요."],"variant_rule":{"alt":[{"stem":"33 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["66"],"explanation":["33을 30과 3으로 나누어 곱해요: 30 × 2 = 60, 3 × 2 = 6.","일의 자리 3 × 2 = 6, 십의 자리 3 × 2 = 6(십)이에요.","60 + 6 = 66 — 66은 어림한 30 × 2 = 60과 가까워요."],"asset":null},{"stem":"14 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["14를 10과 4로 나누어 곱해요: 10 × 2 = 20, 4 × 2 = 8.","일의 자리 4 × 2 = 8, 십의 자리 1 × 2 = 2(십)이에요.","20 + 8 = 28 — 28은 어림한 10 × 2 = 20과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#5','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C3',1,'sa','auto','11 × 5를 10과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"11 × 5를 10과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["10 × 5 = 50.","□는 1 × 5 = 5예요.","50 + 5 = 55 — 11 × 5의 곱이에요."],"asset":{"type":"expr_grid","rows":[["10 × 5","=","50"],["1 × 5","=",null],["50 + □","=","55"]]},"variant_rule":{"alt":[{"stem":"32 × 3을 30과 2로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["30 × 3 = 90.","□는 2 × 3 = 6이에요.","90 + 6 = 96 — 32 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["30 × 3","=","90"],["2 × 3","=",null],["90 + □","=","96"]]}},{"stem":"11 × 6을 10과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["10 × 6 = 60.","□는 1 × 6 = 6이에요.","60 + 6 = 66 — 11 × 6의 곱이에요."],"asset":{"type":"expr_grid","rows":[["10 × 6","=","60"],["1 × 6","=",null],["60 + □","=","66"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#6','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C4',1,'mc','auto','42 × 2를 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":6,"concept":"M3-1-u4-C4","difficulty":1,"kind":"mc","stem":"42 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 80","correct":true},{"t":"약 100","mis":"M3-1-u4-X12"},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 120","mis":"M3-1-u4-X11"}],"explanation":["42는 가까운 몇십 40으로 어림해요.","40 × 2 = 80이에요.","그래서 42 × 2는 약 80이에요 — 실제 곱 84와 가까워요."],"variant_rule":{"alt":[{"stem":"11 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 20","correct":true},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 10","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X11"}],"explanation":["11은 가까운 몇십 10으로 어림해요.","10 × 2 = 20이에요.","그래서 11 × 2는 약 20이에요 — 실제 곱 22와 가까워요."],"asset":null},{"stem":"11 × 9를 어림하면 약 얼마인가요?","options":[{"t":"약 90","correct":true},{"t":"약 180","mis":"M3-1-u4-X12"},{"t":"약 10","mis":"M3-1-u4-X12"},{"t":"약 100","mis":"M3-1-u4-X11"}],"explanation":["11은 가까운 몇십 10으로 어림해요.","10 × 9 = 90이에요.","그래서 11 × 9는 약 90이에요 — 실제 곱 99와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#7','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C5',1,'mc','auto','61 × 6은 얼마인가요?',ARRAY['M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":7,"concept":"M3-1-u4-C5","difficulty":1,"kind":"mc","stem":"61 × 6은 얼마인가요?","options":[{"t":"366","correct":true},{"t":"66","mis":"M3-1-u4-X07"},{"t":"360","mis":"M3-1-u4-X06"},{"t":"6","mis":"M3-1-u4-X06"}],"explanation":["61을 60과 1로 나누어 곱해요: 60 × 6 = 360, 1 × 6 = 6.","십의 자리 곱 60 × 6 = 360 — 백의 자리로 올림해요.","360 + 6 = 366 — 366은 어림한 60 × 6 = 360과 가까워요."],"variant_rule":{"alt":[{"stem":"53 × 2는 얼마인가요?","options":[{"t":"106","correct":true},{"t":"6","mis":"M3-1-u4-X07"},{"t":"100","mis":"M3-1-u4-X06"},{"t":"56","mis":"M3-1-u4-X04"}],"explanation":["53을 50과 3으로 나누어 곱해요: 50 × 2 = 100, 3 × 2 = 6.","십의 자리 곱 50 × 2 = 100 — 백의 자리로 올림해요.","100 + 6 = 106 — 106은 어림한 50 × 2 = 100과 가까워요."],"asset":null},{"stem":"72 × 4는 얼마인가요?","options":[{"t":"288","correct":true},{"t":"88","mis":"M3-1-u4-X07"},{"t":"280","mis":"M3-1-u4-X06"},{"t":"8","mis":"M3-1-u4-X06"}],"explanation":["72를 70과 2로 나누어 곱해요: 70 × 4 = 280, 2 × 4 = 8.","십의 자리 곱 70 × 4 = 280 — 백의 자리로 올림해요.","280 + 8 = 288 — 288은 어림한 70 × 4 = 280과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#8','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C6',1,'sa','auto','14 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u4-C6","difficulty":1,"kind":"sa","stem":"14 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["98"],"explanation":["14를 10과 4로 나누어 곱해요: 10 × 7 = 70, 4 × 7 = 28.","일의 자리 곱 4 × 7 = 28 — 2를 십의 자리로 올림해 더해요.","70 + 28 = 98 — 98은 어림한 10 × 7 = 70과 가까워요."],"variant_rule":{"alt":[{"stem":"13 × 5는 얼마인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["13을 10과 3으로 나누어 곱해요: 10 × 5 = 50, 3 × 5 = 15.","일의 자리 곱 3 × 5 = 15 — 1을 십의 자리로 올림해 더해요.","50 + 15 = 65 — 65는 어림한 10 × 5 = 50과 가까워요."],"asset":null},{"stem":"23 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["92"],"explanation":["23을 20과 3으로 나누어 곱해요: 20 × 4 = 80, 3 × 4 = 12.","일의 자리 곱 3 × 4 = 12 — 1을 십의 자리로 올림해 더해요.","80 + 12 = 92 — 92는 어림한 20 × 4 = 80과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#9','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C1',2,'mc','auto','훌라후프를 한 번에 39바퀴씩 3번 돌렸어요. 모두 몇 바퀴 돌렸는지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":9,"concept":"M3-1-u4-C1","difficulty":2,"kind":"mc","stem":"훌라후프를 한 번에 39바퀴씩 3번 돌렸어요. 모두 몇 바퀴 돌렸는지 구하는 식은 어느 것인가요?","options":[{"t":"39 × 3","correct":true},{"t":"39 + 3","mis":"M3-1-u4-X01"},{"t":"3 × 3","mis":"M3-1-u4-X13"},{"t":"39 × 39","mis":"M3-1-u4-X13"}],"explanation":["39바퀴씩 3번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 39 × 3."],"variant_rule":{"alt":[{"stem":"생수가 한 묶음에 69병씩 7묶음 있어요. 생수는 모두 몇 병인지 구하는 식은 어느 것인가요?","options":[{"t":"69 × 7","correct":true},{"t":"69 + 7","mis":"M3-1-u4-X01"},{"t":"7 × 7","mis":"M3-1-u4-X13"},{"t":"69 × 69","mis":"M3-1-u4-X13"}],"explanation":["69병씩 7번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 69 × 7."],"asset":null},{"stem":"체조를 하루에 88분씩 2일 동안 했어요. 모두 몇 분 했는지 구하는 식은 어느 것인가요?","options":[{"t":"88 × 2","correct":true},{"t":"88 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"88 × 88","mis":"M3-1-u4-X13"}],"explanation":["88분씩 2번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 88 × 2."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#10','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C2',2,'ox','auto','50 × 5 = 25예요.',ARRAY['M3-1-u4-X02']::text[],true,'{"seq":10,"concept":"M3-1-u4-C2","difficulty":2,"kind":"ox","stem":"50 × 5 = 25예요.","answer":"X","reason_options":[{"t":"50 × 5는 5 × 5의 10배라서","correct":true},{"t":"5 × 5 = 25니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"mis":"M3-1-u4-X02","explanation":["5 × 5 = 25예요.","50은 5의 10배라 곱도 10배 — 250이에요.","0을 빠뜨리면 십 모형 25개를 낱개 25개로 센 셈이에요."],"variant_rule":{"alt":[{"stem":"80 × 4 = 32예요.","answer":"X","reason_options":[{"t":"80 × 4는 8 × 4의 10배라서","correct":true},{"t":"8 × 4 = 32니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["8 × 4 = 32예요.","80은 8의 10배라 곱도 10배 — 320이에요.","0을 빠뜨리면 십 모형 32개를 낱개 32개로 센 셈이에요."],"asset":null},{"stem":"80 × 3 = 24예요.","answer":"X","reason_options":[{"t":"80 × 3은 8 × 3의 10배라서","correct":true},{"t":"8 × 3 = 24니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["8 × 3 = 24예요.","80은 8의 10배라 곱도 10배 — 240이에요.","0을 빠뜨리면 십 모형 24개를 낱개 24개로 센 셈이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#11','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C3',2,'sa','auto','22 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-1-u4-C3","difficulty":2,"kind":"sa","stem":"22 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 2 × 4 = 8 → 8을 써요.","22 × 4 = 88 — 일의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["","","2","2"],["×","","","4"],["","","8",null]]},"variant_rule":{"alt":[{"stem":"21 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 2 × 3 = 6 → 6을 써요.","21 × 3 = 63 — 십의 자리 숫자는 6이에요."],"asset":{"type":"expr_grid","rows":[["","","2","1"],["×","","","3"],["","",null,"3"]]}},{"stem":"11 × 9의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 1 × 9 = 9 → 9를 써요.","11 × 9 = 99 — 일의 자리 숫자는 9예요."],"asset":{"type":"expr_grid","rows":[["","","1","1"],["×","","","9"],["","","9",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#12','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C4',2,'mc','auto','33 × 4를 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":12,"concept":"M3-1-u4-C4","difficulty":2,"kind":"mc","stem":"33 × 4를 어림하면 약 얼마인가요?","options":[{"t":"약 120","correct":true},{"t":"약 160","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X12"},{"t":"약 150","mis":"M3-1-u4-X11"}],"explanation":["33은 가까운 몇십 30으로 어림해요.","30 × 4 = 120이에요.","그래서 33 × 4는 약 120이에요 — 실제 곱 132와 가까워요."],"variant_rule":{"alt":[{"stem":"38 × 8을 어림하면 약 얼마인가요?","options":[{"t":"약 320","correct":true},{"t":"약 240","mis":"M3-1-u4-X12"},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 360","mis":"M3-1-u4-X11"}],"explanation":["38은 가까운 몇십 40으로 어림해요.","40 × 8 = 320이에요.","그래서 38 × 8은 약 320이에요 — 실제 곱 304와 가까워요."],"asset":null},{"stem":"97 × 9를 어림하면 약 얼마인가요?","options":[{"t":"약 900","correct":true},{"t":"약 810","mis":"M3-1-u4-X12"},{"t":"약 100","mis":"M3-1-u4-X12"},{"t":"약 1000","mis":"M3-1-u4-X11"}],"explanation":["97은 가까운 몇십 100으로 어림해요.","100 × 9 = 900이에요.","그래서 97 × 9는 약 900이에요 — 실제 곱 873과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#13','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C5',2,'sa','auto','71 × 2의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-1-u4-C5","difficulty":2,"kind":"sa","stem":"71 × 2의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["십의 자리 곱 7 × 2 = 14예요.","10을 넘은 1이 백의 자리로 올림해요.","71 × 2 = 142 — 백의 자리 숫자는 1이에요."],"variant_rule":{"alt":[{"stem":"91 × 7의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["십의 자리 곱 9 × 7 = 63이에요.","10을 넘은 6이 백의 자리로 올림해요.","91 × 7 = 637 — 백의 자리 숫자는 6이에요."],"asset":null},{"stem":"41 × 6의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["십의 자리 곱 4 × 6 = 24예요.","10을 넘은 2가 백의 자리로 올림해요.","41 × 6 = 246 — 백의 자리 숫자는 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#14','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C6',2,'sa','auto','14 × 3을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u4-C6","difficulty":2,"kind":"sa","stem":"14 × 3을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리 4 × 3 = 12예요.","일의 자리에 2를 쓰고 1을 십의 자리로 올림해요.","십의 자리 1 × 3 = 3에 1을 더해 4예요."],"asset":{"type":"expr_grid","rows":[["","","1","4"],["×","","","3"],["","",null,null]]},"variant_rule":{"alt":[{"stem":"18 × 4를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["일의 자리 8 × 4 = 32예요.","일의 자리에 2를 쓰고 3을 십의 자리로 올림해요.","십의 자리 1 × 4 = 4에 3을 더해 7이에요."],"asset":{"type":"expr_grid","rows":[["","","1","8"],["×","","","4"],["","",null,null]]}},{"stem":"19 × 4를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["일의 자리 9 × 4 = 36이에요.","일의 자리에 6을 쓰고 3을 십의 자리로 올림해요.","십의 자리 1 × 4 = 4에 3을 더해 7이에요."],"asset":{"type":"expr_grid","rows":[["","","1","9"],["×","","","4"],["","",null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#15','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C7',2,'mc','auto','27 × 5는 얼마인가요?',ARRAY['M3-1-u4-X08','M3-1-u4-X07','M3-1-u4-X09']::text[],true,'{"seq":15,"concept":"M3-1-u4-C7","difficulty":2,"kind":"mc","stem":"27 × 5는 얼마인가요?","options":[{"t":"135","correct":true},{"t":"105","mis":"M3-1-u4-X08"},{"t":"35","mis":"M3-1-u4-X07"},{"t":"255","mis":"M3-1-u4-X09"}],"explanation":["27을 20과 7로 나누어 곱해요: 20 × 5 = 100, 7 × 5 = 35.","일의 자리 35 → 3 올림, 십의 자리 2 × 5 + 3 = 13 — 백의 자리까지 올림해요.","100 + 35 = 135 — 135는 어림한 30 × 5 = 150과 가까워요."],"variant_rule":{"alt":[{"stem":"79 × 3은 얼마인가요?","options":[{"t":"237","correct":true},{"t":"217","mis":"M3-1-u4-X08"},{"t":"37","mis":"M3-1-u4-X07"},{"t":"277","mis":"M3-1-u4-X09"}],"explanation":["79를 70과 9로 나누어 곱해요: 70 × 3 = 210, 9 × 3 = 27.","일의 자리 27 → 2 올림, 십의 자리 7 × 3 + 2 = 23 — 백의 자리까지 올림해요.","210 + 27 = 237 — 237은 어림한 80 × 3 = 240과 가까워요."],"asset":null},{"stem":"48 × 5는 얼마인가요?","options":[{"t":"240","correct":true},{"t":"200","mis":"M3-1-u4-X08"},{"t":"40","mis":"M3-1-u4-X07"},{"t":"400","mis":"M3-1-u4-X09"}],"explanation":["48을 40과 8로 나누어 곱해요: 40 × 5 = 200, 8 × 5 = 40.","일의 자리 40 → 4 올림, 십의 자리 4 × 5 + 4 = 24 — 백의 자리까지 올림해요.","200 + 40 = 240 — 240은 어림한 50 × 5 = 250과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#16','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C8',2,'sa','auto','열쇠고리를 만들어요. 하트 한 개에 비즈가 38개씩 들어가요. 하트 2개에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-1-u4-C8","difficulty":2,"kind":"sa","stem":"열쇠고리를 만들어요. 하트 한 개에 비즈가 38개씩 들어가요. 하트 2개에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["76"],"explanation":["같은 모양이 2개 반복돼요 — 곱셈으로 한 번에 구해요.","한 개의 비즈 38개 × 2개 = 38 × 2.","38 × 2 = 76 — 비즈 76개가 필요해요."],"variant_rule":{"alt":[{"stem":"열쇠고리를 만들어요. 바람개비 날개 한 장에 비즈가 28개씩 들어가요. 바람개비 날개 2장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["56"],"explanation":["같은 모양이 2장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 28개 × 2장 = 28 × 2.","28 × 2 = 56 — 비즈 56개가 필요해요."],"asset":null},{"stem":"열쇠고리를 만들어요. 꽃잎 한 장에 비즈가 16개씩 들어가요. 꽃잎 5장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["80"],"explanation":["같은 모양이 5장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 16개 × 5장 = 16 × 5.","16 × 5 = 80 — 비즈 80개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#17','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C2',3,'error','auto','30 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X15']::text[],true,'{"seq":17,"concept":"M3-1-u4-C2","difficulty":3,"kind":"error","stem":"30 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「30 × 7 = 21이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"시우 — 「3 × 7 = 21의 10배야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「십 모형 3개씩 7묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["3 × 7 = 21의 10배예요.","30 × 7 = 210이에요.","태오는 0을 빠뜨려 21이라고 말했어요."],"variant_rule":{"alt":[{"stem":"50 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「50 × 7 = 35야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"태오 — 「5 × 7 = 35의 10배야」","mis":"M3-1-u4-X15"},{"t":"하린 — 「십 모형 5개씩 7묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["5 × 7 = 35의 10배예요.","50 × 7 = 350이에요.","도윤은 0을 빠뜨려 35라고 말했어요."],"asset":null},{"stem":"80 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「80 × 8 = 64야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"시우 — 「8 × 8 = 64의 10배야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「십 모형 8개씩 8묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["8 × 8 = 64의 10배예요.","80 × 8 = 640이에요.","지유는 0을 빠뜨려 64라고 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#18','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C3',3,'error','auto','32 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X04','M3-1-u4-X15']::text[],true,'{"seq":18,"concept":"M3-1-u4-C3","difficulty":3,"kind":"error","stem":"32 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「32 × 2 = 34야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"태오 — 「32 × 2 = 64야」","mis":"M3-1-u4-X15"},{"t":"도윤 — 「어림하면 약 60이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 2 × 2 = 4, 십의 자리 3 × 2 = 6(십)이에요.","32 × 2 = 64예요.","하린은 34로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"32 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「32 × 3 = 36이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"지유 — 「32 × 3 = 96이야」","mis":"M3-1-u4-X15"},{"t":"하랑 — 「30 × 3 = 90, 2 × 3 = 6, 더하면 96이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 2 × 3 = 6, 십의 자리 3 × 3 = 9(십)이에요.","32 × 3 = 96이에요.","시우는 36으로 잘못 구했어요."],"asset":null},{"stem":"24 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「24 × 2 = 28이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"지유 — 「24 × 2 = 48이야」","mis":"M3-1-u4-X15"},{"t":"서윤 — 「어림하면 약 40이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 4 × 2 = 8, 십의 자리 2 × 2 = 4(십)이에요.","24 × 2 = 48이에요.","태오는 28로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#19','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C4',3,'ox','auto','81 × 3을 계산했더니 43이 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-1-u4-X12']::text[],true,'{"seq":19,"concept":"M3-1-u4-C4","difficulty":3,"kind":"ox","stem":"81 × 3을 계산했더니 43이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 240과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"mis":"M3-1-u4-X12","explanation":["81을 80으로 어림하면 약 240이에요.","43은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 81 × 3 = 243이에요."],"variant_rule":{"alt":[{"stem":"42 × 3을 계산했더니 26이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 120과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["42를 40으로 어림하면 약 120이에요.","26은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 42 × 3 = 126이에요."],"asset":null},{"stem":"81 × 8을 계산했더니 48이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 640과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["81을 80으로 어림하면 약 640이에요.","48은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 81 × 8 = 648이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#20','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C5',3,'mc','auto','한 상자에 귤이 51개씩 5상자 있어요. 귤은 모두 몇 개인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":20,"concept":"M3-1-u4-C5","difficulty":3,"kind":"mc","stem":"한 상자에 귤이 51개씩 5상자 있어요. 귤은 모두 몇 개인가요?","options":[{"t":"255개","correct":true},{"t":"56개","mis":"M3-1-u4-X01"},{"t":"55개","mis":"M3-1-u4-X07"},{"t":"250개","mis":"M3-1-u4-X06"}],"explanation":["51개씩 5번(묶음) — 곱셈식 51 × 5로 세워요.","십의 자리 곱 50 × 5 = 250 — 백의 자리로 올림해요.","51 × 5 = 255 — 모두 255개예요."],"variant_rule":{"alt":[{"stem":"윗몸 일으키기를 하루에 21개씩 5일 동안 했어요. 모두 몇 개 했나요?","options":[{"t":"105개","correct":true},{"t":"26개","mis":"M3-1-u4-X01"},{"t":"5개","mis":"M3-1-u4-X07"},{"t":"100개","mis":"M3-1-u4-X06"}],"explanation":["21개씩 5번(묶음) — 곱셈식 21 × 5로 세워요.","십의 자리 곱 20 × 5 = 100 — 백의 자리로 올림해요.","21 × 5 = 105 — 모두 105개예요."],"asset":null},{"stem":"양치질을 한 달에 51번씩 9달 동안 빠짐없이 했어요. 모두 몇 번 했나요?","options":[{"t":"459번","correct":true},{"t":"60번","mis":"M3-1-u4-X01"},{"t":"59번","mis":"M3-1-u4-X07"},{"t":"450번","mis":"M3-1-u4-X06"}],"explanation":["51번씩 9번(묶음) — 곱셈식 51 × 9로 세워요.","십의 자리 곱 50 × 9 = 450 — 백의 자리로 올림해요.","51 × 9 = 459 — 모두 459번이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#21','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C6',3,'error','auto','14 × 7을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u4-X09','M3-1-u4-X15']::text[],true,'{"seq":21,"concept":"M3-1-u4-C6","difficulty":3,"kind":"error","stem":"14 × 7을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시우 — 「올림한 2를 십의 자리 1에 먼저 더해 3 × 7 — 답은 218이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"하랑 — 「1 × 7 = 7에 올림한 2를 더해 9 — 답은 98이야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「10 × 7 = 70, 4 × 7 = 28, 더하면 98이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 7 = 7, + 2 = 9 — 14 × 7 = 98이에요.","시우는 먼저 더하고 곱해 218이 나왔어요."],"variant_rule":{"alt":[{"stem":"16 × 6을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시우 — 「올림한 3을 십의 자리 1에 먼저 더해 4 × 6 — 답은 246이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"도윤 — 「1 × 6 = 6에 올림한 3을 더해 9 — 답은 96이야」","mis":"M3-1-u4-X15"},{"t":"하랑 — 「10 × 6 = 60, 6 × 6 = 36, 더하면 96이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 6 = 6, + 3 = 9 — 16 × 6 = 96이에요.","시우는 먼저 더하고 곱해 246이 나왔어요."],"asset":null},{"stem":"36 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은우 — 「올림한 1을 십의 자리 3에 먼저 더해 4 × 2 — 답은 82야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"지유 — 「3 × 2 = 6에 올림한 1을 더해 7 — 답은 72야」","mis":"M3-1-u4-X15"},{"t":"도윤 — 「30 × 2 = 60, 6 × 2 = 12, 더하면 72야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","3 × 2 = 6, + 1 = 7 — 36 × 2 = 72예요.","은우는 먼저 더하고 곱해 82가 나왔어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#22','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C7',3,'mc','auto','줄넘기를 한 번에 84회씩 8번 했어요. 모두 몇 회 했나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X08','M3-1-u4-X07']::text[],true,'{"seq":22,"concept":"M3-1-u4-C7","difficulty":3,"kind":"mc","stem":"줄넘기를 한 번에 84회씩 8번 했어요. 모두 몇 회 했나요?","options":[{"t":"672회","correct":true},{"t":"92회","mis":"M3-1-u4-X01"},{"t":"642회","mis":"M3-1-u4-X08"},{"t":"72회","mis":"M3-1-u4-X07"}],"explanation":["84회씩 8번(묶음) — 곱셈식 84 × 8로 세워요.","일의 자리 32 → 3 올림, 십의 자리 8 × 8 + 3 = 67 — 백의 자리까지 올림해요.","84 × 8 = 672 — 모두 672회예요."],"variant_rule":{"alt":[{"stem":"체조를 하루에 96분씩 2일 동안 했어요. 모두 몇 분 했나요?","options":[{"t":"192분","correct":true},{"t":"98분","mis":"M3-1-u4-X01"},{"t":"182분","mis":"M3-1-u4-X08"},{"t":"92분","mis":"M3-1-u4-X07"}],"explanation":["96분씩 2번(묶음) — 곱셈식 96 × 2로 세워요.","일의 자리 12 → 1 올림, 십의 자리 9 × 2 + 1 = 19 — 백의 자리까지 올림해요.","96 × 2 = 192 — 모두 192분이에요."],"asset":null},{"stem":"길이가 79cm인 골판지 7개를 겹치지 않게 이었어요. 모두 몇 cm인가요?","options":[{"t":"553cm","correct":true},{"t":"86cm","mis":"M3-1-u4-X01"},{"t":"493cm","mis":"M3-1-u4-X08"},{"t":"53cm","mis":"M3-1-u4-X07"}],"explanation":["79cm씩 7번(묶음) — 곱셈식 79 × 7로 세워요.","일의 자리 63 → 6 올림, 십의 자리 7 × 7 + 6 = 55 — 백의 자리까지 올림해요.","79 × 7 = 553 — 모두 553cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#23','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C8',4,'mc','auto','나비 날개 한 장의 비즈는 8개씩 5줄과 7개씩 2줄이에요. 날개 6장을 만들려면 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X14','M3-1-u4-X01']::text[],true,'{"seq":23,"concept":"M3-1-u4-C8","difficulty":4,"kind":"mc","stem":"나비 날개 한 장의 비즈는 8개씩 5줄과 7개씩 2줄이에요. 날개 6장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"324개","correct":true},{"t":"240개","mis":"M3-1-u4-X14"},{"t":"84개","mis":"M3-1-u4-X14"},{"t":"60개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 8 × 5 + 7 × 2 = 40 + 14 = 54개.","날개 6장: 54 × 6.","54 × 6 = 324 — 비즈 324개가 필요해요."],"variant_rule":{"alt":[{"stem":"나비 날개 한 장의 비즈는 6개씩 3줄과 4개씩 6줄이에요. 날개 4장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"168개","correct":true},{"t":"72개","mis":"M3-1-u4-X14"},{"t":"96개","mis":"M3-1-u4-X14"},{"t":"46개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 6 × 3 + 4 × 6 = 18 + 24 = 42개.","날개 4장: 42 × 4.","42 × 4 = 168 — 비즈 168개가 필요해요."],"asset":null},{"stem":"나비 날개 한 장의 비즈는 9개씩 4줄과 5개씩 2줄이에요. 날개 7장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"322개","correct":true},{"t":"252개","mis":"M3-1-u4-X14"},{"t":"70개","mis":"M3-1-u4-X14"},{"t":"53개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 9 × 4 + 5 × 2 = 36 + 10 = 46개.","날개 7장: 46 × 7.","46 × 7 = 322 — 비즈 322개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#24','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C7',4,'mc','auto','곱이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":24,"concept":"M3-1-u4-C7","difficulty":4,"kind":"mc","stem":"곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"27 × 9","correct":true},{"t":"57 × 3","mis":"M3-1-u4-X11"},{"t":"36 × 3","mis":"M3-1-u4-X11"},{"t":"68 × 3","mis":"M3-1-u4-X15"}],"explanation":["하나씩 곱을 구해요.","27 × 9 = 243, 57 × 3 = 171, 36 × 3 = 108, 68 × 3 = 204.","곱이 가장 큰 것은 27 × 9 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"86 × 7","correct":true},{"t":"82 × 5","mis":"M3-1-u4-X15"},{"t":"58 × 3","mis":"M3-1-u4-X11"},{"t":"57 × 2","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","86 × 7 = 602, 82 × 5 = 410, 58 × 3 = 174, 57 × 2 = 114.","곱이 가장 큰 것은 86 × 7 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"76 × 9","correct":true},{"t":"36 × 4","mis":"M3-1-u4-X11"},{"t":"89 × 3","mis":"M3-1-u4-X15"},{"t":"37 × 3","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","76 × 9 = 684, 36 × 4 = 144, 89 × 3 = 267, 37 × 3 = 111.","곱이 가장 큰 것은 76 × 9 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_b#25','math',3,1,'u4','','g3_1_math_u4_review_b','unit_review','M3-1-u4-C6',4,'essay','teacher','지유는 23 × 4를 82라고 했어요. 지유의 실수를 찾고 바른 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u4-C6","difficulty":4,"kind":"essay","stem":"지유는 23 × 4를 82라고 했어요. 지유의 실수를 찾고 바른 답을 구해 보세요.","answer_guide":{"answer":"예: 일의 자리 3 × 4 = 12에서 올림한 1을 십의 자리 곱 2 × 4 = 8에 더하지 않았다. 8 + 1 = 9이므로 바른 답은 92이다.","scoring_points":["올림한 1을 빠뜨렸다고 찾았는가","8 + 1 = 9로 고쳤는가","92를 구했는가"]},"explanation":["3 × 4 = 12 → 1 올림.","2 × 4 + 1 = 9.","23 × 4 = 92."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#1','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C1',1,'mc','auto','33 + 33 + 33을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":1,"concept":"M3-1-u4-C1","difficulty":1,"kind":"mc","stem":"33 + 33 + 33을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"33 × 3","correct":true},{"t":"33 + 3","mis":"M3-1-u4-X01"},{"t":"3 × 3","mis":"M3-1-u4-X13"},{"t":"33 × 33","mis":"M3-1-u4-X13"}],"explanation":["같은 수 33을 3번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","33을 3번 → 33 × 3."],"variant_rule":{"alt":[{"stem":"11 + 11을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"11 × 2","correct":true},{"t":"11 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"11 × 11","mis":"M3-1-u4-X13"}],"explanation":["같은 수 11을 2번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","11을 2번 → 11 × 2."],"asset":null},{"stem":"41 + 41을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"41 × 2","correct":true},{"t":"41 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"41 × 41","mis":"M3-1-u4-X13"}],"explanation":["같은 수 41을 2번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","41을 2번 → 41 × 2."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#2','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C2',1,'mc','auto','1 × 6 = 6이에요. 그러면 10 × 6은 얼마인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X03','M3-1-u4-X11']::text[],true,'{"seq":2,"concept":"M3-1-u4-C2","difficulty":1,"kind":"mc","stem":"1 × 6 = 6이에요. 그러면 10 × 6은 얼마인가요?","options":[{"t":"60","correct":true},{"t":"6","mis":"M3-1-u4-X02"},{"t":"600","mis":"M3-1-u4-X03"},{"t":"70","mis":"M3-1-u4-X11"}],"explanation":["10은 1의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","6의 10배 — 10 × 6 = 60이에요."],"variant_rule":{"alt":[{"stem":"1 × 8 = 8이에요. 그러면 10 × 8은 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8","mis":"M3-1-u4-X02"},{"t":"800","mis":"M3-1-u4-X03"},{"t":"90","mis":"M3-1-u4-X11"}],"explanation":["10은 1의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","8의 10배 — 10 × 8 = 80이에요."],"asset":null},{"stem":"2 × 3 = 6이에요. 그러면 20 × 3은 얼마인가요?","options":[{"t":"60","correct":true},{"t":"6","mis":"M3-1-u4-X02"},{"t":"600","mis":"M3-1-u4-X03"},{"t":"70","mis":"M3-1-u4-X11"}],"explanation":["20은 2의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","6의 10배 — 20 × 3 = 60이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#3','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C2',1,'sa','auto','30 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C2","difficulty":1,"kind":"sa","stem":"30 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["3 × 2 = 6이에요.","30은 3의 10배라 곱도 10배예요.","30 × 2 = 60이에요."],"variant_rule":{"alt":[{"stem":"20 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["2 × 3 = 6이에요.","20은 2의 10배라 곱도 10배예요.","20 × 3 = 60이에요."],"asset":null},{"stem":"10 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["1 × 7 = 7이에요.","10은 1의 10배라 곱도 10배예요.","10 × 7 = 70이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#4','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C3',1,'sa','auto','21 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"21 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["21을 20과 1로 나누어 곱해요: 20 × 2 = 40, 1 × 2 = 2.","일의 자리 1 × 2 = 2, 십의 자리 2 × 2 = 4(십)이에요.","40 + 2 = 42 — 42는 어림한 20 × 2 = 40과 가까워요."],"variant_rule":{"alt":[{"stem":"23 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["69"],"explanation":["23을 20과 3으로 나누어 곱해요: 20 × 3 = 60, 3 × 3 = 9.","일의 자리 3 × 3 = 9, 십의 자리 2 × 3 = 6(십)이에요.","60 + 9 = 69 — 69는 어림한 20 × 3 = 60과 가까워요."],"asset":null},{"stem":"11 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["11을 10과 1로 나누어 곱해요: 10 × 4 = 40, 1 × 4 = 4.","일의 자리 1 × 4 = 4, 십의 자리 1 × 4 = 4(십)이에요.","40 + 4 = 44 — 44는 어림한 10 × 4 = 40과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#5','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C3',1,'sa','auto','23 × 3을 20과 3으로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"23 × 3을 20과 3으로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["20 × 3 = 60.","□는 3 × 3 = 9예요.","60 + 9 = 69 — 23 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["20 × 3","=","60"],["3 × 3","=",null],["60 + □","=","69"]]},"variant_rule":{"alt":[{"stem":"11 × 9를 10과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["10 × 9 = 90.","□는 1 × 9 = 9예요.","90 + 9 = 99 — 11 × 9의 곱이에요."],"asset":{"type":"expr_grid","rows":[["10 × 9","=","90"],["1 × 9","=",null],["90 + □","=","99"]]}},{"stem":"22 × 4를 20과 2로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["20 × 4 = 80.","□는 2 × 4 = 8이에요.","80 + 8 = 88 — 22 × 4의 곱이에요."],"asset":{"type":"expr_grid","rows":[["20 × 4","=","80"],["2 × 4","=",null],["80 + □","=","88"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#6','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C4',1,'mc','auto','11 × 7을 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":6,"concept":"M3-1-u4-C4","difficulty":1,"kind":"mc","stem":"11 × 7을 어림하면 약 얼마인가요?","options":[{"t":"약 70","correct":true},{"t":"약 140","mis":"M3-1-u4-X12"},{"t":"약 10","mis":"M3-1-u4-X12"},{"t":"약 80","mis":"M3-1-u4-X11"}],"explanation":["11은 가까운 몇십 10으로 어림해요.","10 × 7 = 70이에요.","그래서 11 × 7은 약 70이에요 — 실제 곱 77과 가까워요."],"variant_rule":{"alt":[{"stem":"32 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 60","correct":true},{"t":"약 80","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X12"},{"t":"약 90","mis":"M3-1-u4-X11"}],"explanation":["32는 가까운 몇십 30으로 어림해요.","30 × 2 = 60이에요.","그래서 32 × 2는 약 60이에요 — 실제 곱 64와 가까워요."],"asset":null},{"stem":"12 × 4를 어림하면 약 얼마인가요?","options":[{"t":"약 40","correct":true},{"t":"약 80","mis":"M3-1-u4-X12"},{"t":"약 10","mis":"M3-1-u4-X12"},{"t":"약 50","mis":"M3-1-u4-X11"}],"explanation":["12는 가까운 몇십 10으로 어림해요.","10 × 4 = 40이에요.","그래서 12 × 4는 약 40이에요 — 실제 곱 48과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#7','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C5',1,'mc','auto','53 × 3은 얼마인가요?',ARRAY['M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":7,"concept":"M3-1-u4-C5","difficulty":1,"kind":"mc","stem":"53 × 3은 얼마인가요?","options":[{"t":"159","correct":true},{"t":"59","mis":"M3-1-u4-X07"},{"t":"150","mis":"M3-1-u4-X06"},{"t":"9","mis":"M3-1-u4-X06"}],"explanation":["53을 50과 3으로 나누어 곱해요: 50 × 3 = 150, 3 × 3 = 9.","십의 자리 곱 50 × 3 = 150 — 백의 자리로 올림해요.","150 + 9 = 159 — 159는 어림한 50 × 3 = 150과 가까워요."],"variant_rule":{"alt":[{"stem":"51 × 2는 얼마인가요?","options":[{"t":"102","correct":true},{"t":"2","mis":"M3-1-u4-X07"},{"t":"100","mis":"M3-1-u4-X06"},{"t":"52","mis":"M3-1-u4-X04"}],"explanation":["51을 50과 1로 나누어 곱해요: 50 × 2 = 100, 1 × 2 = 2.","십의 자리 곱 50 × 2 = 100 — 백의 자리로 올림해요.","100 + 2 = 102 — 102는 어림한 50 × 2 = 100과 가까워요."],"asset":null},{"stem":"71 × 3은 얼마인가요?","options":[{"t":"213","correct":true},{"t":"13","mis":"M3-1-u4-X07"},{"t":"210","mis":"M3-1-u4-X06"},{"t":"3","mis":"M3-1-u4-X06"}],"explanation":["71을 70과 1로 나누어 곱해요: 70 × 3 = 210, 1 × 3 = 3.","십의 자리 곱 70 × 3 = 210 — 백의 자리로 올림해요.","210 + 3 = 213 — 213은 어림한 70 × 3 = 210과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#8','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C6',1,'sa','auto','28 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u4-C6","difficulty":1,"kind":"sa","stem":"28 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["28을 20과 8로 나누어 곱해요: 20 × 3 = 60, 8 × 3 = 24.","일의 자리 곱 8 × 3 = 24 — 2를 십의 자리로 올림해 더해요.","60 + 24 = 84 — 84는 어림한 30 × 3 = 90과 가까워요."],"variant_rule":{"alt":[{"stem":"12 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["12를 10과 2로 나누어 곱해요: 10 × 7 = 70, 2 × 7 = 14.","일의 자리 곱 2 × 7 = 14 — 1을 십의 자리로 올림해 더해요.","70 + 14 = 84 — 84는 어림한 10 × 7 = 70과 가까워요."],"asset":null},{"stem":"17 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["51"],"explanation":["17을 10과 7로 나누어 곱해요: 10 × 3 = 30, 7 × 3 = 21.","일의 자리 곱 7 × 3 = 21 — 2를 십의 자리로 올림해 더해요.","30 + 21 = 51 — 51은 어림한 20 × 3 = 60과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#9','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C1',2,'mc','auto','생수가 한 묶음에 26병씩 9묶음 있어요. 생수는 모두 몇 병인지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":9,"concept":"M3-1-u4-C1","difficulty":2,"kind":"mc","stem":"생수가 한 묶음에 26병씩 9묶음 있어요. 생수는 모두 몇 병인지 구하는 식은 어느 것인가요?","options":[{"t":"26 × 9","correct":true},{"t":"26 + 9","mis":"M3-1-u4-X01"},{"t":"9 × 9","mis":"M3-1-u4-X13"},{"t":"26 × 26","mis":"M3-1-u4-X13"}],"explanation":["26병씩 9번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 26 × 9."],"variant_rule":{"alt":[{"stem":"걷기 운동을 하루에 24분씩 5일 동안 했어요. 모두 몇 분 걸었는지 구하는 식은 어느 것인가요?","options":[{"t":"24 × 5","correct":true},{"t":"24 + 5","mis":"M3-1-u4-X01"},{"t":"5 × 5","mis":"M3-1-u4-X13"},{"t":"24 × 24","mis":"M3-1-u4-X13"}],"explanation":["24분씩 5번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 24 × 5."],"asset":null},{"stem":"계단 오르기를 하루에 48칸씩 3일 동안 했어요. 모두 몇 칸 올랐는지 구하는 식은 어느 것인가요?","options":[{"t":"48 × 3","correct":true},{"t":"48 + 3","mis":"M3-1-u4-X01"},{"t":"3 × 3","mis":"M3-1-u4-X13"},{"t":"48 × 48","mis":"M3-1-u4-X13"}],"explanation":["48칸씩 3번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 48 × 3."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#10','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C2',2,'ox','auto','30 × 9 = 27이에요.',ARRAY['M3-1-u4-X02']::text[],true,'{"seq":10,"concept":"M3-1-u4-C2","difficulty":2,"kind":"ox","stem":"30 × 9 = 27이에요.","answer":"X","reason_options":[{"t":"30 × 9는 3 × 9의 10배라서","correct":true},{"t":"3 × 9 = 27이니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"mis":"M3-1-u4-X02","explanation":["3 × 9 = 27이에요.","30은 3의 10배라 곱도 10배 — 270이에요.","0을 빠뜨리면 십 모형 27개를 낱개 27개로 센 셈이에요."],"variant_rule":{"alt":[{"stem":"90 × 2 = 18이에요.","answer":"X","reason_options":[{"t":"90 × 2는 9 × 2의 10배라서","correct":true},{"t":"9 × 2 = 18이니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["9 × 2 = 18이에요.","90은 9의 10배라 곱도 10배 — 180이에요.","0을 빠뜨리면 십 모형 18개를 낱개 18개로 센 셈이에요."],"asset":null},{"stem":"50 × 4 = 20이에요.","answer":"X","reason_options":[{"t":"50 × 4는 5 × 4의 10배라서","correct":true},{"t":"5 × 4 = 20이니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["5 × 4 = 20이에요.","50은 5의 10배라 곱도 10배 — 200이에요.","0을 빠뜨리면 십 모형 20개를 낱개 20개로 센 셈이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#11','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C3',2,'sa','auto','31 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-1-u4-C3","difficulty":2,"kind":"sa","stem":"31 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 3 × 2 = 6 → 6을 써요.","31 × 2 = 62 — 십의 자리 숫자는 6이에요."],"asset":{"type":"expr_grid","rows":[["","","3","1"],["×","","","2"],["","",null,"2"]]},"variant_rule":{"alt":[{"stem":"23 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 3 × 2 = 6 → 6을 써요.","23 × 2 = 46 — 일의 자리 숫자는 6이에요."],"asset":{"type":"expr_grid","rows":[["","","2","3"],["×","","","2"],["","","4",null]]}},{"stem":"21 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 2 × 2 = 4 → 4를 써요.","21 × 2 = 42 — 십의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["","","2","1"],["×","","","2"],["","",null,"2"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#12','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C4',2,'mc','auto','27 × 8을 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":12,"concept":"M3-1-u4-C4","difficulty":2,"kind":"mc","stem":"27 × 8을 어림하면 약 얼마인가요?","options":[{"t":"약 240","correct":true},{"t":"약 160","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X12"},{"t":"약 270","mis":"M3-1-u4-X11"}],"explanation":["27은 가까운 몇십 30으로 어림해요.","30 × 8 = 240이에요.","그래서 27 × 8은 약 240이에요 — 실제 곱 216과 가까워요."],"variant_rule":{"alt":[{"stem":"27 × 5를 어림하면 약 얼마인가요?","options":[{"t":"약 150","correct":true},{"t":"약 100","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X12"},{"t":"약 180","mis":"M3-1-u4-X11"}],"explanation":["27은 가까운 몇십 30으로 어림해요.","30 × 5 = 150이에요.","그래서 27 × 5는 약 150이에요 — 실제 곱 135와 가까워요."],"asset":null},{"stem":"64 × 6을 어림하면 약 얼마인가요?","options":[{"t":"약 360","correct":true},{"t":"약 420","mis":"M3-1-u4-X12"},{"t":"약 60","mis":"M3-1-u4-X12"},{"t":"약 300","mis":"M3-1-u4-X11"}],"explanation":["64는 가까운 몇십 60으로 어림해요.","60 × 6 = 360이에요.","그래서 64 × 6은 약 360이에요 — 실제 곱 384와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#13','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C5',2,'sa','auto','61 × 3의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-1-u4-C5","difficulty":2,"kind":"sa","stem":"61 × 3의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["십의 자리 곱 6 × 3 = 18이에요.","10을 넘은 1이 백의 자리로 올림해요.","61 × 3 = 183 — 백의 자리 숫자는 1이에요."],"variant_rule":{"alt":[{"stem":"41 × 5의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["십의 자리 곱 4 × 5 = 20이에요.","10을 넘은 2가 백의 자리로 올림해요.","41 × 5 = 205 — 백의 자리 숫자는 2예요."],"asset":null},{"stem":"81 × 2의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["십의 자리 곱 8 × 2 = 16이에요.","10을 넘은 1이 백의 자리로 올림해요.","81 × 2 = 162 — 백의 자리 숫자는 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#14','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C6',2,'sa','auto','16 × 2를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u4-C6","difficulty":2,"kind":"sa","stem":"16 × 2를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리 6 × 2 = 12예요.","일의 자리에 2를 쓰고 1을 십의 자리로 올림해요.","십의 자리 1 × 2 = 2에 1을 더해 3이에요."],"asset":{"type":"expr_grid","rows":[["","","1","6"],["×","","","2"],["","",null,null]]},"variant_rule":{"alt":[{"stem":"14 × 6을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리 4 × 6 = 24예요.","일의 자리에 4를 쓰고 2를 십의 자리로 올림해요.","십의 자리 1 × 6 = 6에 2를 더해 8이에요."],"asset":{"type":"expr_grid","rows":[["","","1","4"],["×","","","6"],["","",null,null]]}},{"stem":"29 × 2를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리 9 × 2 = 18이에요.","일의 자리에 8을 쓰고 1을 십의 자리로 올림해요.","십의 자리 2 × 2 = 4에 1을 더해 5예요."],"asset":{"type":"expr_grid","rows":[["","","2","9"],["×","","","2"],["","",null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#15','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C7',2,'mc','auto','64 × 7은 얼마인가요?',ARRAY['M3-1-u4-X08','M3-1-u4-X07','M3-1-u4-X09']::text[],true,'{"seq":15,"concept":"M3-1-u4-C7","difficulty":2,"kind":"mc","stem":"64 × 7은 얼마인가요?","options":[{"t":"448","correct":true},{"t":"428","mis":"M3-1-u4-X08"},{"t":"48","mis":"M3-1-u4-X07"},{"t":"568","mis":"M3-1-u4-X09"}],"explanation":["64를 60과 4로 나누어 곱해요: 60 × 7 = 420, 4 × 7 = 28.","일의 자리 28 → 2 올림, 십의 자리 6 × 7 + 2 = 44 — 백의 자리까지 올림해요.","420 + 28 = 448 — 448은 어림한 60 × 7 = 420과 가까워요."],"variant_rule":{"alt":[{"stem":"44 × 7은 얼마인가요?","options":[{"t":"308","correct":true},{"t":"288","mis":"M3-1-u4-X08"},{"t":"8","mis":"M3-1-u4-X07"},{"t":"428","mis":"M3-1-u4-X09"}],"explanation":["44를 40과 4로 나누어 곱해요: 40 × 7 = 280, 4 × 7 = 28.","일의 자리 28 → 2 올림, 십의 자리 4 × 7 + 2 = 30 — 백의 자리까지 올림해요.","280 + 28 = 308 — 308은 어림한 40 × 7 = 280과 가까워요."],"asset":null},{"stem":"89 × 8은 얼마인가요?","options":[{"t":"712","correct":true},{"t":"642","mis":"M3-1-u4-X08"},{"t":"12","mis":"M3-1-u4-X07"},{"t":"1202","mis":"M3-1-u4-X09"}],"explanation":["89를 80과 9로 나누어 곱해요: 80 × 8 = 640, 9 × 8 = 72.","일의 자리 72 → 7 올림, 십의 자리 8 × 8 + 7 = 71 — 백의 자리까지 올림해요.","640 + 72 = 712 — 712는 어림한 90 × 8 = 720과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#16','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C8',2,'sa','auto','열쇠고리를 만들어요. 바람개비 날개 한 장에 비즈가 28개씩 들어가요. 바람개비 날개 3장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-1-u4-C8","difficulty":2,"kind":"sa","stem":"열쇠고리를 만들어요. 바람개비 날개 한 장에 비즈가 28개씩 들어가요. 바람개비 날개 3장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["84"],"explanation":["같은 모양이 3장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 28개 × 3장 = 28 × 3.","28 × 3 = 84 — 비즈 84개가 필요해요."],"variant_rule":{"alt":[{"stem":"열쇠고리를 만들어요. 꽃잎 한 장에 비즈가 26개씩 들어가요. 꽃잎 2장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["52"],"explanation":["같은 모양이 2장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 26개 × 2장 = 26 × 2.","26 × 2 = 52 — 비즈 52개가 필요해요."],"asset":null},{"stem":"열쇠고리를 만들어요. 나비 날개 한 장에 비즈가 18개씩 들어가요. 나비 날개 4장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["72"],"explanation":["같은 모양이 4장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 18개 × 4장 = 18 × 4.","18 × 4 = 72 — 비즈 72개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#17','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C2',3,'error','auto','10 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X15']::text[],true,'{"seq":17,"concept":"M3-1-u4-C2","difficulty":3,"kind":"error","stem":"10 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「10 × 4 = 4야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"은우 — 「1 × 4 = 4의 10배야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「십 모형 1개씩 4묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["1 × 4 = 4의 10배예요.","10 × 4 = 40이에요.","하린은 0을 빠뜨려 4라고 말했어요."],"variant_rule":{"alt":[{"stem":"80 × 9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「80 × 9 = 72야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"하랑 — 「8 × 9 = 72의 10배야」","mis":"M3-1-u4-X15"},{"t":"지유 — 「십 모형 8개씩 9묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["8 × 9 = 72의 10배예요.","80 × 9 = 720이에요.","도윤은 0을 빠뜨려 72라고 말했어요."],"asset":null},{"stem":"90 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「90 × 3 = 27이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"지유 — 「9 × 3 = 27의 10배야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「십 모형 9개씩 3묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["9 × 3 = 27의 10배예요.","90 × 3 = 270이에요.","도윤은 0을 빠뜨려 27이라고 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#18','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C3',3,'error','auto','42 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X04','M3-1-u4-X15']::text[],true,'{"seq":18,"concept":"M3-1-u4-C3","difficulty":3,"kind":"error","stem":"42 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「42 × 2 = 44야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"서윤 — 「42 × 2 = 84야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「40 × 2 = 80, 2 × 2 = 4, 더하면 84야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 2 × 2 = 4, 십의 자리 4 × 2 = 8(십)이에요.","42 × 2 = 84예요.","하린은 44로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"22 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「22 × 2 = 24야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"서윤 — 「22 × 2 = 44야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「어림하면 약 40이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 2 × 2 = 4, 십의 자리 2 × 2 = 4(십)이에요.","22 × 2 = 44예요.","태오는 24로 잘못 구했어요."],"asset":null},{"stem":"11 × 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「11 × 6 = 16이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"태오 — 「11 × 6 = 66이야」","mis":"M3-1-u4-X15"},{"t":"지유 — 「10 × 6 = 60, 1 × 6 = 6, 더하면 66이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 1 × 6 = 6, 십의 자리 1 × 6 = 6(십)이에요.","11 × 6 = 66이에요.","서윤은 16으로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#19','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C4',3,'ox','auto','81 × 2를 계산했더니 62가 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-1-u4-X12']::text[],true,'{"seq":19,"concept":"M3-1-u4-C4","difficulty":3,"kind":"ox","stem":"81 × 2를 계산했더니 62가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 160과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"mis":"M3-1-u4-X12","explanation":["81을 80으로 어림하면 약 160이에요.","62는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 81 × 2 = 162예요."],"variant_rule":{"alt":[{"stem":"61 × 4를 계산했더니 44가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 240과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["61을 60으로 어림하면 약 240이에요.","44는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 61 × 4 = 244예요."],"asset":null},{"stem":"41 × 3을 계산했더니 23이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 120과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["41을 40으로 어림하면 약 120이에요.","23은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 41 × 3 = 123이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#20','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C5',3,'mc','auto','계단 오르기를 하루에 52칸씩 3일 동안 했어요. 모두 몇 칸 올랐나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":20,"concept":"M3-1-u4-C5","difficulty":3,"kind":"mc","stem":"계단 오르기를 하루에 52칸씩 3일 동안 했어요. 모두 몇 칸 올랐나요?","options":[{"t":"156칸","correct":true},{"t":"55칸","mis":"M3-1-u4-X01"},{"t":"56칸","mis":"M3-1-u4-X07"},{"t":"150칸","mis":"M3-1-u4-X06"}],"explanation":["52칸씩 3번(묶음) — 곱셈식 52 × 3으로 세워요.","십의 자리 곱 50 × 3 = 150 — 백의 자리로 올림해요.","52 × 3 = 156 — 모두 156칸이에요."],"variant_rule":{"alt":[{"stem":"훌라후프를 한 번에 32바퀴씩 4번 돌렸어요. 모두 몇 바퀴 돌렸나요?","options":[{"t":"128바퀴","correct":true},{"t":"36바퀴","mis":"M3-1-u4-X01"},{"t":"28바퀴","mis":"M3-1-u4-X07"},{"t":"120바퀴","mis":"M3-1-u4-X06"}],"explanation":["32바퀴씩 4번(묶음) — 곱셈식 32 × 4로 세워요.","십의 자리 곱 30 × 4 = 120 — 백의 자리로 올림해요.","32 × 4 = 128 — 모두 128바퀴예요."],"asset":null},{"stem":"색종이를 한 명에게 73장씩 3명에게 나누어 주었어요. 모두 몇 장인가요?","options":[{"t":"219장","correct":true},{"t":"76장","mis":"M3-1-u4-X01"},{"t":"19장","mis":"M3-1-u4-X07"},{"t":"210장","mis":"M3-1-u4-X06"}],"explanation":["73장씩 3번(묶음) — 곱셈식 73 × 3으로 세워요.","십의 자리 곱 70 × 3 = 210 — 백의 자리로 올림해요.","73 × 3 = 219 — 모두 219장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#21','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C6',3,'error','auto','18 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u4-X09','M3-1-u4-X15']::text[],true,'{"seq":21,"concept":"M3-1-u4-C6","difficulty":3,"kind":"error","stem":"18 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"지유 — 「올림한 1을 십의 자리 1에 먼저 더해 2 × 2 — 답은 46이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"도윤 — 「1 × 2 = 2에 올림한 1을 더해 3 — 답은 36이야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「10 × 2 = 20, 8 × 2 = 16, 더하면 36이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 2 = 2, + 1 = 3 — 18 × 2 = 36이에요.","지유는 먼저 더하고 곱해 46이 나왔어요."],"variant_rule":{"alt":[{"stem":"19 × 3을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하랑 — 「올림한 2를 십의 자리 1에 먼저 더해 3 × 3 — 답은 97이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"도윤 — 「1 × 3 = 3에 올림한 2를 더해 5 — 답은 57이야」","mis":"M3-1-u4-X15"},{"t":"지유 — 「10 × 3 = 30, 9 × 3 = 27, 더하면 57이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 3 = 3, + 2 = 5 — 19 × 3 = 57이에요.","하랑은 먼저 더하고 곱해 97이 나왔어요."],"asset":null},{"stem":"28 × 3을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"지유 — 「올림한 2를 십의 자리 2에 먼저 더해 4 × 3 — 답은 124야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"도윤 — 「2 × 3 = 6에 올림한 2를 더해 8 — 답은 84야」","mis":"M3-1-u4-X15"},{"t":"하린 — 「20 × 3 = 60, 8 × 3 = 24, 더하면 84야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","2 × 3 = 6, + 2 = 8 — 28 × 3 = 84예요.","지유는 먼저 더하고 곱해 124가 나왔어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#22','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C7',3,'mc','auto','걷기 운동을 하루에 64분씩 4일 동안 했어요. 모두 몇 분 걸었나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X08','M3-1-u4-X07']::text[],true,'{"seq":22,"concept":"M3-1-u4-C7","difficulty":3,"kind":"mc","stem":"걷기 운동을 하루에 64분씩 4일 동안 했어요. 모두 몇 분 걸었나요?","options":[{"t":"256분","correct":true},{"t":"68분","mis":"M3-1-u4-X01"},{"t":"246분","mis":"M3-1-u4-X08"},{"t":"56분","mis":"M3-1-u4-X07"}],"explanation":["64분씩 4번(묶음) — 곱셈식 64 × 4로 세워요.","일의 자리 16 → 1 올림, 십의 자리 6 × 4 + 1 = 25 — 백의 자리까지 올림해요.","64 × 4 = 256 — 모두 256분이에요."],"variant_rule":{"alt":[{"stem":"길이가 52cm인 골판지 8개를 겹치지 않게 이었어요. 모두 몇 cm인가요?","options":[{"t":"416cm","correct":true},{"t":"60cm","mis":"M3-1-u4-X01"},{"t":"406cm","mis":"M3-1-u4-X08"},{"t":"16cm","mis":"M3-1-u4-X07"}],"explanation":["52cm씩 8번(묶음) — 곱셈식 52 × 8로 세워요.","일의 자리 16 → 1 올림, 십의 자리 5 × 8 + 1 = 41 — 백의 자리까지 올림해요.","52 × 8 = 416 — 모두 416cm예요."],"asset":null},{"stem":"훌라후프를 한 번에 24바퀴씩 7번 돌렸어요. 모두 몇 바퀴 돌렸나요?","options":[{"t":"168바퀴","correct":true},{"t":"31바퀴","mis":"M3-1-u4-X01"},{"t":"148바퀴","mis":"M3-1-u4-X08"},{"t":"68바퀴","mis":"M3-1-u4-X07"}],"explanation":["24바퀴씩 7번(묶음) — 곱셈식 24 × 7로 세워요.","일의 자리 28 → 2 올림, 십의 자리 2 × 7 + 2 = 16 — 백의 자리까지 올림해요.","24 × 7 = 168 — 모두 168바퀴예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#23','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C8',4,'mc','auto','나비 날개 한 장의 비즈는 6개씩 7줄과 8개씩 2줄이에요. 날개 3장을 만들려면 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X14','M3-1-u4-X01']::text[],true,'{"seq":23,"concept":"M3-1-u4-C8","difficulty":4,"kind":"mc","stem":"나비 날개 한 장의 비즈는 6개씩 7줄과 8개씩 2줄이에요. 날개 3장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"174개","correct":true},{"t":"126개","mis":"M3-1-u4-X14"},{"t":"48개","mis":"M3-1-u4-X14"},{"t":"61개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 6 × 7 + 8 × 2 = 42 + 16 = 58개.","날개 3장: 58 × 3.","58 × 3 = 174 — 비즈 174개가 필요해요."],"variant_rule":{"alt":[{"stem":"나비 날개 한 장의 비즈는 9개씩 5줄과 7개씩 3줄이에요. 날개 2장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"132개","correct":true},{"t":"90개","mis":"M3-1-u4-X14"},{"t":"42개","mis":"M3-1-u4-X14"},{"t":"68개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 9 × 5 + 7 × 3 = 45 + 21 = 66개.","날개 2장: 66 × 2.","66 × 2 = 132 — 비즈 132개가 필요해요."],"asset":null},{"stem":"나비 날개 한 장의 비즈는 8개씩 6줄과 7개씩 2줄이에요. 날개 4장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"248개","correct":true},{"t":"192개","mis":"M3-1-u4-X14"},{"t":"56개","mis":"M3-1-u4-X14"},{"t":"66개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 8 × 6 + 7 × 2 = 48 + 14 = 62개.","날개 4장: 62 × 4.","62 × 4 = 248 — 비즈 248개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#24','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C7',4,'mc','auto','곱이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u4-X11','M3-1-u4-X15']::text[],true,'{"seq":24,"concept":"M3-1-u4-C7","difficulty":4,"kind":"mc","stem":"곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"72 × 8","correct":true},{"t":"62 × 7","mis":"M3-1-u4-X11"},{"t":"99 × 4","mis":"M3-1-u4-X15"},{"t":"32 × 5","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","72 × 8 = 576, 62 × 7 = 434, 99 × 4 = 396, 32 × 5 = 160.","곱이 가장 큰 것은 72 × 8 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"82 × 6","correct":true},{"t":"22 × 7","mis":"M3-1-u4-X11"},{"t":"84 × 5","mis":"M3-1-u4-X15"},{"t":"62 × 7","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","82 × 6 = 492, 22 × 7 = 154, 84 × 5 = 420, 62 × 7 = 434.","곱이 가장 큰 것은 82 × 6 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"54 × 9","correct":true},{"t":"64 × 3","mis":"M3-1-u4-X11"},{"t":"66 × 5","mis":"M3-1-u4-X15"},{"t":"46 × 9","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","54 × 9 = 486, 64 × 3 = 192, 66 × 5 = 330, 46 × 9 = 414.","곱이 가장 큰 것은 54 × 9 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_c#25','math',3,1,'u4','','g3_1_math_u4_review_c','unit_review','M3-1-u4-C8',4,'essay','teacher','바람개비 한 개의 날개 비즈는 60개, 손잡이 비즈는 24개예요. 바람개비 7개에 들어가는 비즈는 모두 몇 개인지 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u4-C8","difficulty":4,"kind":"essay","stem":"바람개비 한 개의 날개 비즈는 60개, 손잡이 비즈는 24개예요. 바람개비 7개에 들어가는 비즈는 모두 몇 개인지 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 날개 비즈 60 × 7 = 420개, 손잡이 비즈 24 × 7 = 168개(20 × 7 = 140, 4 × 7 = 28). 모두 420 + 168 = 588개이다. (또는 한 개 84개 × 7 = 588개)","scoring_points":["60 × 7 = 420을 구했는가","24 × 7 = 168을 구했는가","모두 588개를 구했는가"]},"explanation":["날개 60 × 7 = 420.","손잡이 24 × 7 = 168.","420 + 168 = 588개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#1','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C1',1,'mc','auto','22 + 22 + 22 + 22를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":1,"concept":"M3-1-u4-C1","difficulty":1,"kind":"mc","stem":"22 + 22 + 22 + 22를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"22 × 4","correct":true},{"t":"22 + 4","mis":"M3-1-u4-X01"},{"t":"4 × 4","mis":"M3-1-u4-X13"},{"t":"22 × 22","mis":"M3-1-u4-X13"}],"explanation":["같은 수 22를 4번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","22를 4번 → 22 × 4."],"variant_rule":{"alt":[{"stem":"42 + 42를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"42 × 2","correct":true},{"t":"42 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"42 × 42","mis":"M3-1-u4-X13"}],"explanation":["같은 수 42를 2번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","42를 2번 → 42 × 2."],"asset":null},{"stem":"21 + 21을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"21 × 2","correct":true},{"t":"21 + 2","mis":"M3-1-u4-X01"},{"t":"2 × 2","mis":"M3-1-u4-X13"},{"t":"21 × 21","mis":"M3-1-u4-X13"}],"explanation":["같은 수 21을 2번 더했어요.","같은 수를 여러 번 더하면 곱셈으로 간단히 나타내요.","21을 2번 → 21 × 2."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#2','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C2',1,'mc','auto','1 × 9 = 9예요. 그러면 10 × 9는 얼마인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X03','M3-1-u4-X11']::text[],true,'{"seq":2,"concept":"M3-1-u4-C2","difficulty":1,"kind":"mc","stem":"1 × 9 = 9예요. 그러면 10 × 9는 얼마인가요?","options":[{"t":"90","correct":true},{"t":"9","mis":"M3-1-u4-X02"},{"t":"900","mis":"M3-1-u4-X03"},{"t":"100","mis":"M3-1-u4-X11"}],"explanation":["10은 1의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","9의 10배 — 10 × 9 = 90이에요."],"variant_rule":{"alt":[{"stem":"1 × 4 = 4예요. 그러면 10 × 4는 얼마인가요?","options":[{"t":"40","correct":true},{"t":"4","mis":"M3-1-u4-X02"},{"t":"400","mis":"M3-1-u4-X03"},{"t":"50","mis":"M3-1-u4-X11"}],"explanation":["10은 1의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","4의 10배 — 10 × 4 = 40이에요."],"asset":null},{"stem":"3 × 3 = 9예요. 그러면 30 × 3은 얼마인가요?","options":[{"t":"90","correct":true},{"t":"9","mis":"M3-1-u4-X02"},{"t":"900","mis":"M3-1-u4-X03"},{"t":"100","mis":"M3-1-u4-X11"}],"explanation":["30은 3의 10배예요.","곱해지는 수가 10배가 되면 곱도 10배가 돼요.","9의 10배 — 30 × 3 = 90이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#3','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C2',1,'sa','auto','20 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u4-C2","difficulty":1,"kind":"sa","stem":"20 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["2 × 2 = 4예요.","20은 2의 10배라 곱도 10배예요.","20 × 2 = 40이에요."],"variant_rule":{"alt":[{"stem":"20 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["2 × 3 = 6이에요.","20은 2의 10배라 곱도 10배예요.","20 × 3 = 60이에요."],"asset":null},{"stem":"20 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["2 × 4 = 8이에요.","20은 2의 10배라 곱도 10배예요.","20 × 4 = 80이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#4','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C3',1,'sa','auto','21 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"21 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["21을 20과 1로 나누어 곱해요: 20 × 2 = 40, 1 × 2 = 2.","일의 자리 1 × 2 = 2, 십의 자리 2 × 2 = 4(십)이에요.","40 + 2 = 42 — 42는 어림한 20 × 2 = 40과 가까워요."],"variant_rule":{"alt":[{"stem":"33 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["99"],"explanation":["33을 30과 3으로 나누어 곱해요: 30 × 3 = 90, 3 × 3 = 9.","일의 자리 3 × 3 = 9, 십의 자리 3 × 3 = 9(십)이에요.","90 + 9 = 99 — 99는 어림한 30 × 3 = 90과 가까워요."],"asset":null},{"stem":"13 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["13을 10과 3으로 나누어 곱해요: 10 × 3 = 30, 3 × 3 = 9.","일의 자리 3 × 3 = 9, 십의 자리 1 × 3 = 3(십)이에요.","30 + 9 = 39 — 39는 어림한 10 × 3 = 30과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#5','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C3',1,'sa','auto','31 × 3을 30과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u4-C3","difficulty":1,"kind":"sa","stem":"31 × 3을 30과 1로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["30 × 3 = 90.","□는 1 × 3 = 3이에요.","90 + 3 = 93 — 31 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["30 × 3","=","90"],["1 × 3","=",null],["90 + □","=","93"]]},"variant_rule":{"alt":[{"stem":"22 × 3을 20과 2로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["20 × 3 = 60.","□는 2 × 3 = 6이에요.","60 + 6 = 66 — 22 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["20 × 3","=","60"],["2 × 3","=",null],["60 + □","=","66"]]}},{"stem":"22 × 4를 20과 2로 나누어 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["20 × 4 = 80.","□는 2 × 4 = 8이에요.","80 + 8 = 88 — 22 × 4의 곱이에요."],"asset":{"type":"expr_grid","rows":[["20 × 4","=","80"],["2 × 4","=",null],["80 + □","=","88"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#6','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C4',1,'mc','auto','34 × 2를 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":6,"concept":"M3-1-u4-C4","difficulty":1,"kind":"mc","stem":"34 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 60","correct":true},{"t":"약 80","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X12"},{"t":"약 90","mis":"M3-1-u4-X11"}],"explanation":["34는 가까운 몇십 30으로 어림해요.","30 × 2 = 60이에요.","그래서 34 × 2는 약 60이에요 — 실제 곱 68과 가까워요."],"variant_rule":{"alt":[{"stem":"12 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 20","correct":true},{"t":"약 40","mis":"M3-1-u4-X12"},{"t":"약 10","mis":"M3-1-u4-X12"},{"t":"약 30","mis":"M3-1-u4-X11"}],"explanation":["12는 가까운 몇십 10으로 어림해요.","10 × 2 = 20이에요.","그래서 12 × 2는 약 20이에요 — 실제 곱 24와 가까워요."],"asset":null},{"stem":"21 × 4를 어림하면 약 얼마인가요?","options":[{"t":"약 80","correct":true},{"t":"약 120","mis":"M3-1-u4-X12"},{"t":"약 20","mis":"M3-1-u4-X12"},{"t":"약 100","mis":"M3-1-u4-X11"}],"explanation":["21은 가까운 몇십 20으로 어림해요.","20 × 4 = 80이에요.","그래서 21 × 4는 약 80이에요 — 실제 곱 84와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#7','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C5',1,'mc','auto','84 × 2는 얼마인가요?',ARRAY['M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":7,"concept":"M3-1-u4-C5","difficulty":1,"kind":"mc","stem":"84 × 2는 얼마인가요?","options":[{"t":"168","correct":true},{"t":"68","mis":"M3-1-u4-X07"},{"t":"160","mis":"M3-1-u4-X06"},{"t":"8","mis":"M3-1-u4-X06"}],"explanation":["84를 80과 4로 나누어 곱해요: 80 × 2 = 160, 4 × 2 = 8.","십의 자리 곱 80 × 2 = 160 — 백의 자리로 올림해요.","160 + 8 = 168 — 168은 어림한 80 × 2 = 160과 가까워요."],"variant_rule":{"alt":[{"stem":"81 × 6은 얼마인가요?","options":[{"t":"486","correct":true},{"t":"86","mis":"M3-1-u4-X07"},{"t":"480","mis":"M3-1-u4-X06"},{"t":"6","mis":"M3-1-u4-X06"}],"explanation":["81을 80과 1로 나누어 곱해요: 80 × 6 = 480, 1 × 6 = 6.","십의 자리 곱 80 × 6 = 480 — 백의 자리로 올림해요.","480 + 6 = 486 — 486은 어림한 80 × 6 = 480과 가까워요."],"asset":null},{"stem":"61 × 3은 얼마인가요?","options":[{"t":"183","correct":true},{"t":"83","mis":"M3-1-u4-X07"},{"t":"180","mis":"M3-1-u4-X06"},{"t":"3","mis":"M3-1-u4-X06"}],"explanation":["61을 60과 1로 나누어 곱해요: 60 × 3 = 180, 1 × 3 = 3.","십의 자리 곱 60 × 3 = 180 — 백의 자리로 올림해요.","180 + 3 = 183 — 183은 어림한 60 × 3 = 180과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#8','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C6',1,'sa','auto','28 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u4-C6","difficulty":1,"kind":"sa","stem":"28 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["28을 20과 8로 나누어 곱해요: 20 × 2 = 40, 8 × 2 = 16.","일의 자리 곱 8 × 2 = 16 — 1을 십의 자리로 올림해 더해요.","40 + 16 = 56 — 56은 어림한 30 × 2 = 60과 가까워요."],"variant_rule":{"alt":[{"stem":"13 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["91"],"explanation":["13을 10과 3으로 나누어 곱해요: 10 × 7 = 70, 3 × 7 = 21.","일의 자리 곱 3 × 7 = 21 — 2를 십의 자리로 올림해 더해요.","70 + 21 = 91 — 91은 어림한 10 × 7 = 70과 가까워요."],"asset":null},{"stem":"14 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["14를 10과 4로 나누어 곱해요: 10 × 4 = 40, 4 × 4 = 16.","일의 자리 곱 4 × 4 = 16 — 1을 십의 자리로 올림해 더해요.","40 + 16 = 56 — 56은 어림한 10 × 4 = 40과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#9','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C1',2,'mc','auto','체조를 하루에 49분씩 6일 동안 했어요. 모두 몇 분 했는지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X13']::text[],true,'{"seq":9,"concept":"M3-1-u4-C1","difficulty":2,"kind":"mc","stem":"체조를 하루에 49분씩 6일 동안 했어요. 모두 몇 분 했는지 구하는 식은 어느 것인가요?","options":[{"t":"49 × 6","correct":true},{"t":"49 + 6","mis":"M3-1-u4-X01"},{"t":"6 × 6","mis":"M3-1-u4-X13"},{"t":"49 × 49","mis":"M3-1-u4-X13"}],"explanation":["49분씩 6번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 49 × 6."],"variant_rule":{"alt":[{"stem":"윗몸 일으키기를 하루에 92개씩 9일 동안 했어요. 모두 몇 개 했는지 구하는 식은 어느 것인가요?","options":[{"t":"92 × 9","correct":true},{"t":"92 + 9","mis":"M3-1-u4-X01"},{"t":"9 × 9","mis":"M3-1-u4-X13"},{"t":"92 × 92","mis":"M3-1-u4-X13"}],"explanation":["92개씩 9번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 92 × 9."],"asset":null},{"stem":"한 봉지에 사탕이 62개씩 9봉지 있어요. 사탕은 모두 몇 개인지 구하는 식은 어느 것인가요?","options":[{"t":"62 × 9","correct":true},{"t":"62 + 9","mis":"M3-1-u4-X01"},{"t":"9 × 9","mis":"M3-1-u4-X13"},{"t":"62 × 62","mis":"M3-1-u4-X13"}],"explanation":["62개씩 9번(묶음)이에요.","같은 수를 여러 번 더하는 상황이라 곱셈이에요.","한 묶음 수 × 묶음 수 = 62 × 9."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#10','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C2',2,'ox','auto','30 × 3 = 9예요.',ARRAY['M3-1-u4-X02']::text[],true,'{"seq":10,"concept":"M3-1-u4-C2","difficulty":2,"kind":"ox","stem":"30 × 3 = 9예요.","answer":"X","reason_options":[{"t":"30 × 3은 3 × 3의 10배라서","correct":true},{"t":"3 × 3 = 9니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"mis":"M3-1-u4-X02","explanation":["3 × 3 = 9예요.","30은 3의 10배라 곱도 10배 — 90이에요.","0을 빠뜨리면 십 모형 9개를 낱개 9개로 센 셈이에요."],"variant_rule":{"alt":[{"stem":"90 × 6 = 54예요.","answer":"X","reason_options":[{"t":"90 × 6은 9 × 6의 10배라서","correct":true},{"t":"9 × 6 = 54니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["9 × 6 = 54예요.","90은 9의 10배라 곱도 10배 — 540이에요.","0을 빠뜨리면 십 모형 54개를 낱개 54개로 센 셈이에요."],"asset":null},{"stem":"90 × 3 = 27이에요.","answer":"X","reason_options":[{"t":"90 × 3은 9 × 3의 10배라서","correct":true},{"t":"9 × 3 = 27이니까 0은 안 써도 되어서","mis":"M3-1-u4-X02"}],"explanation":["9 × 3 = 27이에요.","90은 9의 10배라 곱도 10배 — 270이에요.","0을 빠뜨리면 십 모형 27개를 낱개 27개로 센 셈이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#11','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C3',2,'sa','auto','31 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-1-u4-C3","difficulty":2,"kind":"sa","stem":"31 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 1 × 2 = 2 → 2를 써요.","31 × 2 = 62 — 일의 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["","","3","1"],["×","","","2"],["","","6",null]]},"variant_rule":{"alt":[{"stem":"14 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 1 × 2 = 2 → 2를 써요.","14 × 2 = 28 — 십의 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["","","1","4"],["×","","","2"],["","",null,"8"]]}},{"stem":"33 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 3 × 2 = 6 → 6을 써요.","33 × 2 = 66 — 일의 자리 숫자는 6이에요."],"asset":{"type":"expr_grid","rows":[["","","3","3"],["×","","","2"],["","","6",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#12','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C4',2,'mc','auto','96 × 9를 어림하면 약 얼마인가요?',ARRAY['M3-1-u4-X12','M3-1-u4-X11']::text[],true,'{"seq":12,"concept":"M3-1-u4-C4","difficulty":2,"kind":"mc","stem":"96 × 9를 어림하면 약 얼마인가요?","options":[{"t":"약 900","correct":true},{"t":"약 810","mis":"M3-1-u4-X12"},{"t":"약 100","mis":"M3-1-u4-X12"},{"t":"약 1000","mis":"M3-1-u4-X11"}],"explanation":["96은 가까운 몇십 100으로 어림해요.","100 × 9 = 900이에요.","그래서 96 × 9는 약 900이에요 — 실제 곱 864와 가까워요."],"variant_rule":{"alt":[{"stem":"62 × 8을 어림하면 약 얼마인가요?","options":[{"t":"약 480","correct":true},{"t":"약 560","mis":"M3-1-u4-X12"},{"t":"약 60","mis":"M3-1-u4-X12"},{"t":"약 540","mis":"M3-1-u4-X11"}],"explanation":["62는 가까운 몇십 60으로 어림해요.","60 × 8 = 480이에요.","그래서 62 × 8은 약 480이에요 — 실제 곱 496과 가까워요."],"asset":null},{"stem":"52 × 8을 어림하면 약 얼마인가요?","options":[{"t":"약 400","correct":true},{"t":"약 480","mis":"M3-1-u4-X12"},{"t":"약 50","mis":"M3-1-u4-X12"},{"t":"약 450","mis":"M3-1-u4-X11"}],"explanation":["52는 가까운 몇십 50으로 어림해요.","50 × 8 = 400이에요.","그래서 52 × 8은 약 400이에요 — 실제 곱 416과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#13','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C5',2,'sa','auto','71 × 7의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-1-u4-C5","difficulty":2,"kind":"sa","stem":"71 × 7의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["십의 자리 곱 7 × 7 = 49예요.","10을 넘은 4가 백의 자리로 올림해요.","71 × 7 = 497 — 백의 자리 숫자는 4예요."],"variant_rule":{"alt":[{"stem":"42 × 4의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["십의 자리 곱 4 × 4 = 16이에요.","10을 넘은 1이 백의 자리로 올림해요.","42 × 4 = 168 — 백의 자리 숫자는 1이에요."],"asset":null},{"stem":"51 × 6의 곱에서 백의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["십의 자리 곱 5 × 6 = 30이에요.","10을 넘은 3이 백의 자리로 올림해요.","51 × 6 = 306 — 백의 자리 숫자는 3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#14','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C6',2,'sa','auto','12 × 7을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u4-C6","difficulty":2,"kind":"sa","stem":"12 × 7을 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리 2 × 7 = 14예요.","일의 자리에 4를 쓰고 1을 십의 자리로 올림해요.","십의 자리 1 × 7 = 7에 1을 더해 8이에요."],"asset":{"type":"expr_grid","rows":[["","","1","2"],["×","","","7"],["","",null,null]]},"variant_rule":{"alt":[{"stem":"18 × 4를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["일의 자리 8 × 4 = 32예요.","일의 자리에 2를 쓰고 3을 십의 자리로 올림해요.","십의 자리 1 × 4 = 4에 3을 더해 7이에요."],"asset":{"type":"expr_grid","rows":[["","","1","8"],["×","","","4"],["","",null,null]]}},{"stem":"19 × 4를 세로셈으로 계산할 때 일의 자리에서 십의 자리로 올림한 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["일의 자리 9 × 4 = 36이에요.","일의 자리에 6을 쓰고 3을 십의 자리로 올림해요.","십의 자리 1 × 4 = 4에 3을 더해 7이에요."],"asset":{"type":"expr_grid","rows":[["","","1","9"],["×","","","4"],["","",null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#15','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C7',2,'mc','auto','76 × 7은 얼마인가요?',ARRAY['M3-1-u4-X08','M3-1-u4-X07','M3-1-u4-X09']::text[],true,'{"seq":15,"concept":"M3-1-u4-C7","difficulty":2,"kind":"mc","stem":"76 × 7은 얼마인가요?","options":[{"t":"532","correct":true},{"t":"492","mis":"M3-1-u4-X08"},{"t":"32","mis":"M3-1-u4-X07"},{"t":"772","mis":"M3-1-u4-X09"}],"explanation":["76을 70과 6으로 나누어 곱해요: 70 × 7 = 490, 6 × 7 = 42.","일의 자리 42 → 4 올림, 십의 자리 7 × 7 + 4 = 53 — 백의 자리까지 올림해요.","490 + 42 = 532 — 532는 어림한 80 × 7 = 560과 가까워요."],"variant_rule":{"alt":[{"stem":"97 × 5는 얼마인가요?","options":[{"t":"485","correct":true},{"t":"455","mis":"M3-1-u4-X08"},{"t":"85","mis":"M3-1-u4-X07"},{"t":"605","mis":"M3-1-u4-X09"}],"explanation":["97을 90과 7로 나누어 곱해요: 90 × 5 = 450, 7 × 5 = 35.","일의 자리 35 → 3 올림, 십의 자리 9 × 5 + 3 = 48 — 백의 자리까지 올림해요.","450 + 35 = 485 — 485는 어림한 100 × 5 = 500과 가까워요."],"asset":null},{"stem":"52 × 9는 얼마인가요?","options":[{"t":"468","correct":true},{"t":"458","mis":"M3-1-u4-X08"},{"t":"68","mis":"M3-1-u4-X07"},{"t":"548","mis":"M3-1-u4-X09"}],"explanation":["52를 50과 2로 나누어 곱해요: 50 × 9 = 450, 2 × 9 = 18.","일의 자리 18 → 1 올림, 십의 자리 5 × 9 + 1 = 46 — 백의 자리까지 올림해요.","450 + 18 = 468 — 468은 어림한 50 × 9 = 450과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#16','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C8',2,'sa','auto','열쇠고리를 만들어요. 꽃잎 한 장에 비즈가 16개씩 들어가요. 꽃잎 5장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-1-u4-C8","difficulty":2,"kind":"sa","stem":"열쇠고리를 만들어요. 꽃잎 한 장에 비즈가 16개씩 들어가요. 꽃잎 5장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["80"],"explanation":["같은 모양이 5장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 16개 × 5장 = 16 × 5.","16 × 5 = 80 — 비즈 80개가 필요해요."],"variant_rule":{"alt":[{"stem":"열쇠고리를 만들어요. 나비 날개 한 장에 비즈가 13개씩 들어가요. 나비 날개 7장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["91"],"explanation":["같은 모양이 7장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 13개 × 7장 = 13 × 7.","13 × 7 = 91 — 비즈 91개가 필요해요."],"asset":null},{"stem":"열쇠고리를 만들어요. 네잎클로버 잎 한 장에 비즈가 18개씩 들어가요. 네잎클로버 잎 4장에는 비즈가 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["72"],"explanation":["같은 모양이 4장 반복돼요 — 곱셈으로 한 번에 구해요.","한 장의 비즈 18개 × 4장 = 18 × 4.","18 × 4 = 72 — 비즈 72개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#17','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C2',3,'error','auto','20 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X02','M3-1-u4-X15']::text[],true,'{"seq":17,"concept":"M3-1-u4-C2","difficulty":3,"kind":"error","stem":"20 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「20 × 8 = 16이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"서윤 — 「2 × 8 = 16의 10배야」","mis":"M3-1-u4-X15"},{"t":"하랑 — 「십 모형 2개씩 8묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["2 × 8 = 16의 10배예요.","20 × 8 = 160이에요.","도윤은 0을 빠뜨려 16이라고 말했어요."],"variant_rule":{"alt":[{"stem":"30 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「30 × 4 = 12야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"하랑 — 「3 × 4 = 12의 10배야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「십 모형 3개씩 4묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["3 × 4 = 12의 10배예요.","30 × 4 = 120이에요.","태오는 0을 빠뜨려 12라고 말했어요."],"asset":null},{"stem":"10 × 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「10 × 6 = 6이야」","correct":true,"mis_target":"M3-1-u4-X02"},{"t":"도윤 — 「1 × 6 = 6의 10배야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「십 모형 1개씩 6묶음이야」","mis":"M3-1-u4-X15"}],"explanation":["1 × 6 = 6의 10배예요.","10 × 6 = 60이에요.","지유는 0을 빠뜨려 6이라고 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#18','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C3',3,'error','auto','44 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u4-X04','M3-1-u4-X15']::text[],true,'{"seq":18,"concept":"M3-1-u4-C3","difficulty":3,"kind":"error","stem":"44 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「44 × 2 = 48이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"서윤 — 「44 × 2 = 88이야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「어림하면 약 80이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 4 × 2 = 8, 십의 자리 4 × 2 = 8(십)이에요.","44 × 2 = 88이에요.","도윤은 48로 잘못 구했어요."],"variant_rule":{"alt":[{"stem":"11 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「11 × 3 = 13이야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"시우 — 「11 × 3 = 33이야」","mis":"M3-1-u4-X15"},{"t":"은우 — 「10 × 3 = 30, 1 × 3 = 3, 더하면 33이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 1 × 3 = 3, 십의 자리 1 × 3 = 3(십)이에요.","11 × 3 = 33이에요.","서윤은 13으로 잘못 구했어요."],"asset":null},{"stem":"41 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「41 × 2 = 42야」","correct":true,"mis_target":"M3-1-u4-X04"},{"t":"하랑 — 「41 × 2 = 82야」","mis":"M3-1-u4-X15"},{"t":"태오 — 「어림하면 약 80이야」","mis":"M3-1-u4-X15"}],"explanation":["일의 자리 1 × 2 = 2, 십의 자리 4 × 2 = 8(십)이에요.","41 × 2 = 82예요.","시우는 42로 잘못 구했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#19','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C4',3,'ox','auto','62 × 4를 계산했더니 48이 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-1-u4-X12']::text[],true,'{"seq":19,"concept":"M3-1-u4-C4","difficulty":3,"kind":"ox","stem":"62 × 4를 계산했더니 48이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 240과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"mis":"M3-1-u4-X12","explanation":["62를 60으로 어림하면 약 240이에요.","48은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 62 × 4 = 248이에요."],"variant_rule":{"alt":[{"stem":"91 × 4를 계산했더니 64가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 360과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["91을 90으로 어림하면 약 360이에요.","64는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 91 × 4 = 364예요."],"asset":null},{"stem":"61 × 2를 계산했더니 22가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 120과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-1-u4-X12"}],"explanation":["61을 60으로 어림하면 약 120이에요.","22는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 61 × 2 = 122예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#20','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C5',3,'mc','auto','양치질을 한 달에 81번씩 5달 동안 빠짐없이 했어요. 모두 몇 번 했나요?',ARRAY['M3-1-u4-X01','M3-1-u4-X07','M3-1-u4-X06']::text[],true,'{"seq":20,"concept":"M3-1-u4-C5","difficulty":3,"kind":"mc","stem":"양치질을 한 달에 81번씩 5달 동안 빠짐없이 했어요. 모두 몇 번 했나요?","options":[{"t":"405번","correct":true},{"t":"86번","mis":"M3-1-u4-X01"},{"t":"5번","mis":"M3-1-u4-X07"},{"t":"400번","mis":"M3-1-u4-X06"}],"explanation":["81번씩 5번(묶음) — 곱셈식 81 × 5로 세워요.","십의 자리 곱 80 × 5 = 400 — 백의 자리로 올림해요.","81 × 5 = 405 — 모두 405번이에요."],"variant_rule":{"alt":[{"stem":"색종이를 한 명에게 53장씩 2명에게 나누어 주었어요. 모두 몇 장인가요?","options":[{"t":"106장","correct":true},{"t":"55장","mis":"M3-1-u4-X01"},{"t":"6장","mis":"M3-1-u4-X07"},{"t":"100장","mis":"M3-1-u4-X06"}],"explanation":["53장씩 2번(묶음) — 곱셈식 53 × 2로 세워요.","십의 자리 곱 50 × 2 = 100 — 백의 자리로 올림해요.","53 × 2 = 106 — 모두 106장이에요."],"asset":null},{"stem":"걷기 운동을 하루에 81분씩 2일 동안 했어요. 모두 몇 분 걸었나요?","options":[{"t":"162분","correct":true},{"t":"83분","mis":"M3-1-u4-X01"},{"t":"62분","mis":"M3-1-u4-X07"},{"t":"160분","mis":"M3-1-u4-X06"}],"explanation":["81분씩 2번(묶음) — 곱셈식 81 × 2로 세워요.","십의 자리 곱 80 × 2 = 160 — 백의 자리로 올림해요.","81 × 2 = 162 — 모두 162분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#21','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C6',3,'error','auto','27 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u4-X09','M3-1-u4-X15']::text[],true,'{"seq":21,"concept":"M3-1-u4-C6","difficulty":3,"kind":"error","stem":"27 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"지유 — 「올림한 1을 십의 자리 2에 먼저 더해 3 × 2 — 답은 64야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"하린 — 「2 × 2 = 4에 올림한 1을 더해 5 — 답은 54야」","mis":"M3-1-u4-X15"},{"t":"시우 — 「20 × 2 = 40, 7 × 2 = 14, 더하면 54야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","2 × 2 = 4, + 1 = 5 — 27 × 2 = 54예요.","지유는 먼저 더하고 곱해 64가 나왔어요."],"variant_rule":{"alt":[{"stem":"28 × 3을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시우 — 「올림한 2를 십의 자리 2에 먼저 더해 4 × 3 — 답은 124야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"하린 — 「2 × 3 = 6에 올림한 2를 더해 8 — 답은 84야」","mis":"M3-1-u4-X15"},{"t":"서윤 — 「20 × 3 = 60, 8 × 3 = 24, 더하면 84야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","2 × 3 = 6, + 2 = 8 — 28 × 3 = 84예요.","시우는 먼저 더하고 곱해 124가 나왔어요."],"asset":null},{"stem":"13 × 7을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은우 — 「올림한 2를 십의 자리 1에 먼저 더해 3 × 7 — 답은 211이야」","correct":true,"mis_target":"M3-1-u4-X09"},{"t":"태오 — 「1 × 7 = 7에 올림한 2를 더해 9 — 답은 91이야」","mis":"M3-1-u4-X15"},{"t":"도윤 — 「10 × 7 = 70, 3 × 7 = 21, 더하면 91이야」","mis":"M3-1-u4-X15"}],"explanation":["올림한 수는 십의 자리를 곱한 다음에 더해요.","1 × 7 = 7, + 2 = 9 — 13 × 7 = 91이에요.","은우는 먼저 더하고 곱해 211이 나왔어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#22','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C7',3,'mc','auto','길이가 33cm인 골판지 4개를 겹치지 않게 이었어요. 모두 몇 cm인가요?',ARRAY['M3-1-u4-X01','M3-1-u4-X08','M3-1-u4-X07']::text[],true,'{"seq":22,"concept":"M3-1-u4-C7","difficulty":3,"kind":"mc","stem":"길이가 33cm인 골판지 4개를 겹치지 않게 이었어요. 모두 몇 cm인가요?","options":[{"t":"132cm","correct":true},{"t":"37cm","mis":"M3-1-u4-X01"},{"t":"122cm","mis":"M3-1-u4-X08"},{"t":"32cm","mis":"M3-1-u4-X07"}],"explanation":["33cm씩 4번(묶음) — 곱셈식 33 × 4로 세워요.","일의 자리 12 → 1 올림, 십의 자리 3 × 4 + 1 = 13 — 백의 자리까지 올림해요.","33 × 4 = 132 — 모두 132cm예요."],"variant_rule":{"alt":[{"stem":"양치질을 한 달에 44번씩 5달 동안 빠짐없이 했어요. 모두 몇 번 했나요?","options":[{"t":"220번","correct":true},{"t":"49번","mis":"M3-1-u4-X01"},{"t":"200번","mis":"M3-1-u4-X08"},{"t":"20번","mis":"M3-1-u4-X07"}],"explanation":["44번씩 5번(묶음) — 곱셈식 44 × 5로 세워요.","일의 자리 20 → 2 올림, 십의 자리 4 × 5 + 2 = 22 — 백의 자리까지 올림해요.","44 × 5 = 220 — 모두 220번이에요."],"asset":null},{"stem":"철봉에 한 번에 46초씩 3번 매달렸어요. 모두 몇 초 매달렸나요?","options":[{"t":"138초","correct":true},{"t":"49초","mis":"M3-1-u4-X01"},{"t":"128초","mis":"M3-1-u4-X08"},{"t":"38초","mis":"M3-1-u4-X07"}],"explanation":["46초씩 3번(묶음) — 곱셈식 46 × 3으로 세워요.","일의 자리 18 → 1 올림, 십의 자리 4 × 3 + 1 = 13 — 백의 자리까지 올림해요.","46 × 3 = 138 — 모두 138초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#23','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C8',4,'mc','auto','나비 날개 한 장의 비즈는 9개씩 3줄과 5개씩 4줄이에요. 날개 6장을 만들려면 비즈가 모두 몇 개 필요한가요?',ARRAY['M3-1-u4-X14','M3-1-u4-X01']::text[],true,'{"seq":23,"concept":"M3-1-u4-C8","difficulty":4,"kind":"mc","stem":"나비 날개 한 장의 비즈는 9개씩 3줄과 5개씩 4줄이에요. 날개 6장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"282개","correct":true},{"t":"162개","mis":"M3-1-u4-X14"},{"t":"120개","mis":"M3-1-u4-X14"},{"t":"53개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 9 × 3 + 5 × 4 = 27 + 20 = 47개.","날개 6장: 47 × 6.","47 × 6 = 282 — 비즈 282개가 필요해요."],"variant_rule":{"alt":[{"stem":"나비 날개 한 장의 비즈는 9개씩 2줄과 6개씩 5줄이에요. 날개 3장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"144개","correct":true},{"t":"54개","mis":"M3-1-u4-X14"},{"t":"90개","mis":"M3-1-u4-X14"},{"t":"51개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 9 × 2 + 6 × 5 = 18 + 30 = 48개.","날개 3장: 48 × 3.","48 × 3 = 144 — 비즈 144개가 필요해요."],"asset":null},{"stem":"나비 날개 한 장의 비즈는 8개씩 4줄과 5개씩 3줄이에요. 날개 5장을 만들려면 비즈가 모두 몇 개 필요한가요?","options":[{"t":"235개","correct":true},{"t":"160개","mis":"M3-1-u4-X14"},{"t":"75개","mis":"M3-1-u4-X14"},{"t":"52개","mis":"M3-1-u4-X01"}],"explanation":["날개 한 장: 8 × 4 + 5 × 3 = 32 + 15 = 47개.","날개 5장: 47 × 5.","47 × 5 = 235 — 비즈 235개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#24','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C7',4,'mc','auto','곱이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u4-X15','M3-1-u4-X11']::text[],true,'{"seq":24,"concept":"M3-1-u4-C7","difficulty":4,"kind":"mc","stem":"곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"46 × 7","correct":true},{"t":"94 × 3","mis":"M3-1-u4-X15"},{"t":"19 × 9","mis":"M3-1-u4-X11"},{"t":"49 × 6","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","46 × 7 = 322, 94 × 3 = 282, 19 × 9 = 171, 49 × 6 = 294.","곱이 가장 큰 것은 46 × 7 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"24 × 8","correct":true},{"t":"29 × 5","mis":"M3-1-u4-X11"},{"t":"33 × 4","mis":"M3-1-u4-X11"},{"t":"56 × 2","mis":"M3-1-u4-X15"}],"explanation":["하나씩 곱을 구해요.","24 × 8 = 192, 29 × 5 = 145, 33 × 4 = 132, 56 × 2 = 112.","곱이 가장 큰 것은 24 × 8 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"47 × 3","correct":true},{"t":"58 × 2","mis":"M3-1-u4-X11"},{"t":"66 × 2","mis":"M3-1-u4-X15"},{"t":"12 × 9","mis":"M3-1-u4-X11"}],"explanation":["하나씩 곱을 구해요.","47 × 3 = 141, 58 × 2 = 116, 66 × 2 = 132, 12 × 9 = 108.","곱이 가장 큰 것은 47 × 3 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u4_review_d#25','math',3,1,'u4','','g3_1_math_u4_review_d','unit_review','M3-1-u4-C5',4,'essay','teacher','한 봉지에 사탕이 63개씩 3봉지 있어요. 63 × 3을 세로셈으로 계산하는 방법을 쓰고, 백의 자리 숫자가 어떻게 생겼는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u4-C5","difficulty":4,"kind":"essay","stem":"한 봉지에 사탕이 63개씩 3봉지 있어요. 63 × 3을 세로셈으로 계산하는 방법을 쓰고, 백의 자리 숫자가 어떻게 생겼는지 설명해 보세요.","answer_guide":{"answer":"예: 일의 자리 3 × 3 = 9를 쓴다. 십의 자리 6 × 3 = 18은 180을 뜻하므로 십의 자리에 8, 백의 자리에 1을 쓴다. 답은 189개이다.","scoring_points":["일의 자리 9를 구했는가","18에서 백의 자리 1을 올림했다고 설명했는가","189를 구했는가"]},"explanation":["3 × 3 = 9.","6 × 3 = 18 → 백 1, 십 8.","63 × 3 = 189."],"asset":{"type":"expr_grid","rows":[["","","6","3"],["×","","","3"],["","1","8","9"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
